window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0102", [{"word":"elevation","ipa_uk":"/ˌelɪˈveɪʃən/","ipa_us":"/ˌeləˈveɪʃən/","definition_zh":"海拔；提高；高地；立面图；晋升；仰角","definition_en":"the height of a place above sea level, or the act of raising something to a higher level","core_image":"一根测量杆从海平面被缓缓抬到山脊，刻度一路向上走","scene":"勘察队在山脚架好仪器，沿坡缓慢向上测量。Surveyors record the elevation of the ridge as two thousand metres.","sceneCN":"这里 elevation 指「某地高出海平面的海拔」（第 1 个义项：以海平面为基准量出的垂直高度）；句意为测量员记录这道山脊的海拔约为两千米。图中可辨识物件：水准仪、标尺、等高线地图、山脊。","pos":[{"tag":"n.","zh":"海拔；高度"},{"tag":"n.","zh":"提高；晋升；高地"},{"tag":"n.","zh":"（建筑的）立面图；仰角"}],"collocations":[{"phrase":"elevation above sea level","zh":"海拔高度"},{"phrase":"elevation gain","zh":"（徒步、爬山的）累计爬升"},{"phrase":"elevation drawing","zh":"立面图"},{"phrase":"elevation of the sun","zh":"太阳高度角"},{"phrase":"elevation in rank","zh":"军衔或职位的晋升"},{"phrase":"elevation of temperature","zh":"体温或气温升高"}],"forms":[{"label":"复数","form":"elevations"},{"label":"形容词（高程的；立面的）","form":"elevational"},{"label":"动词（抬高；提升）","form":"elevate"}],"derivatives":[{"word":"elevate","pos":"v.","zh":"抬高；提升；使振奋"},{"word":"elevated","pos":"adj.","zh":"高起的；高架的；崇高的"},{"word":"elevator","pos":"n.","zh":"电梯；升降机；升降舵"},{"word":"elevational","pos":"adj.","zh":"高程的；立面的"}],"senses":[{"no":"01","title":"Height above sea level","titleCN":"海拔：高出海平面的高度","definition":"the height of a place or object measured from sea level","definitionCN":"某地或某物以海平面为基准量出的高度","example":"The village sits at an elevation of eighteen hundred metres.","exampleCN":"这个村子坐落在海拔一千八百米处。","why":"E- 'out, upward' plus levare 'to raise' gives 'a raising up'; measured from the sea, that raised distance is the elevation.","whyCN":"e-「向外、向上」加 levare「抬起」构成「被举起」；以海面为起点量这段被举起的高度，就是海拔。"},{"no":"02","title":"The act of raising something","titleCN":"提高：把东西抬到更高处","definition":"the act or result of lifting something to a higher position","definitionCN":"把某物抬到更高位置的动作或结果","example":"The elevation of the platform took three cranes.","exampleCN":"把平台抬高用了三台起重机。","why":"The noun keeps the literal movement of the verb elevate: an object is moved upward.","whyCN":"这个名词保留了动词 elevate 的字面动作：物体被向上移动。"},{"no":"03","title":"A raised piece of ground","titleCN":"高地：高出周围地面的隆起","definition":"a hill or raised area of land standing above its surroundings","definitionCN":"高出周围地面的小山或隆起地块","example":"The old church stands on a slight elevation above the marsh.","exampleCN":"那座老教堂坐落在湿地上方一处略高的地方。","why":"A patch of land that has been raised, geologically or simply by contrast, is called an elevation because it stands above the flat ground.","whyCN":"地块相对四周被抬高，无论成因如何，都因高出平地而被称为 elevation。"},{"no":"04","title":"Angle above the horizon","titleCN":"仰角：视线在水平线以上的夹角","definition":"the angle between an object in the sky and the horizontal, measured upward","definitionCN":"天空中某物体与水平面之间向上量出的夹角","example":"The astronomer measured the elevation of the star before dawn.","exampleCN":"天文学家在黎明前测量了那颗星的仰角。","why":"Surveying lifts a sight line from the level horizon toward a target, so the angle of that lift is also an elevation.","whyCN":"测量时把视线从水平面向目标抬起，这条抬起的角度同样叫 elevation。"},{"no":"05","title":"Architectural facade drawing","titleCN":"立面图：建筑外墙的正投影图","definition":"a scale drawing that shows the front or side of a building as seen straight on","definitionCN":"从正面或侧面正对建筑画出的按比例图纸","example":"The architect sent the council a front elevation of the new library.","exampleCN":"建筑师向市政会提交了新图书馆的正立面图。","why":"The facade is drawn as if the building had been lifted and laid flat toward the viewer; French architectural usage gave this sense to English.","whyCN":"立面图把建筑外表面「抬起、摊平」正对观者；这一义项经法语建筑用语进入英语。"},{"no":"06","title":"Promotion in rank or status","titleCN":"晋升：地位被抬到更高一级","definition":"the act of raising someone to a higher rank, office or dignity","definitionCN":"把某人提升到更高军衔、职位或地位的举动","example":"Her elevation to the board surprised no one.","exampleCN":"她被提升进董事会，谁都不觉得意外。","why":"A person is metaphorically lifted from a lower place in a hierarchy to a higher one, so the same raising verb serves social rank.","whyCN":"人被比喻性地从层级较低处抬到较高处，这个「抬起」动词因此也用于社会地位。"},{"no":"07","title":"Increase in amount or level","titleCN":"升高：数值或强度的上升","definition":"an increase in the amount or intensity of something measured","definitionCN":"某可测量事物在数量或强度上的上升","example":"Doctors watched the elevation of his blood pressure.","exampleCN":"医生们关注着他血压的升高。","why":"A reading that climbs is a value raised above its earlier level, which extends the physical 'raise' to numbers.","whyCN":"读数向上爬升，就是数值被抬到高于原先的水平，物理的「抬起」由此延伸到数字。"},{"no":"08","title":"Lofty quality of style or thought","titleCN":"高远：文风或思想境界的提升","definition":"a dignified or noble quality in language, thought or feeling","definitionCN":"语言、思想或情感中庄重崇高的品质","example":"The sermon was praised for the elevation of its language.","exampleCN":"这篇布道因语言格调高远而受到称赞。","why":"The medieval religious sense of raising the mind toward higher things survives in talk about elevated style and thought.","whyCN":"中世纪宗教语境中「把心灵引向更高之物」的用法，留存为今天说文体与思想「高远」。"}],"etymology":{"intro":{"en":"Elevation comes through French from Latin elevatio, a noun of action from elevare 'to raise'. The verb is built from a prefix of upward movement and a root meaning 'light, to lift'. Dates are approximate.","cn":"elevation 经法语来自拉丁 elevatio，是动词 elevare「举起」的动名词；该动词由表示向上移动的前缀与「轻、抬起」的词根构成。年代均为约数。"},"items":[{"era":"LATIN LEVIS","en":"Levare 'to lift, raise' was formed on levis 'light, not heavy'; lifting is what one does with something light. The link is generally accepted, while the deeper Indo-European source of levis is reconstructed as a 'light, nimble' root.","cn":"levare「举起、抬起」由 levis「轻的、不重的」构成；轻的东西才容易被抬起。这一联系一般认为是可靠的，而 levis 在印欧语中更深的来源则属重构形式。"},{"era":"LATIN ELEVARE","en":"The prefix e- (from ex-) 'out, upward' plus levare produced elevare 'to raise up, lift, relieve'.","cn":"前缀 e-（源自 ex-）表示「向外、向上」，加 levare 构成 elevare「举起、抬高、减轻」。"},{"era":"LATIN ELEVATIO","en":"Elevatio, elevationis (feminine, third declension) is the action noun: 'a lifting up, a raising'.","cn":"elevatio（阴性，第三变格）是动作名词，意为「举起、抬高」。"},{"era":"OLD FRENCH AND ENGLISH","en":"Old French elevation carried both the physical and the religious sense of raising the mind; English borrowed it in the fourteenth century.","cn":"古法语 elevation 同时带有物理上的「举起」与宗教上的「使心灵升华」两义；英语在 14 世纪借入。"},{"era":"SURVEYING SENSE","en":"The modern 'height above sea level' sense belongs to surveying and cartography from the eighteenth and nineteenth centuries; no precise first citation is recorded.","cn":"现代「高出海平面的高度」义属于 18 至 19 世纪的测量与制图学；确切的最早书证未见记载。"},{"era":"UNCERTAIN FIRST DATES","en":"Source uncertain (first dates only): the architectural sense of a facade drawing is attested later than the general noun, but its exact entry date in English is unsettled. The Latin root itself is not in doubt.","cn":"来源不确定（仅首见年代）：立面图义晚于一般名词义出现，但其进入英语的确切年代无定论。拉丁词根本身并无争议。"}]},"similar":{"note":{"en":"Group one gathers words that look close to elevation; group two gathers words that also name a height but measure it differently.","cn":"第一组是外形与 elevation 接近的词；第二组是同样表示高度、但测量基准不同的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"elevator","ipa":"/ˈelɪveɪtə/","tag":"same family, different suffix","definition":"Elevate plus -or 'one that does': the machine that raises people or goods, not the height itself.","definitionCN":"elevate 加 -or「做某事者」：指把人或货抬起来的机器，而不是高度本身。"},{"word":"levitation","ipa":"/ˌlevɪˈteɪʃn/","tag":"shares the lift root","definition":"From Latin levis 'light' through levitas: the act of rising or floating, with no reference to a measured altitude.","definitionCN":"经拉丁 levitas 来自 levis「轻」：指升空或悬浮，与量出的高度无关。"},{"word":"alleviate","ipa":"/əˈliːvieɪt/","tag":"prefix changes direction","definition":"Ad- 'toward' plus levare 'lighten': to make pain or a burden lighter, not to raise a place.","definitionCN":"ad-「朝向」加 levare「使轻」：减轻痛苦或负担，而非把地方抬高。"},{"word":"elation","ipa":"/ɪˈleɪʃn/","tag":"sounds like, different root","definition":"From Latin efferre 'carry away, lift up' in the sense of spirits being carried high; it is a feeling, not a height.","definitionCN":"来自拉丁 efferre「带走、举起」中「情绪被抬高」的用法；指心情，不指高度。"}]},{"heading":"NEAR MEANING","entries":[{"word":"altitude","ipa":"/ˈæltɪtjuːd/","tag":"height above a reference","definition":"The vertical height of an object or aircraft above a chosen level; elevation usually measures land against sea level.","definitionCN":"物体或飞机高出某一选定基准的垂直高度；elevation 通常指陆地相对海平面的高度。"},{"word":"height","ipa":"/haɪt/","tag":"general vertical measure","definition":"The everyday word for how tall or how high something is, with no technical baseline.","definitionCN":"日常用词，指某物有多高，不含技术性的基准面。"},{"word":"uplift","ipa":"/ˈʌplɪft/","tag":"geological raising","definition":"A mass of rock pushed upward by forces inside the earth; it names the process, while elevation can name the resulting height.","definitionCN":"地壳内力把岩体向上推；它指过程，而 elevation 可指结果的高度。"},{"word":"rise","ipa":"/raɪz/","tag":"plain upward movement","definition":"A simple increase in level or position; elevation is the measured or formal result of such a rise.","definitionCN":"指水平或位置的简单上升；elevation 是这种上升被测量或正式记录的结果。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real surveying terms and real relatives, not invented rhymes.","cn":"正常联想：真实的语素、真实的测量术语与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"E- 'up, out' + levare 'lift': the height you get after lifting a point above sea level.","cn":"e-「向上、向外」+ levare「抬起」：把一个点抬到海平面之上得到的高度。"},{"en":"The lever and levitate family share the 'lift, light' idea, so elevation belongs with things that rise.","cn":"lever 与 levitate 同带「抬起、轻」的意思，因此 elevation 与「上升」一类概念同族。"},{"en":"Hikers speak of elevation gain, the total climbing on a route.","cn":"徒步者说 elevation gain，指一条路线累计爬升的总高度。"},{"en":"In maps, elevation is measured against sea level; in flight, the same idea is usually called altitude.","cn":"地图上的 elevation 以海平面为基准；飞行中同一概念通常叫 altitude。"},{"en":"An architect's elevation is a flat drawing of a facade, seen straight on rather than from above.","cn":"建筑师的 elevation 是立面的平面图，正对墙面看，而不是从上往下看。"}],"abstract":[{"en":"Picture a stage lift carrying a speaker up into the light.","cn":"想象一台舞台升降机把演讲者抬到灯光里。"},{"en":"Picture a hill that is only a hill because the plain around it stays low.","cn":"想象一座山丘之所以是山丘，只因四周平原保持低矮。"},{"en":"Picture a sentence whose tone is lifted a register above ordinary speech.","cn":"想象一句话的语气比日常说话高出一个音区。"}]},"examples":[{"en":"The trail climbs to an elevation of three thousand metres.","cn":"这条步道爬升到海拔三千米。"},{"en":"A front elevation shows the building as a flat pattern of windows and doors.","cn":"正立面图把建筑呈现为门窗排列的平面图案。"},{"en":"His elevation to captain came after ten years of service.","cn":"服役十年后，他被晋升为上尉。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"e（向外、向上）+ lev（举起，如 lever 杠杆）+ ation（名词）→ 被举起来的高度 → 海拔、提升","word":"elevation"},"root":"拉丁 elevare「举起」= e-（向外、向上）+ levare「抬起」；levare 源于 levis「轻」。英语 elevation 经法语借入。","sensesIntro":{"en":"Eight senses follow one gesture: a point, a value or a person is lifted above a base line, and the result of that lift is the elevation.","cn":"八个义项沿同一个动作展开：把一个点、一个数值或一个人抬到基准线之上，抬起的结果就是 elevation。"},"semanticMap":{"core":{"en":"CORE IMAGE: a surveyor's rod lifted from sea level to a ridge, reading the vertical rise.","cn":"核心意象：一根测量杆从海平面被抬到山脊，读出这段垂直上升。"},"chain":["SEA LEVEL","VERTICAL RISE","MEASURED HEIGHT","RAISED GROUND","HIGH ANGLE","HIGH STANDING"],"branches":[{"senses":"S1 · S4","en":"MEASURE UP: from sea level or from the horizon, both senses give a number for height above a base.","cn":"向上量：无论以海平面还是以水平线为基准，两个义项都给出高出基准的数值。"},{"senses":"S2 · S7","en":"INCREASE: raising an object and raising a value are the same upward movement seen in space and in numbers.","cn":"上升：抬起物体与抬升数值，是空间与数字中同一个向上动作。"},{"senses":"S3","en":"GROUND: when the rise belongs to land, the result stands as a hill.","cn":"地面：当上升属于土地，结果就立成一座高地。"},{"senses":"S5 · S8","en":"FORM: a facade is a building lifted onto flat paper; elevated style is language lifted above the ordinary.","cn":"形式：立面图是把建筑抬到纸面上；高远的文风是把语言抬到日常之上。"},{"senses":"S6","en":"RANK: a person is lifted to a higher place in a hierarchy.","cn":"位阶：人被抬到层级中更高的位置。"}]},"affixes":{"intro":{"en":"Elevation is a Latin noun of action whose prefix, root and suffix all recur in English words, so the family can be read morpheme by morpheme.","cn":"elevation 是拉丁动作名词，其前缀、词根与后缀都在英语其它词中复现，因此这个词族可以按语素逐个读出。"},"latinIntro":{"en":"Latin levare 'to lift' yields elevate, elevation, elevator and alleviate, while levis 'light' also gives levity and levitation; ex- adds the upward direction.","cn":"拉丁 levare「举起」衍生 elevate、elevation、elevator 与 alleviate；levis「轻」还衍生 levity 与 levitation；ex- 增添向上的方向。"},"items":[{"word":"e-","structure":"ex- (Latin prefix, 'out, upward')","meaning":"out; upward","meaningCN":"向外；向上","example":"The prefix turns the root into a movement away from the ground.","exampleCN":"这个前缀把词根变成离开地面的动作。"},{"word":"levare","structure":"levare (Latin verb, first conjugation)","meaning":"to lift, raise, lighten","meaningCN":"抬起；举起；减轻","example":"The root supplies the physical lift.","exampleCN":"这个词根提供物理上的抬起。"},{"word":"-ation","structure":"-atio, -ationis (Latin suffix, action or result)","meaning":"action or result","meaningCN":"动作或结果","example":"The suffix turns the verb into the name of its result.","exampleCN":"后缀把动词变成其结果的名称。"},{"word":"elevation","structure":"e- + levare + -ation","meaning":"a raising; height","meaningCN":"抬高；高度","example":"The ridge's elevation was marked on the map.","exampleCN":"这道山脊的海拔被标在地图上。"},{"word":"elevate","structure":"e- + levare (verb)","meaning":"to raise","meaningCN":"抬高；提升","example":"The crane elevated the beam.","exampleCN":"起重机把横梁吊起。"},{"word":"elevator","structure":"elevate + -or (one that does)","meaning":"a lifting machine","meaningCN":"升降设备","example":"The elevator rose to the top floor.","exampleCN":"电梯升到顶层。"},{"word":"elevational","structure":"elevation + -al (relating to)","meaning":"relating to elevation","meaningCN":"高程的；立面的","example":"The plan includes elevational drawings.","exampleCN":"方案里包含立面图。"},{"word":"alleviate","structure":"al- (ad-, 'toward') + levare","meaning":"to lighten","meaningCN":"减轻","example":"The medicine alleviated the pain.","exampleCN":"药物减轻了疼痛。"},{"word":"levity","structure":"levis + -ity (state)","meaning":"lightness","meaningCN":"轻浮；轻率","example":"His levity annoyed the committee.","exampleCN":"他的轻率惹恼了委员会。"},{"word":"levitation","structure":"levitas + -ation","meaning":"rising into the air","meaningCN":"悬浮；升空","example":"The trick appeared to produce levitation.","exampleCN":"这个戏法看起来像让人悬浮。"}],"latinEntries":[{"word":"levare","structure":"levare, levavi, levatum (verb, first conjugation)","meaning":"to lift, raise, relieve","meaningCN":"抬起；举起；减轻"},{"word":"elevare","structure":"elevare, elevavi, elevatum (verb, first conjugation)","meaning":"to raise up, lift","meaningCN":"举起；抬高"},{"word":"elevatio","structure":"elevatio, elevationis (f., third declension)","meaning":"a lifting up","meaningCN":"举起；抬高"}]}},{"word":"altitude","ipa_uk":"/ˈæltɪtjuːd/","ipa_us":"/ˈæltɪtuːd/","definition_zh":"海拔；高度；高空；高海拔地区；（三角形的）高；地平纬度","definition_en":"the vertical height of something above a chosen level, especially above sea level","core_image":"一只测高气球从基准线垂直升到某个刻度，尺子只量竖直方向的距离","scene":"飞行员在高原机场准备下降，先扫了一眼仪表。The pilot checks the altitude reading before descending into the valley.","sceneCN":"这里 altitude 指「飞行器高出海平面的高度」（第 1 个义项：以海平面为基准的垂直高度）；句意为飞行员在进入山谷前先查看高度表读数。图中可辨识物件：驾驶舱、高度表、山谷、跑道。","pos":[{"tag":"n.","zh":"海拔；高度；高空"},{"tag":"n.","zh":"（几何图形的）高；地平纬度"}],"collocations":[{"phrase":"high altitude","zh":"高海拔；高空"},{"phrase":"altitude sickness","zh":"高原反应；高山病"},{"phrase":"cruising altitude","zh":"巡航高度"},{"phrase":"altitude of a triangle","zh":"三角形的高"},{"phrase":"altitude above sea level","zh":"海拔高度"},{"phrase":"altitude reading","zh":"高度表读数"}],"forms":[{"label":"复数","form":"altitudes"},{"label":"形容词（高度的）","form":"altitudinal"},{"label":"副词（按高度地）","form":"altitudinally"}],"derivatives":[{"word":"altitudinal","pos":"adj.","zh":"高度的；按海拔分布的"},{"word":"altimeter","pos":"n.","zh":"高度表；测高仪"},{"word":"altimetry","pos":"n.","zh":"测高学；高度测量"},{"word":"altimetrical","pos":"adj.","zh":"测高的"}],"senses":[{"no":"01","title":"Height above sea level","titleCN":"海拔：高出海平面的高度","definition":"the height of a place, mountain or aircraft above sea level","definitionCN":"地点、山峰或飞行器高出海平面的高度","example":"The plane levelled off at an altitude of ten thousand metres.","exampleCN":"飞机在一万米的高度上改平飞行。","why":"Altus 'high' plus -tudo 'state of being' gives 'highness'; measured from the sea, that highness is the altitude of the craft.","whyCN":"altus「高」加 -tudo「状态」构成「高」；以海面为起点量这份「高」，就是飞行器的高度。"},{"no":"02","title":"Height above any chosen reference","titleCN":"相对高度：高出某一基准的垂直距离","definition":"the vertical distance of an object above a stated reference level","definitionCN":"物体高出某一指定基准面的垂直距离","example":"The tower's altitude above the square is ninety metres.","exampleCN":"这座塔高出广场的高度是九十米。","why":"Once the reference is moved from the sea to a square or a floor, the same word measures a purely local height.","whyCN":"基准从海面换到广场或楼层后，同一个词就量出局部的高度。"},{"no":"03","title":"High regions or great height","titleCN":"高海拔地区；高空","definition":"a high place or region, often used in the plural for mountain zones","definitionCN":"高处或高海拔地带，常用复数指山区","example":"Few trees grow in the upper altitudes of the range.","exampleCN":"在这条山脉的高海拔地带，树木很少生长。","why":"The abstract 'highness' can be used for the places that are high, so the altitudes become a region rather than a measurement.","whyCN":"抽象的「高」可以转指高的地方，于是 the altitudes 成了一个地区，而不只是一个测量值。"},{"no":"04","title":"Perpendicular height of a triangle","titleCN":"（三角形的）高：从顶点到对边的垂直距离","definition":"the perpendicular distance from a vertex of a triangle to the opposite side","definitionCN":"三角形一个顶点到对边的垂直距离","example":"The area equals half the base multiplied by the altitude.","exampleCN":"面积等于底边乘以高的一半。","why":"Geometry keeps only the vertical drop from a point to a base line, which is the literal 'height' of the figure.","whyCN":"几何只保留从一点到底边的竖直距离，也就是图形字面上的「高」。"},{"no":"05","title":"Angular height of a celestial body","titleCN":"地平纬度：天体在地平线以上的角度","definition":"the angle of a star or the sun above the observer's horizon","definitionCN":"恒星或太阳在观测者地平线以上的角度","example":"Navigators measured the sun's altitude with a sextant.","exampleCN":"航海者用六分仪测量太阳的地平纬度。","why":"A star's 'height' in the sky is an angle rather than a distance, so altitude extends from metres to degrees.","whyCN":"天体在天空中的「高」是角度而不是距离，因此 altitude 从米延伸到度。"},{"no":"06","title":"Pressure altitude","titleCN":"压力高度：按气压换算出的飞行高度","definition":"the height shown by an altimeter when it is set to a standard pressure","definitionCN":"高度表按标准气压设定时显示的高度","example":"Air traffic control assigned the flight a pressure altitude of flight level three five zero.","exampleCN":"空管给这架航班指定了飞行高度层三五零的压力高度。","why":"In aviation the measured quantity is air pressure, converted into a height, so the word names a derived rather than a geometric altitude.","whyCN":"航空中实际测量的是气压，再换算成高度，因此这个词指的是推算高度而非几何高度。"},{"no":"07","title":"Lofty quality, literary","titleCN":"高远：思想或格调的高度（书面）","definition":"a noble or elevated quality of thought or expression, now chiefly literary","definitionCN":"思想或表达的高尚、高远，现多用于书面语","example":"The essay was admired for its altitude of thought.","exampleCN":"这篇文章因其思想高远而受到赞赏。","why":"The old figurative use treats intellectual height as if it were a measured altitude above ordinary minds.","whyCN":"旧的比喻用法把思想的高度当作高出常人之上的一段可测高度。"},{"no":"08","title":"Height of a solid figure","titleCN":"立体图形的高：两平行面之间的距离","definition":"the perpendicular distance between two parallel faces of a solid","definitionCN":"立体图形两个平行面之间的垂直距离","example":"The volume of the prism equals base area times its altitude.","exampleCN":"棱柱的体积等于底面积乘以其高。","why":"For a solid, the 'height' is the perpendicular gap between parallel faces, the same geometry raised into three dimensions.","whyCN":"对立体而言，「高」是两平行面之间的垂直间隔，是同一几何概念升入三维。"}],"etymology":{"intro":{"en":"Altitude goes back through French to Latin altitudo 'height', an abstract noun from altus 'high'. Altus itself is the participle of alere 'to nourish', literally 'grown tall'. Dates are approximate.","cn":"altitude 经法语上溯到拉丁 altitudo「高度」，由 altus「高的」构成的抽象名词；altus 本身是 alere「养育」的分词，字面为「被养大的」。年代均为约数。"},"items":[{"era":"LATIN ALERE","en":"Alere meant 'to nourish, feed, bring up'. Its participle altus developed the sense 'nourished, grown tall, high'. The derivation is generally accepted.","cn":"alere 意为「养育、喂养、抚养」，其分词 altus 发展出「被养大的、长高的、高的」之意；这一派生一般认为是可靠的。"},{"era":"LATIN ALTITUDO","en":"Altus plus the abstract suffix -tudo produced altitudo, 'height, depth, highness'.","cn":"altus 加抽象后缀 -tudo 构成 altitudo，意为「高度、深度、高」。"},{"era":"FRENCH AND ENGLISH","en":"Old French altitude passed the noun into English in the fourteenth century, first as a general word for height.","cn":"古法语 altitude 在 14 世纪把这个名词传入英语，最初泛指高度。"},{"era":"ASTRONOMY","en":"From the sixteenth and seventeenth centuries altitude named the angle of a heavenly body above the horizon, a sense still used in navigation.","cn":"16 至 17 世纪起，altitude 指天体在地平线以上的角度，这一义项至今仍用于航海。"},{"era":"AVIATION","en":"In the twentieth century aviation added pressure altitude and cruising altitude, where a pressure reading is converted into height.","cn":"20 世纪航空增添了 pressure altitude 与 cruising altitude，其中气压读数被换算成高度。"},{"era":"UNCERTAIN FIRST DATES","en":"Source uncertain (first dates only): the exact first English use of the geometric and aviation senses is not recorded, though the Latin root and its derivation are not in doubt.","cn":"来源不确定（仅首见年代）：几何义与航空义在英语中确切的首见年代未见记载，但拉丁词根及其派生并无争议。"}]},"similar":{"note":{"en":"Group one holds words that look or sound close to altitude; group two holds words that also answer the question 'how high?'","cn":"第一组是外形或读音接近 altitude 的词；第二组是同样回答「多高」的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"attitude","ipa":"/ˈætɪtjuːd/","tag":"one letter away","definition":"From aptitudo's neighbour in form but a different Latin source: a settled way of thinking or a bodily posture, not a height.","definitionCN":"外形只差一个字母，但拉丁来源不同：指固定的想法或身体姿态，与高度无关。"},{"word":"aptitude","ipa":"/ˈæptɪtjuːd/","tag":"same -tude ending","definition":"From aptus 'fitted': natural ability to learn something, with no vertical meaning.","definitionCN":"来自 aptus「合适的」：指学习某事的天然能力，不含垂直高度。"},{"word":"latitude","ipa":"/ˈlætɪtjuːd/","tag":"same -tude ending","definition":"From latus 'broad': distance north or south of the equator, measured in angles along the surface.","definitionCN":"来自 latus「宽」：沿地表用角度量出的南北距离。"},{"word":"longitude","ipa":"/ˈlɒŋɡɪtjuːd/","tag":"same -tude ending","definition":"From longus 'long': distance east or west of a prime meridian, again an angular measure.","definitionCN":"来自 longus「长」：相对本初子午线量出的东西距离，同样是角度。"}]},{"heading":"NEAR MEANING","entries":[{"word":"elevation","ipa":"/ˌelɪˈveɪʃən/","tag":"land against sea level","definition":"The height of land above sea level; altitude is the more general and more aeronautical term.","definitionCN":"陆地高出海平面的高度；altitude 更通用，也更常用于航空。"},{"word":"height","ipa":"/haɪt/","tag":"everyday word","definition":"The ordinary word for vertical size, with no technical reference level.","definitionCN":"表示竖直尺寸的日常词，不含技术基准面。"},{"word":"ceiling","ipa":"/ˈsiːlɪŋ/","tag":"aviation limit","definition":"The maximum altitude an aircraft can reach, or the height of the lowest cloud layer; it is a limit, not a position.","definitionCN":"飞机能达到的最大高度，或最低云层的高度；它是一个上限而非所在位置。"},{"word":"depth","ipa":"/depθ/","tag":"downward measure","definition":"Vertical distance below a surface; altitude is the matching measure upward.","definitionCN":"某表面以下的垂直距离，与向上的 altitude 相对应。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Latin root, real aviation phrases and real geometry, not invented rhymes.","cn":"正常联想：真实的拉丁词根、真实的航空短语与真实的几何概念，而非编造的顺口溜。"},"normal":[{"en":"Altus 'high' + -tudo 'state': the state of being high, measured from a base.","cn":"altus「高」+ -tudo「状态」：高的状态，从某一基准量起。"},{"en":"The altimeter and altimetry family all carry the same 'high' root.","cn":"altimeter 与 altimetry 词族都带同一个「高」的词根。"},{"en":"Altitude sickness appears when the body climbs too fast into thin air.","cn":"身体过快升入空气稀薄的高处，就会出现高原反应。"},{"en":"In a triangle the altitude is the perpendicular drop from a vertex to the opposite side.","cn":"三角形的高是从顶点向对边作的垂线。"},{"en":"Aviation separates altitude above sea level from height above the ground beneath the aircraft.","cn":"航空把相对海平面的高度与相对机下地面的高度区分开来。"}],"abstract":[{"en":"Picture a balloon on a string, with the string marked in metres from the ground up.","cn":"想象一只系着绳子的气球，绳上从地面向上标着米数。"},{"en":"Picture a star whose 'height' is really an angle you lift your eyes through.","cn":"想象一颗星，它的「高」其实是你抬眼所经过的角度。"},{"en":"Picture a mountain that exists only as the space between its peak and the sea.","cn":"想象一座山，它只作为峰顶与海面之间的那段距离而存在。"}]},"examples":[{"en":"Altitude affects how much oxygen the blood can carry.","cn":"海拔会影响血液能携带多少氧。"},{"en":"The altitude of the triangle is six centimetres.","cn":"这个三角形的高是六厘米。"},{"en":"The village lies at an altitude of two thousand metres.","cn":"这个村庄位于海拔两千米处。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"阿尔提（alti）像「高」的发音 + tude（状态）→ 高的状态 → 海拔、高度","word":"altitude"},"root":"拉丁 altitudo「高度」= altus「高的」（alere「养育」的分词）+ -tudo（状态）；英语 altitude 经法语借入。","sensesIntro":{"en":"Eight senses all answer 'how high?' but change the base: sea level, a local reference, a region, a geometric side, the horizon, a pressure setting, a style of thought and a solid's parallel faces.","cn":"八个义项都在回答「多高」，只是换了基准：海平面、局部参照、地区、几何底边、地平线、气压设定、思想格调与立体的平行面。"},"semanticMap":{"core":{"en":"CORE IMAGE: a measuring line dropped straight up from a base to a point, and the reading at the top.","cn":"核心意象：一条测量线从基准垂直向上拉到某点，顶端给出读数。"},"chain":["BASE LINE","VERTICAL LIFT","READING","HIGH GROUND","SKY ANGLE","HIGH THOUGHT"],"branches":[{"senses":"S1 · S2","en":"REFERENCE POINT: sea level or a local datum, the measurement is the same vertical gap.","cn":"参照点：无论海平面还是局部基准，量的都是同一段垂直间隔。"},{"senses":"S3 · S8","en":"SPACE THAT IS HIGH: a mountain zone and a solid's parallel faces both occupy a vertical extent.","cn":"高处的空间：山区与立体的平行面都占据一段竖直范围。"},{"senses":"S4","en":"FIGURE: a triangle's altitude is the perpendicular that turns a shape into an area.","cn":"图形：三角形的高是把形状化成面积的垂线。"},{"senses":"S5 · S6","en":"SKY AND AIR: stars are measured in angles, aircraft in pressure-derived metres.","cn":"天空与空气：恒星用角度量，飞机用气压换算的米数。"},{"senses":"S7","en":"MIND: intellectual height is treated as a measurable altitude above ordinary thought.","cn":"心灵：思想的高度被当作高出常人的可测海拔。"}]},"affixes":{"intro":{"en":"Altitude is built from a Latin root for 'high' and a suffix for 'state', and the same root recurs in measuring instruments and in music.","cn":"altitude 由表示「高」的拉丁词根与表示「状态」的后缀构成，同一词根还出现在测量仪器与音乐术语中。"},"latinIntro":{"en":"Latin altus 'high' (from alere 'nourish') yields altitude and altitudinal; with Greek metron 'measure' it also yields altimeter and altimetry, while Italian alto continues the same root.","cn":"拉丁 altus「高」（源于 alere「养育」）衍生 altitude 与 altitudinal；与希腊 metron「测量」结合又衍生 altimeter 与 altimetry，意大利语 alto 亦延续同一词根。"},"items":[{"word":"altus","structure":"altus (Latin adjective, 'high, deep')","meaning":"high; deep","meaningCN":"高的；深的","example":"The root names vertical extent in either direction.","exampleCN":"这个词根表示任一方向的竖直延伸。"},{"word":"-tudo","structure":"-tudo, -tudinis (Latin suffix, state or quality)","meaning":"state of being","meaningCN":"状态；性质","example":"The suffix turns 'high' into 'height'.","exampleCN":"后缀把「高」变成「高度」。"},{"word":"altitude","structure":"altus + -tudo","meaning":"height","meaningCN":"高度；海拔","example":"The peak's altitude is marked on the map.","exampleCN":"峰顶的海拔标在地图上。"},{"word":"altitudinal","structure":"altitude + -al (relating to)","meaning":"relating to height","meaningCN":"高度的；海拔的","example":"Species change along an altitudinal gradient.","exampleCN":"物种随海拔梯度而变化。"},{"word":"altimeter","structure":"altus + Greek metron 'measure'","meaning":"a height-measuring instrument","meaningCN":"高度表","example":"The altimeter showed a rapid climb.","exampleCN":"高度表显示快速爬升。"},{"word":"altimetry","structure":"altimeter + -y (practice or science)","meaning":"the science of height measurement","meaningCN":"测高学","example":"Satellite altimetry maps the ocean surface.","exampleCN":"卫星测高绘制海面形态。"},{"word":"alto","structure":"alto (Italian, from Latin altus)","meaning":"high voice or part","meaningCN":"高音；中高音","example":"She sings alto in the choir.","exampleCN":"她在合唱团唱中高音。"},{"word":"altocumulus","structure":"alto- 'high' + cumulus 'heap'","meaning":"a middle-level cloud","meaningCN":"高积云","example":"Altocumulus clouds streaked the morning sky.","exampleCN":"高积云划过清晨的天空。"},{"word":"altiplano","structure":"alto 'high' + plano 'plain'","meaning":"a high plateau","meaningCN":"高原","example":"The altiplano stretches between two ranges.","exampleCN":"高原在两道山脉之间延伸。"}],"latinEntries":[{"word":"altus","structure":"altus, alta, altum (adjective)","meaning":"high, tall, deep","meaningCN":"高的；高的；深的"},{"word":"altitudo","structure":"altitudo, altitudinis (f., third declension)","meaning":"height, depth","meaningCN":"高度；深度"},{"word":"alere","structure":"alere, alui, altum (verb, third conjugation)","meaning":"to nourish, bring up","meaningCN":"养育；抚养"}]}},{"word":"latitude","ipa_uk":"/ˈlætɪtjuːd/","ipa_us":"/ˈlætɪtuːd/","definition_zh":"纬度；纬度地区；自由度；活动余地；宽容度；宽度","definition_en":"the angular distance of a place north or south of the equator, or the freedom to act within limits","core_image":"地球仪上一条条与赤道平行的圈，把表面切成一层层南北的带","scene":"老船长在甲板上教学生用正午太阳与赤道比较。Sailors measure latitude by comparing the noon sun with the equator.","sceneCN":"这里 latitude 指「某地相对赤道的南北角距离」（第 1 个义项：以赤道为零度、按角度量出的南北位置）；句意为水手通过比较正午太阳与赤道来测定纬度。图中可辨识物件：六分仪、海图、太阳、地平线。","pos":[{"tag":"n.","zh":"纬度；纬度地区"},{"tag":"n.","zh":"自由度；活动余地；宽容度"},{"tag":"n.","zh":"宽度（古义、技术义）"}],"collocations":[{"phrase":"latitude and longitude","zh":"经纬度"},{"phrase":"high latitudes","zh":"高纬度地区"},{"phrase":"low latitudes","zh":"低纬度地区"},{"phrase":"degrees of latitude","zh":"纬度度数"},{"phrase":"give someone latitude","zh":"给某人自主空间"},{"phrase":"latitude of interpretation","zh":"解释上的自由余地"}],"forms":[{"label":"复数","form":"latitudes"},{"label":"形容词（纬度的；纵向的）","form":"latitudinal"},{"label":"副词（按纬度地）","form":"latitudinally"}],"derivatives":[{"word":"latitudinal","pos":"adj.","zh":"纬度的；沿纬度方向的"},{"word":"latitudinally","pos":"adv.","zh":"按纬度方向地"},{"word":"latitudinarian","pos":"adj./n.","zh":"宽纵的；宽容主义者"},{"word":"latitudinarianism","pos":"n.","zh":"宽纵主义"}],"senses":[{"no":"01","title":"Angular distance from the equator","titleCN":"纬度：相对赤道的南北角距离","definition":"the angular distance of a place north or south of the equator, measured in degrees","definitionCN":"某地相对赤道向南或向北的角距离，以度数计","example":"The island lies at a latitude of twenty degrees north.","exampleCN":"这座岛屿位于北纬二十度。","why":"Latin latitudo meant 'breadth'; on a globe the north-south breadth of the known world became an angle measured from the equator.","whyCN":"拉丁 latitudo 意为「宽度」；在地球仪上，已知世界的南北「宽度」变成了从赤道量起的角度。"},{"no":"02","title":"A region or band of the globe","titleCN":"纬度地区：由纬度划出的地带","definition":"a region of the earth identified by the latitude it occupies","definitionCN":"按所占纬度来指认的地球区域","example":"Coffee grows well in the warm latitudes near the equator.","exampleCN":"咖啡在赤道附近的温暖纬度带生长良好。","why":"Instead of a number, the word can name the band that the number marks, so 'the warm latitudes' means a zone, not a coordinate.","whyCN":"这个词不只给数字，也能指数字所标出的地带，因此 the warm latitudes 指一片区域而非坐标。"},{"no":"03","title":"Freedom to act or decide","titleCN":"自由度：行动与决定的余地","definition":"the freedom to choose how to act within a framework of rules","definitionCN":"在规则框架内选择如何行动的自由","example":"The new editor was given wide latitude in choosing stories.","exampleCN":"新编辑在选题上获得了很大的自由空间。","why":"A map coordinate can move within a range without leaving the map; freedom of action was pictured the same way, as room to move.","whyCN":"地图坐标可以在范围内移动而不越出图幅；行动自由被同样地想象成可活动的余量。"},{"no":"04","title":"Permitted range or tolerance","titleCN":"容许范围：可偏离的限度","definition":"the amount by which something may vary without breaking a rule or standard","definitionCN":"某事物在不违反规则或标准的前提下可偏离的幅度","example":"The specification allows a latitude of two millimetres in the cut.","exampleCN":"规格允许切割有两毫米的偏差。","why":"From room to move comes room to deviate: a tolerance is latitude expressed as an allowed error.","whyCN":"由「可活动」引申出「可偏离」：公差就是把余地换算成允许的误差。"},{"no":"05","title":"Exposure latitude in photography","titleCN":"曝光宽容度：底片可容忍的曝光范围","definition":"the range of exposure over which a film or sensor still gives a usable image","definitionCN":"胶片或传感器仍能给出可用影像的曝光范围","example":"Negative film has more exposure latitude than slide film.","exampleCN":"负片的曝光宽容度比反转片大。","why":"A photographic emulsion tolerates a range of light before it fails, exactly the 'permitted range' sense applied to light.","whyCN":"感光乳剂在失效前能容忍一定范围的光量，正是「容许范围」义用于光线。"},{"no":"06","title":"Breadth or width, archaic","titleCN":"宽度：横向量度（古义、技术义）","definition":"the breadth or width of a thing, now chiefly technical or historical","definitionCN":"事物的横向宽度，今多用于技术或历史语境","example":"The old survey recorded the latitude of the field as forty paces.","exampleCN":"旧时的测量记录这块地的宽度为四十步。","why":"This is the original Latin sense of latitudo 'breadth', preserved after the geographical sense took over everyday use.","whyCN":"这是拉丁 latitudo「宽度」的本义，在地理义占据日常用法之后仍被保留。"},{"no":"07","title":"Lines of latitude on a map","titleCN":"纬线：地图上与赤道平行的圈","definition":"a circle on a map or globe parallel to the equator, joining places of equal latitude","definitionCN":"地图或地球仪上与赤道平行、连接同纬度各点的圈","example":"The chart draws lines of latitude every ten degrees.","exampleCN":"这张海图每隔十度画一条纬线。","why":"The parallel is the visible mark of the measured angle, so 'latitude' can name the line as well as the number.","whyCN":"纬线是所量角度的可见标记，因此 latitude 既可指数值也可指这条线。"},{"no":"08","title":"Celestial latitude","titleCN":"黄纬：天体相对黄道的角距离","definition":"the angular distance of a celestial body north or south of the ecliptic","definitionCN":"天体相对黄道向北或向南的角距离","example":"Astronomers record the celestial latitude of each planet.","exampleCN":"天文学家记录每颗行星的黄纬。","why":"The same 'breadth' geometry was transferred to the sky, where the ecliptic serves as the baseline instead of the equator.","whyCN":"同一套「宽度」几何被搬到天上，只是基准由赤道换成了黄道。"}],"etymology":{"intro":{"en":"Latitude comes from Latin latitudo 'breadth, width', formed on latus 'broad'. The geographical sense is a later narrowing of that breadth to an angular distance. Dates are approximate.","cn":"latitude 来自拉丁 latitudo「宽度、广度」，由 latus「宽的」构成；地理义是后来把「广度」收窄为角距离。年代均为约数。"},"items":[{"era":"LATIN LATUS","en":"Latus meant 'broad, wide'; it is not the same word as latus, lateris 'side', although the two forms look alike in Latin dictionaries.","cn":"latus 意为「宽的、广的」；它与 latus, lateris「侧边」并非同一个词，尽管在拉丁词典里两个词形相近。"},{"era":"LATIN LATITUDO","en":"Latus plus -tudo gave latitudo, 'breadth, width, extent'.","cn":"latus 加 -tudo 构成 latitudo，意为「宽度、广度、范围」。"},{"era":"GEOGRAPHICAL NARROWING","en":"In sixteenth-century geography the 'breadth' of the known world became the north-south angular distance from the equator, the modern sense.","cn":"16 世纪地理学把已知世界的「广度」定为相对赤道的南北角距离，即现代义。"},{"era":"ASTRONOMY","en":"The same word was applied to the sky, where celestial latitude measures distance from the ecliptic rather than from the equator.","cn":"同一个词被用于天空，黄纬量的是相对黄道而非赤道的距离。"},{"era":"FIGURATIVE SCOPE","en":"From the idea of a range or extent came the senses 'freedom of action' and 'permitted tolerance' in the sixteenth and seventeenth centuries.","cn":"从「范围、幅度」的观念引申出 16 至 17 世纪的「行动自由」与「容许误差」两义。"},{"era":"UNCERTAIN FIRST DATES","en":"Source uncertain (first dates only): the photographic sense is twentieth-century, and no precise first citation is recorded for it; the Latin root is well established.","cn":"来源不确定（仅首见年代）：摄影义属 20 世纪，确切的最早书证未见记载；拉丁词根则已确立。"}]},"similar":{"note":{"en":"Group one holds the four -tude words most often confused on maps and in exams; group two holds words about range, room and breadth.","cn":"第一组是最容易在地图与考试中混淆的四个 -tude 词；第二组是关于范围、余地与宽度的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"longitude","ipa":"/ˈlɒŋɡɪtjuːd/","tag":"east-west partner","definition":"From longus 'long': the east-west coordinate, measured from a prime meridian, not from the equator.","definitionCN":"来自 longus「长」：相对本初子午线量出的东西坐标，不以赤道为基准。"},{"word":"altitude","ipa":"/ˈæltɪtjuːd/","tag":"vertical, not horizontal","definition":"From altus 'high': vertical height above a reference level, whether of land or an aircraft.","definitionCN":"来自 altus「高」：相对某基准的垂直高度，可指陆地或飞机。"},{"word":"attitude","ipa":"/ˈætɪtjuːd/","tag":"posture or outlook","definition":"A settled way of thinking or a bodily posture; its Latin source is aptitudo's neighbour actitudo, not latus.","definitionCN":"指固定的想法或身体姿态；其拉丁来源是 actitudo，与 latus 无关。"},{"word":"aptitude","ipa":"/ˈæptɪtjuːd/","tag":"natural ability","definition":"From aptus 'fit': the capacity to learn or do something, with no geographic sense.","definitionCN":"来自 aptus「合适」：学习或做某事的能力，不含地理意义。"}]},{"heading":"NEAR MEANING","entries":[{"word":"longitude","ipa":"/ˈlɒŋɡɪtjuːd/","tag":"the other coordinate","definition":"The east-west angle paired with latitude to fix a position on the globe.","definitionCN":"与纬度配对、用于确定地球位置的东西向角度。"},{"word":"scope","ipa":"/skəʊp/","tag":"room to act","definition":"The range covered by a plan, rule or activity; latitude adds the idea of permitted freedom.","definitionCN":"计划、规则或活动覆盖的范围；latitude 另带「被允许的自由」之意。"},{"word":"tolerance","ipa":"/ˈtɒlərəns/","tag":"allowed deviation","definition":"The permitted variation in a measurement or in behaviour; latitude is the older, broader word for such room.","definitionCN":"测量或行为上被允许的偏差；latitude 是更旧、更宽的说法。"},{"word":"breadth","ipa":"/bredθ/","tag":"width itself","definition":"The literal width of something; it is the original sense that latitude carried in Latin.","definitionCN":"事物实际的宽度；正是 latitude 在拉丁语中携带的本义。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real Latin 'breadth', real map lines and real figurative uses, not invented rhymes.","cn":"正常联想：真实的拉丁「宽度」、真实的地图线条与真实的比喻用法，而非编造的顺口溜。"},"normal":[{"en":"Latus 'broad' + -tude 'state': the breadth of the world, later measured as an angle from the equator.","cn":"latus「宽」+ -tude「状态」：世界的广度，后来变成从赤道量起的角度。"},{"en":"Latitude lines run east-west and measure north-south position; longitude lines do the opposite.","cn":"纬线东西走向，却量南北位置；经线正好相反。"},{"en":"The pair 'latitude and longitude' fixes any point on the globe.","cn":"纬度与经度这一对数值能定位地球上的任何一点。"},{"en":"Giving someone latitude means giving them room to choose within limits.","cn":"give someone latitude 指在限定的范围内给对方选择的余地。"},{"en":"Film photographers speak of exposure latitude, the range of light a negative can survive.","cn":"胶片摄影师说曝光宽容度，即负片能承受的光量范围。"}],"abstract":[{"en":"Picture a rubber band that can stretch only so far before it snaps.","cn":"想象一根橡皮筋，拉到一定程度就会断。"},{"en":"Picture a map with many horizontal belts, each one a different warmth.","cn":"想象一张地图上有许多水平地带，每一带温度不同。"},{"en":"Picture a ruler laid across the globe rather than along it.","cn":"想象一把尺横着放在地球上，而不是沿着地表。"}]},"examples":[{"en":"The ship's latitude was forty degrees south.","cn":"这艘船的纬度是南纬四十度。"},{"en":"Teachers are given latitude in how they organise their lessons.","cn":"教师在如何组织课程上享有自主空间。"},{"en":"Warm latitudes support a greater variety of plants.","cn":"温暖的纬度带能养活更多种类的植物。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"lat（宽，如 lateral 侧面的、latitudes 纬度）+ itude（状态）→ 地球的横向宽度 → 纬度、余地","word":"latitude"},"root":"拉丁 latitudo「宽度」= latus「宽的」+ -tudo（状态）；与 latus, lateris「侧边」不是同一个词。英语 latitude 经法语借入。","sensesIntro":{"en":"Eight senses grow from one Latin idea, 'breadth': the globe's north-south breadth, the bands it creates, the room a person has to act, the error a standard allows, the light a film tolerates, literal width, the drawn parallel, and the sky's version of the same measure.","cn":"八个义项都从拉丁「宽度」这一观念长出：地球的南北广度、由此划出的地带、人可行动的余地、标准允许的误差、胶片可容忍的光量、字面的宽度、画出的纬线，以及天空中的同一量度。"},"semanticMap":{"core":{"en":"CORE IMAGE: a band stretched across a sphere, wide in the north-south direction, then read as an angle.","cn":"核心意象：一条横跨球面的带子，在南北方向上有宽度，再被读成角度。"},"chain":["BREADTH","NORTH-SOUTH ANGLE","PARALLEL LINE","CLIMATE BAND","ROOM TO MOVE","ALLOWED RANGE"],"branches":[{"senses":"S1 · S7","en":"MEASURE AND MARK: the angle and the parallel line are the number and its visible trace.","cn":"测量与标记：角度与纬线，是数值与它的可见痕迹。"},{"senses":"S2 · S8","en":"BANDS OF THE SPHERE: one band is on the earth, the other is projected onto the sky.","cn":"球面上的带：一带在地球上，另一带投影到天空。"},{"senses":"S3 · S4","en":"ROOM: freedom to act and tolerance in a standard are the same slack measured in behaviour and in numbers.","cn":"余地：行动自由与标准公差，是同一段松紧在行为与数字上的度量。"},{"senses":"S5","en":"LIGHT: a film's exposure latitude is the permitted range applied to light.","cn":"光：胶片的曝光宽容度就是把容许范围用于光线。"},{"senses":"S6","en":"LITERAL WIDTH: the oldest sense survives as a technical word for breadth.","cn":"字面宽度：最古老的意义作为表示宽度的技术词留存下来。"}]},"affixes":{"intro":{"en":"Latitude is built on a Latin adjective for 'broad' plus a state suffix; the same root also appears in dilate, where the idea of widening is physical.","cn":"latitude 由表示「宽」的拉丁形容词加状态后缀构成；同一词根也出现在 dilate 中，那里「变宽」是物理动作。"},"latinIntro":{"en":"Latin latus 'broad' gives latitudo and latitude; the verb dilatare 'to spread out' comes from dis- plus latus and yields dilate, dilation and dilatory.","cn":"拉丁 latus「宽」衍生 latitudo 与 latitude；动词 dilatare「摊开」由 dis- 加 latus 构成，衍生 dilate、dilation 与 dilatory。"},"items":[{"word":"latus","structure":"latus (Latin adjective, 'broad, wide')","meaning":"broad; wide","meaningCN":"宽的；广的","example":"The root names extent across, not length along.","exampleCN":"这个词根指横向的幅度，而非纵向的长度。"},{"word":"-tudo","structure":"-tudo, -tudinis (Latin suffix, state)","meaning":"state or quality","meaningCN":"状态；性质","example":"The suffix makes 'broad' into 'breadth'.","exampleCN":"后缀把「宽」变成「宽度」。"},{"word":"latitude","structure":"latus + -tudo","meaning":"breadth; north-south angle","meaningCN":"纬度；宽度","example":"The latitude of the site is marked in degrees.","exampleCN":"该地点的纬度以度数标注。"},{"word":"latitudinal","structure":"latitude + -al (relating to)","meaning":"relating to latitude","meaningCN":"纬度的","example":"The forest changes along a latitudinal gradient.","exampleCN":"森林沿纬度梯度变化。"},{"word":"latitudinarian","structure":"latitude + -arian (one who holds)","meaning":"a person who allows broad interpretation","meaningCN":"宽容主义者","example":"The latitudinarian clergy avoided strict tests.","exampleCN":"宽容派教士避免严格的信条审查。"},{"word":"dilate","structure":"dis- 'apart' + latus 'wide'","meaning":"to widen","meaningCN":"扩张；扩大","example":"The pupil dilates in dim light.","exampleCN":"瞳孔在暗光中放大。"},{"word":"dilation","structure":"dilate + -ion (action)","meaning":"a widening","meaningCN":"扩张；扩大","example":"Dilation of the blood vessel improved flow.","exampleCN":"血管扩张改善了血流。"},{"word":"dilatory","structure":"dilator 'one who delays' + -y","meaning":"slow, delaying","meaningCN":"拖延的","example":"The dilatory reply cost them the contract.","exampleCN":"拖延的答复让他们失去了合同。"}],"latinEntries":[{"word":"latus","structure":"latus, lata, latum (adjective)","meaning":"broad, wide","meaningCN":"宽的；广的"},{"word":"latitudo","structure":"latitudo, latitudinis (f., third declension)","meaning":"breadth, width","meaningCN":"宽度；广度"},{"word":"dilatare","structure":"dilatare, dilatavi, dilatatum (verb, first conjugation)","meaning":"to spread out, widen","meaningCN":"摊开；加宽"}]}},{"word":"longitude","ipa_uk":"/ˈlɒŋɡɪtjuːd/","ipa_us":"/ˈlɑːŋɡɪtuːd/","definition_zh":"经度；经线；经度位置；（古）长度","definition_en":"the angular distance of a place east or west of a prime meridian, or, in older use, length","core_image":"地球仪上一圈圈从北极到南极的竖线，把表面切成一条条东西的瓣","scene":"航海者在船舱里把当地时间与格林尼治时间对照。A navigator compares local noon with Greenwich time to find the longitude.","sceneCN":"这里 longitude 指「某地相对本初子午线的东西角距离」（第 1 个义项：以本初子午线为零度、按角度量出的东西位置）；句意为航海者把当地正午与格林尼治时间对照，从而求出经度。图中可辨识物件：航海钟、海图、六分仪、地球仪。","pos":[{"tag":"n.","zh":"经度；经线；经度位置"},{"tag":"n.","zh":"长度（古义）"}],"collocations":[{"phrase":"latitude and longitude","zh":"经纬度"},{"phrase":"degrees of longitude","zh":"经度度数"},{"phrase":"east longitude","zh":"东经"},{"phrase":"west longitude","zh":"西经"},{"phrase":"line of longitude","zh":"经线"},{"phrase":"celestial longitude","zh":"黄经"}],"forms":[{"label":"复数","form":"longitudes"},{"label":"形容词（经度的；纵向的）","form":"longitudinal"},{"label":"副词（按经度地）","form":"longitudinally"}],"derivatives":[{"word":"longitudinal","pos":"adj./n.","zh":"经度的；纵向的 / 纵向研究"},{"word":"longitudinally","pos":"adv.","zh":"沿纵向地；按经度地"},{"word":"longitudinality","pos":"n.","zh":"纵向性（罕见术语）"}],"senses":[{"no":"01","title":"Angular distance from the prime meridian","titleCN":"经度：相对本初子午线的东西角距离","definition":"the angular distance of a place east or west of a fixed prime meridian, measured in degrees","definitionCN":"某地相对一条固定本初子午线向东或向西的角距离，以度数计","example":"The observatory stands at a longitude of seventy degrees west.","exampleCN":"这座天文台位于西经七十度。","why":"Latin longitudo meant 'length'; on the globe the east-west length of the known world became an angle measured from a chosen meridian.","whyCN":"拉丁 longitudo 意为「长度」；在地球上，已知世界的东西「长度」变成了从选定子午线量起的角度。"},{"no":"02","title":"A meridian or line of longitude","titleCN":"经线：连接两极的大圆","definition":"a great circle passing through both poles, drawn on a map to mark a longitude","definitionCN":"过南北两极、在地图上标出某经度的大圆","example":"The captain marked the line of longitude on the chart.","exampleCN":"船长在海图上标出了那条经线。","why":"The drawn line is the visible form of the measured angle, so the same word names coordinate, line and position.","whyCN":"画出的线是所测角度的可见形态，因此同一个词兼指坐标、线与位置。"},{"no":"03","title":"Position east or west of a reference","titleCN":"经度位置：位于参考线以东或以西","definition":"the east-west position of a place relative to a reference meridian","definitionCN":"某地相对参考子午线的东西位置","example":"Ships approaching the coast reported their longitude every hour.","exampleCN":"接近海岸的船只每小时报告一次经度位置。","why":"Navigation treats longitude as a place on a scale from west to east, not only as a degree value.","whyCN":"航海把经度当作从西到东的刻度上的位置，而不只是度数。"},{"no":"04","title":"Length, archaic","titleCN":"长度：事物的长向尺寸（古义）","definition":"the length of a thing, the original Latin sense, now obsolete in everyday use","definitionCN":"事物的长度，即拉丁本义，今日常用语中已废弃","example":"The old geometry text speaks of the longitude of a rectangle.","exampleCN":"那本旧几何书谈到矩形的长度。","why":"This is the literal Latin sense; it survives only in historical and technical writing after geography took the word over.","whyCN":"这是拉丁本义；在地理义占据该词之后，只残存于历史与技术文字中。"},{"no":"05","title":"Celestial longitude","titleCN":"黄经：天体沿黄道量出的角度","definition":"the angular distance of a celestial body measured eastward along the ecliptic","definitionCN":"天体沿黄道向东量出的角距离","example":"Ephemeris tables list the celestial longitude of the moon.","exampleCN":"星历表列出月球的黄经。","why":"The sky was mapped with the same length-turned-angle logic, using the ecliptic as its zero circle.","whyCN":"天空也按同一套「长度转为角度」的逻辑绘制，只是零度圈改用黄道。"},{"no":"06","title":"Longitude and time","titleCN":"经度与时差：经度差对应的时间差","definition":"the fixed relation between a difference in longitude and a difference in local time","definitionCN":"经度差与当地时间差之间的固定关系","example":"Every fifteen degrees of longitude equals one hour of time.","exampleCN":"每十五度经度相当于一小时的时间差。","why":"Because the earth turns at a steady rate, an east-west angle can be converted into a time difference, which made the chronometer method possible.","whyCN":"地球匀速自转，东西向的角度可换算成时间差，这正是航海钟测经法的基础。"},{"no":"07","title":"Difference of longitude","titleCN":"经度差：两地经线之间的角度","definition":"the angle between the meridians of two places, used in navigation and surveying","definitionCN":"两地经线之间的夹角，用于航海与测量","example":"The survey first computed the difference of longitude between the two towns.","exampleCN":"测量队先算出两镇之间的经度差。","why":"Two positions are compared by subtracting their longitudes, so the word also names the gap rather than a single coordinate.","whyCN":"比较两地位置要相减经度，因此这个词也指这段差值而非单一坐标。"},{"no":"08","title":"Geodetic versus astronomical longitude","titleCN":"大地经度与天文经度：两种测定口径","definition":"the east-west coordinate defined either by a reference ellipsoid or by the local vertical","definitionCN":"分别以参考椭球或当地铅垂线定义的东西坐标","example":"Geodetic longitude differs slightly from astronomical longitude.","exampleCN":"大地经度与天文经度略有差异。","why":"Precise mapping distinguishes a coordinate on the ellipsoid from one fixed by gravity, so longitude splits into two technical readings.","whyCN":"精密制图把椭球面上的坐标与由重力确定的坐标分开，经度因此分为两种技术读数。"}],"etymology":{"intro":{"en":"Longitude comes from Latin longitudo 'length', built on longus 'long'. Geography narrowed 'length' to the east-west span of the world and then to an angle. Dates are approximate.","cn":"longitude 来自拉丁 longitudo「长度」，由 longus「长的」构成；地理学把「长度」收窄为世界的东西跨度，再收窄为角度。年代均为约数。"},"items":[{"era":"LATIN LONGUS","en":"Longus meant 'long'; its Indo-European source is reconstructed as a form meaning 'long', so the deeper form is a reconstruction rather than a recorded word.","cn":"longus 意为「长的」；其印欧语来源被重构为表示「长」的形式，因此更深层的词形属重构而非有记录的词。"},{"era":"LATIN LONGITUDO","en":"Longus plus -tudo gave longitudo, 'length, extent'.","cn":"longus 加 -tudo 构成 longitudo，意为「长度、幅度」。"},{"era":"GEOGRAPHICAL NARROWING","en":"In sixteenth-century geography the 'length' of the known world was fixed as the east-west angular distance from a prime meridian.","cn":"16 世纪地理学把已知世界的「长度」定为相对本初子午线的东西角距离。"},{"era":"ASTRONOMY","en":"Celestial longitude applies the same measure to the sky, counting eastward along the ecliptic.","cn":"黄经把同一量度用于天空，沿黄道向东计数。"},{"era":"THE LONGITUDE PROBLEM","en":"From the seventeenth to the eighteenth century the practical need to fix longitude at sea drove chronometer astronomy and precision timekeeping.","cn":"17 至 18 世纪，在海上确定经度的实际需要推动了航海钟天文学与精密计时。"},{"era":"UNCERTAIN FIRST DATES","en":"Source uncertain (first dates only): the archaic 'length' sense faded without a recorded final use, and the first maritime applications are not precisely dated. The root is secure.","cn":"来源不确定（仅首见年代）：古义「长度」在无记录的情况下淡出，最早的航海应用亦无确切年代。词根本身可靠。"}]},"similar":{"note":{"en":"Group one holds the -tude words that share spelling patterns with longitude; group two holds the map and sky terms it is paired with or confused with.","cn":"第一组是与 longitude 共享拼写模式的 -tude 词；第二组是常与它配对或混淆的地图与天球术语。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"latitude","ipa":"/ˈlætɪtjuːd/","tag":"the partner coordinate","definition":"From latus 'broad': the north-south angle, drawn as east-west parallels.","definitionCN":"来自 latus「宽」：南北向角度，画成东西走向的纬线。"},{"word":"altitude","ipa":"/ˈæltɪtjuːd/","tag":"vertical height","definition":"From altus 'high': height above a reference, with no east-west meaning.","definitionCN":"来自 altus「高」：高出基准的高度，与东西位置无关。"},{"word":"magnitude","ipa":"/ˈmæɡnɪtjuːd/","tag":"size, not place","definition":"From magnus 'great': the size or brightness of something, especially a star.","definitionCN":"来自 magnus「大」：某物的大小或亮度，尤指恒星。"},{"word":"aptitude","ipa":"/ˈæptɪtjuːd/","tag":"ability, not place","definition":"From aptus 'fit': a natural capacity for learning, with no geographic use.","definitionCN":"来自 aptus「合适」：学习的天赋，不含地理用法。"}]},{"heading":"NEAR MEANING","entries":[{"word":"meridian","ipa":"/məˈrɪdiən/","tag":"the line itself","definition":"A great circle through the poles; a meridian is one specific line of longitude, often the reference line.","definitionCN":"过两极的大圆；经线是某一条具体的经度线，常指参考线。"},{"word":"parallel","ipa":"/ˈpærəlel/","tag":"latitude's line","definition":"A circle parallel to the equator; it is the drawn form of a latitude, not a longitude.","definitionCN":"与赤道平行的圈；它是纬度的画线形态，不是经度。"},{"word":"bearing","ipa":"/ˈbeərɪŋ/","tag":"direction, not position","definition":"The direction of one point from another, measured as an angle from north; it answers 'which way', not 'how far east'.","definitionCN":"一点相对另一点的方向，从正北量角；它回答「朝哪边」，而非「向东多远」。"},{"word":"coordinate","ipa":"/kəʊˈɔːdɪneɪt/","tag":"the general term","definition":"Either of the numbers that fix a position; latitude and longitude are the two geographic coordinates.","definitionCN":"用于确定位置的两个数之一；纬度与经度就是两个地理坐标。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real Latin 'length', real map practice and the real history of the longitude problem.","cn":"正常联想：真实的拉丁「长度」、真实的地图实践与真实的经度难题史。"},"normal":[{"en":"Longus 'long' + -tudo 'state': the world's east-west length, later measured as an angle.","cn":"longus「长」+ -tudo「状态」：世界的东西长度，后来被量成角度。"},{"en":"Longitude lines run north-south and measure east-west position; latitude lines do the reverse.","cn":"经线南北走向，却量东西位置；纬线正好相反。"},{"en":"Fifteen degrees of longitude correspond to one hour of solar time.","cn":"十五度经度对应一小时的太阳时。"},{"en":"The prime meridian at Greenwich is the zero line for longitude.","cn":"格林尼治本初子午线是经度的零度线。"},{"en":"The 'longitude problem' was solved by accurate clocks at sea, not by better maps alone.","cn":"「经度难题」是靠海上精确计时解决的，仅靠更好的地图不够。"}],"abstract":[{"en":"Picture a clock and a globe joined by a single shaft, so time turns into distance.","cn":"想象一只钟与一个地球仪由一根轴连在一起，时间由此变成距离。"},{"en":"Picture an orange cut into wedges from top to bottom rather than around its middle.","cn":"想象一只橙子从上到下切成瓣，而不是横着切。"},{"en":"Picture a ruler laid north-south while it measures how far east you are.","cn":"想象一把尺南北摆放，却量出你向东走了多远。"}]},"examples":[{"en":"The town lies at a longitude of one hundred degrees east.","cn":"这座小镇位于东经一百度。"},{"en":"Difference in longitude can be converted into difference in local time.","cn":"经度差可以换算成地方时差。"},{"en":"Early sailors could find latitude but not longitude.","cn":"早期的水手能测纬度，却测不出经度。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"long（长）+ itude（状态）→ 地球东西方向的「长度」→ 经度","word":"longitude"},"root":"拉丁 longitudo「长度」= longus「长的」+ -tudo（状态）；地理学把「长度」收窄为东西向角距离。英语 longitude 经法语借入。","sensesIntro":{"en":"Eight senses all come from 'length' turned into a coordinate: the east-west angle, the line that marks it, the position it names, the older literal length, the sky's version, the time it implies, the gap between two places, and the two ways surveyors define it.","cn":"八个义项都来自「长度」被转为坐标：东西向角度、标出它的经线、它所命名的位置、更早的字面长度、天空中的对应量、它对应的时间、两地之间的差值，以及测量者定义它的两种口径。"},"semanticMap":{"core":{"en":"CORE IMAGE: a line running pole to pole, marking how far east or west a place has moved from a zero line.","cn":"核心意象：一条从极到极的线，标出某地相对零度线向东或向西移动了多远。"},"chain":["LENGTH","ZERO MERIDIAN","EAST-WEST ANGLE","DRAWN MERIDIAN","TIME GAP","TWO DATUMS"],"branches":[{"senses":"S1 · S3","en":"COORDINATE AND PLACE: a degree value and the position it picks out are two faces of one coordinate.","cn":"坐标与位置：度数与它所标出的位置，是同一坐标的两面。"},{"senses":"S2 · S7","en":"LINE AND GAP: one meridian marks a place, two meridians measure the distance between places.","cn":"线与差：一条经线标记地点，两条经线量出地点间的距离。"},{"senses":"S4","en":"OLD LENGTH: the literal Latin sense survives as a technical term for extent.","cn":"旧义长度：拉丁本义作为表示幅度的技术词留存。"},{"senses":"S5","en":"SKY: the same measure is counted eastward along the ecliptic.","cn":"天空：同一量度沿黄道向东计数。"},{"senses":"S6 · S8","en":"TIME AND DATUM: longitude converts into time, and into two technical readings on ellipsoid or plumb line.","cn":"时间与基准：经度可换算为时间，也可分成椭球面与铅垂线的两种技术读数。"}]},"affixes":{"intro":{"en":"Longitude is built on Latin longus 'long' and a state suffix; the same root runs through long, elongate and elongation.","cn":"longitude 由拉丁 longus「长的」与状态后缀构成；同一词根贯穿 long、elongate 与 elongation。"},"latinIntro":{"en":"Latin longus 'long' yields longitude, longitudinal and prolong; the verb elongare 'to lengthen' gives elongate and elongation.","cn":"拉丁 longus「长」衍生 longitude、longitudinal 与 prolong；动词 elongare「使变长」衍生 elongate 与 elongation。"},"items":[{"word":"longus","structure":"longus (Latin adjective, 'long')","meaning":"long","meaningCN":"长的","example":"The root supplies the idea of extent from end to end.","exampleCN":"词根提供从一端到另一端的延伸之意。"},{"word":"-tudo","structure":"-tudo, -tudinis (Latin suffix, state)","meaning":"state or quality","meaningCN":"状态；性质","example":"The suffix turns 'long' into 'length'.","exampleCN":"后缀把「长」变成「长度」。"},{"word":"longitude","structure":"longus + -tudo","meaning":"length; east-west angle","meaningCN":"经度；长度","example":"The map gives longitude before latitude.","exampleCN":"地图先标经度再标纬度。"},{"word":"longitudinal","structure":"longitude + -al (relating to)","meaning":"running lengthwise","meaningCN":"纵向的；经度的","example":"A longitudinal study followed the same children for years.","exampleCN":"一项纵向研究跟踪同一批孩子多年。"},{"word":"longitudinally","structure":"longitudinal + -ly (adverb)","meaning":"in a lengthwise direction","meaningCN":"纵向地","example":"The pipe was cut longitudinally.","exampleCN":"管道被纵向切开。"},{"word":"long","structure":"long (English adjective from Old English lang)","meaning":"long","meaningCN":"长的","example":"The same Germanic root survives beside the Latin borrowing.","exampleCN":"同一日耳曼词根与拉丁借词并存。"},{"word":"elongate","structure":"e- 'out' + longus 'long'","meaning":"to stretch out","meaningCN":"拉长；延长","example":"The cells elongate as they mature.","exampleCN":"细胞成熟时伸长。"},{"word":"elongation","structure":"elongate + -ion (action)","meaning":"lengthening; angular separation","meaningCN":"延长；距角","example":"The elongation of the planet is measured from the sun.","exampleCN":"行星的距角从太阳起算。"}],"latinEntries":[{"word":"longus","structure":"longus, longa, longum (adjective)","meaning":"long","meaningCN":"长的"},{"word":"longitudo","structure":"longitudo, longitudinis (f., third declension)","meaning":"length","meaningCN":"长度"},{"word":"elongare","structure":"elongare, elongavi, elongatum (verb, first conjugation)","meaning":"to lengthen, remove","meaningCN":"延长；移开"}]}},{"word":"hemisphere","ipa_uk":"/ˈhemɪsfɪə/","ipa_us":"/ˈhemɪsfɪr/","definition_zh":"半球；地球半球；大脑半球；半球图；（活动）范围","definition_en":"one half of a sphere, especially the northern or southern half of the earth","core_image":"一个球被过球心的大圆切成两半，每一半都保留着完整的弧面","scene":"地理老师在球体模型上沿赤道画了一圈。The teacher cuts the globe along the equator to show each hemisphere.","sceneCN":"这里 hemisphere 指「地球被赤道分成的南北两半之一」（第 1 个义项：以赤道为界划分的地球半球）；句意为老师沿赤道切开地球仪，展示南北两个半球。图中可辨识物件：地球仪、赤道线、半圆剖面、支架。","pos":[{"tag":"n.","zh":"半球；地球的南北半球"},{"tag":"n.","zh":"大脑半球；（活动）范围"}],"collocations":[{"phrase":"northern hemisphere","zh":"北半球"},{"phrase":"southern hemisphere","zh":"南半球"},{"phrase":"eastern hemisphere","zh":"东半球"},{"phrase":"western hemisphere","zh":"西半球"},{"phrase":"cerebral hemisphere","zh":"大脑半球"},{"phrase":"hemisphere map","zh":"半球图"}],"forms":[{"label":"复数","form":"hemispheres"},{"label":"形容词（半球形的）","form":"hemispherical"},{"label":"形容词（半球的）","form":"hemispheric"}],"derivatives":[{"word":"hemispherical","pos":"adj.","zh":"半球形的"},{"word":"hemispheric","pos":"adj.","zh":"半球的；大脑半球的"},{"word":"hemispherectomy","pos":"n.","zh":"大脑半球切除术"},{"word":"hemispheroid","pos":"n.","zh":"半球状体（几何）"}],"senses":[{"no":"01","title":"Half of the earth","titleCN":"地球的半球：以赤道或经圈分成的两半","definition":"either the northern or southern half of the earth, divided by the equator, or the eastern and western halves divided by meridians","definitionCN":"地球被赤道分成南北两半，或被经线分成东西两半的任一半","example":"Most of the world's population lives in the northern hemisphere.","exampleCN":"世界人口大部分住在北半球。","why":"Hemi- 'half' plus sphaira 'sphere' literally gives 'half ball'; once applied to the earth, it names each of its two halves.","whyCN":"hemi-「一半」加 sphaira「球」字面就是「半个球」；用于地球后，就指地球的两半之一。"},{"no":"02","title":"Half of any sphere","titleCN":"半球体：任意球体被大圆切开的一半","definition":"one of the two halves of a sphere cut by a plane through its centre","definitionCN":"球体被过球心平面切开后的任一半","example":"A hemisphere has a curved surface and one flat circular face.","exampleCN":"半球有一个曲面和一个平的圆面。","why":"The geometry sense is the literal one: a sphere divided by a great circle leaves two equal halves.","whyCN":"几何义是字面义：球被大圆分割，留下两个相等的半。"},{"no":"03","title":"One side of the brain","titleCN":"大脑半球：大脑左右两半之一","definition":"either of the two halves of the brain, left and right, divided by the central fissure","definitionCN":"大脑被中央沟分成左右两半的任一半","example":"The left hemisphere usually handles language in right-handed people.","exampleCN":"惯用右手的人通常由左半球处理语言。","why":"The brain is roughly spherical, so its two lobes were named hemispheres when anatomy borrowed the word.","whyCN":"大脑近似球形，解剖学借这个词时就把左右两叶称作半球。"},{"no":"04","title":"A map of one half of the globe","titleCN":"半球图：展示地球一半的地图","definition":"a map projection that shows one half of the globe at a time","definitionCN":"一次展示地球一半的地图投影","example":"The atlas opens with a hemisphere map of the Pacific.","exampleCN":"这本图集以一幅太平洋半球图开篇。","why":"A flat map can show only half the globe without severe distortion, so such maps are called hemisphere maps.","whyCN":"平面地图不严重变形时只能展示地球一半，这类图因而叫半球图。"},{"no":"05","title":"Eastern or western division","titleCN":"东西半球：按经度划分的政治地理分区","definition":"either of the two east-west divisions of the globe, often used as a cultural or political label","definitionCN":"地球按经度划分的东西两半，常用作文化或政治标签","example":"The convention placed the new nation in the western hemisphere.","exampleCN":"这一惯例把新国家归入西半球。","why":"Meridians can split the globe into two named halves just as the equator does, and those names then acquire cultural and political weight.","whyCN":"经线也能像赤道一样把地球分成两个有名称的半，而这些名称随后带上文化与政治分量。"},{"no":"06","title":"Half of the celestial sphere","titleCN":"天球半球：天球被地平圈分成的一半","definition":"either half of the sky as divided by the horizon or by a celestial great circle","definitionCN":"天空被地平圈或天球大圆分成的任一半","example":"Astronomers chart the visible hemisphere before dawn.","exampleCN":"天文学家在黎明前绘制可见天球半球。","why":"The horizon cuts the spherical sky into a visible half and a hidden half, the same geometry as the globe.","whyCN":"地平圈把球形天空切成可见与不可见两半，与地球的几何分割相同。"},{"no":"07","title":"A sphere of activity or influence","titleCN":"活动范围：影响所及的领域（书面）","definition":"an area of activity, knowledge or influence, used figuratively","definitionCN":"活动、知识或影响所及的范围，用于比喻","example":"The reform moved education into a different hemisphere of public debate.","exampleCN":"这项改革把教育推入公共讨论的另一个领域。","why":"The globe's two halves are imagined as two separate worlds, so any divided field can be called a hemisphere.","whyCN":"地球的两半被想象成两个分开的世界，因此任何被分割的领域都可称为一个 hemisphere。"},{"no":"08","title":"Land or water hemisphere","titleCN":"陆半球或水半球：按海陆分布划分的半球","definition":"either of two halves of the earth chosen to contain most of its land or most of its water","definitionCN":"地球按陆地或水域最集中而划分出的两半之一","example":"The land hemisphere is centred near southern Europe.","exampleCN":"陆半球以欧洲南部附近为中心。","why":"Geographers may choose the centre so that most land falls in one half and most water in the other, which makes the division a deliberate cut.","whyCN":"地理学家可以选择中心，使大部分陆地落在一半、大部分水域落在另一半，因此这种划分是有意选定的切法。"}],"etymology":{"intro":{"en":"Hemisphere goes back to Greek hemisphairion, 'half a sphere', from hemi- 'half' and sphaira 'ball'. Latin took it as hemisphaerium and English borrowed it in the sixteenth century. Dates are approximate.","cn":"hemisphere 上溯到希腊 hemisphairion「半个球」，由 hemi-「一半」与 sphaira「球」构成；拉丁作 hemisphaerium，英语在 16 世纪借入。年代均为约数。"},"items":[{"era":"GREEK HEMI-","en":"Hemi- meant 'half' and is a productive prefix in English, as in hemicycle and hemisphere.","cn":"hemi- 意为「一半」，在英语中是能产前缀，如 hemicycle 与 hemisphere。"},{"era":"GREEK SPHAIRA","en":"Sphaira meant 'ball, globe'. Its deeper origin is not established; any Indo-European root proposed for it is a reconstruction, not a recorded form.","cn":"sphaira 意为「球、globus」；其更深来源未得到证明，为其提出的任何印欧词根都属重构形式，而非有记录的词。"},{"era":"GREEK HEMISPHAIRION","en":"Hemi- plus sphaira gave hemisphairion, 'a half sphere', used by Greek geographers and astronomers.","cn":"hemi- 加 sphaira 构成 hemisphairion「半球」，为希腊地理学家与天文学家所用。"},{"era":"LATIN HEMISPHAERIUM","en":"Latin borrowed the Greek compound as hemisphaerium, keeping both elements intact.","cn":"拉丁把这个希腊复合词借作 hemisphaerium，两个成分原样保留。"},{"era":"ENGLISH","en":"English hemisphere appears in the sixteenth century, first for the halves of the celestial and terrestrial spheres.","cn":"英语 hemisphere 出现于 16 世纪，最初指天球与地球的半球。"},{"era":"BRAIN SENSE","en":"The anatomical use for the two halves of the brain developed later; its exact first English date is uncertain, while the compound itself is transparent.","cn":"指大脑两半的解剖用法较晚出现；其英语首见确切年代不确定，但复合词本身结构透明。"}]},"similar":{"note":{"en":"Group one holds the -sphere words that look alike; group two holds words for halves, globes and brain regions.","cn":"第一组是外形相近的 -sphere 词；第二组是表示一半、球体与脑区的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"atmosphere","ipa":"/ˈætməsfɪə/","tag":"sphere of air","definition":"From Greek atmos 'vapour' plus sphaira: the envelope of air around a planet, not a half of it.","definitionCN":"来自希腊 atmos「蒸汽」加 sphaira：行星周围的空气层，不是球的一半。"},{"word":"biosphere","ipa":"/ˈbaɪəsfɪə/","tag":"sphere of life","definition":"From Greek bios 'life' plus sphaira: the zone of living things, named by analogy with atmosphere.","definitionCN":"来自希腊 bios「生命」加 sphaira：生物所在圈层，仿 atmosphere 造出。"},{"word":"ionosphere","ipa":"/ˈaɪənəsfɪə/","tag":"sphere of ions","definition":"The ionised layer of the upper atmosphere; again a full shell, not a hemisphere.","definitionCN":"高层大气中的电离层；同样是完整壳层而非半球。"},{"word":"stratosphere","ipa":"/ˈstrætəsfɪə/","tag":"layered sphere","definition":"From Latin stratum 'layer' plus sphaira: a layer of the atmosphere, with no half division.","definitionCN":"来自拉丁 stratum「层」加 sphaira：大气的一层，不含对半分割。"}]},{"heading":"NEAR MEANING","entries":[{"word":"half","ipa":"/hɑːf/","tag":"plain part word","definition":"The everyday word for one of two equal parts; hemisphere adds the spherical shape.","definitionCN":"表示两个相等部分之一的日常词；hemisphere 另带球体形状。"},{"word":"globe","ipa":"/ɡləʊb/","tag":"the whole ball","definition":"The whole spherical earth or a model of it; a hemisphere is only one of its halves.","definitionCN":"整个球形地球或其模型；半球只是它的一半。"},{"word":"lobe","ipa":"/ləʊb/","tag":"rounded division","definition":"A rounded projecting part, as of the brain or lung; hemisphere stresses the left-right division.","definitionCN":"圆形突出的部分，如脑叶或肺叶；hemisphere 强调左右分半。"},{"word":"zone","ipa":"/zəʊn/","tag":"belt, not half","definition":"A band or region defined by climate or function; it cuts the globe into belts rather than halves.","definitionCN":"按气候或功能划分的带或区域；它把地球切成带而非两半。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Greek compound, real map terms and real anatomy, not invented rhymes.","cn":"正常联想：真实的希腊复合词、真实的地图术语与真实的解剖学，而非编造的顺口溜。"},"normal":[{"en":"Hemi- 'half' + sphaira 'sphere': literally half a ball, then half the earth.","cn":"hemi-「一半」+ sphaira「球」：字面是半个球，再指地球的一半。"},{"en":"The -sphere family (atmosphere, biosphere, ionosphere) is built on the same Greek 'ball'.","cn":"atmosphere、biosphere、ionosphere 等 -sphere 词族都建立在同一个希腊「球」上。"},{"en":"Northern and southern hemispheres are divided by the equator; eastern and western by meridians.","cn":"南北半球由赤道分开，东西半球由经线分开。"},{"en":"The brain's two hemispheres are linked by the corpus callosum.","cn":"大脑两个半球由胼胝体相连。"},{"en":"A hemisphere map shows half the globe at once, which limits distortion.","cn":"半球图一次展示地球一半，从而限制变形。"}],"abstract":[{"en":"Picture an orange sliced exactly through its centre into two equal cups.","cn":"想象一只橙子沿正中心切成两只相等的杯状半。"},{"en":"Picture a theatre with the audience seated on one side of the stage only.","cn":"想象一座剧场，观众只坐在舞台的一侧。"},{"en":"Picture a conversation that belongs to one half of a divided family.","cn":"想象一场只属于分裂家庭中某一方的对话。"}]},"examples":[{"en":"Summer begins in the southern hemisphere in December.","cn":"南半球的夏天在十二月开始。"},{"en":"Each hemisphere of the brain has different functions.","cn":"大脑每个半球各有不同功能。"},{"en":"The map folds out into two hemispheres.","cn":"这张地图展开后分成两个半球图。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"hemi（一半，如 hemi- 前缀）+ sphere（球）→ 半个球 → 半球、大脑半球","word":"hemisphere"},"root":"希腊 hemisphairion「半球」= hemi-（一半）+ sphaira（球）；拉丁 hemisphaerium，英语 16 世纪借入。","sensesIntro":{"en":"Eight senses all begin with a sphere and a cut through its centre: the earth's halves, any ball's halves, the brain's two sides, a map of one half, the east-west labels, the sky's halves, a figurative field, and the land-water division.","cn":"八个义项都从「球体被过球心切开」开始：地球两半、任意球体的两半、大脑两侧、展示一半的地图、东西半球标签、天空两半、比喻的领域，以及陆半球与水半球。"},"semanticMap":{"core":{"en":"CORE IMAGE: a sphere cut exactly through its centre, leaving two equal curved halves.","cn":"核心意象：一个球被过球心切开，留下两个相等的弧面半。"},"chain":["SPHERE","GREAT CIRCLE","TWO HALVES","EARTH DIVIDED","BRAIN DIVIDED","FIELD DIVIDED"],"branches":[{"senses":"S1 · S2","en":"GEOMETRY TO EARTH: the literal half ball becomes the earth's northern and southern halves.","cn":"几何到地球：字面的半个球变成地球的南北两半。"},{"senses":"S3","en":"BODY: the brain's two sides borrow the spherical division.","cn":"身体：大脑两侧借用了球体的分割。"},{"senses":"S4 · S8","en":"DRAWN AND CHOSEN: maps show one half at a time, and land or water can define an uneven half.","cn":"画出与选定：地图一次展示一半，陆地或水域也能划出不完全对等的一半。"},{"senses":"S5 · S7","en":"LABEL AND METAPHOR: east-west halves are political names, and any field can be pictured as a half.","cn":"标签与比喻：东西半球是政治名称，任何领域也可被想象成一半。"},{"senses":"S6","en":"SKY: the celestial sphere is cut by the horizon into visible and invisible halves.","cn":"天空：天球被地平圈分成可见与不可见的两半。"}]},"affixes":{"intro":{"en":"Hemisphere joins a Greek prefix for 'half' to the Greek word for 'ball'; the second element also builds the atmosphere and biosphere words.","cn":"hemisphere 把希腊「一半」前缀与希腊「球」词连在一起；后一成分还构成 atmosphere 与 biosphere 等词。"},"latinIntro":{"en":"Greek sphaira 'ball' passed into Latin as sphaera and into English as -sphere; hemi- remains a live prefix in English compounds.","cn":"希腊 sphaira「球」传入拉丁作 sphaera，再进入英语作 -sphere；hemi- 在英语复合词中仍是能产前缀。"},"items":[{"word":"hemi-","structure":"hemi- (Greek prefix, 'half')","meaning":"half","meaningCN":"一半","example":"The prefix cuts the sphere exactly in two.","exampleCN":"这个前缀把球正好切成两半。"},{"word":"sphaira","structure":"sphaira (Greek noun, 'ball, globe')","meaning":"ball; globe","meaningCN":"球；天球","example":"The root supplies the round shape.","exampleCN":"这个词根提供圆形。"},{"word":"hemisphere","structure":"hemi- + sphaira","meaning":"half a sphere","meaningCN":"半球","example":"The northern hemisphere is warmer in July.","exampleCN":"北半球七月较暖。"},{"word":"hemispherical","structure":"hemisphere + -ical (shaped like)","meaning":"shaped like half a sphere","meaningCN":"半球形的","example":"The dome is hemispherical.","exampleCN":"这座穹顶是半球形的。"},{"word":"hemispheric","structure":"hemisphere + -ic (relating to)","meaning":"relating to a hemisphere","meaningCN":"半球的","example":"Hemispheric trade grew after the treaty.","exampleCN":"条约签订后半球间贸易增长。"},{"word":"hemispherectomy","structure":"hemisphere + Greek ektome 'cutting out'","meaning":"surgical removal of a hemisphere","meaningCN":"大脑半球切除术","example":"The child recovered after a hemispherectomy.","exampleCN":"这个孩子在半球切除术后康复。"},{"word":"atmosphere","structure":"Greek atmos 'vapour' + sphaira","meaning":"sphere of air","meaningCN":"大气层","example":"The atmosphere protects the surface.","exampleCN":"大气层保护地表。"},{"word":"biosphere","structure":"Greek bios 'life' + sphaira","meaning":"sphere of life","meaningCN":"生物圈","example":"The biosphere extends through land and sea.","exampleCN":"生物圈遍及陆地与海洋。"},{"word":"ionosphere","structure":"Greek ion 'going' + sphaira","meaning":"ionised layer of air","meaningCN":"电离层","example":"Radio signals bounce off the ionosphere.","exampleCN":"无线电信号从电离层反射。"}],"latinEntries":[{"word":"sphaera","structure":"sphaera, sphaerae (f., first declension)","meaning":"sphere, globe","meaningCN":"球；天球"},{"word":"hemisphaerium","structure":"hemisphaerium, hemisphaerii (n., second declension)","meaning":"half sphere","meaningCN":"半球"},{"word":"hemispherium","structure":"hemispherium, hemispherii (n., second declension, variant)","meaning":"half sphere","meaningCN":"半球（异体）"}]}},{"word":"equator","ipa_uk":"/ɪˈkweɪtə/","ipa_us":"/ɪˈkweɪtər/","definition_zh":"赤道；赤道地区；天赤道；磁赤道；热赤道；（细胞的）赤道面","definition_en":"the great circle around the earth halfway between the poles, or a corresponding line on another sphere","core_image":"一只橙子被横着切开，刀口绕行一圈，正好把球分成上下相等两半","scene":"课堂上老师拿一只橙子演示地球的横切大圆。A teacher draws a line around an orange to show where the equator would cut the globe.","sceneCN":"这里 equator 指「地球表面与南北两极等距的大圆」（第 1 个义项：把地球分成南北两半的零度纬线）；句意为老师用橙子演示这条大圆落在球面上的位置。图中可辨识物件：橙子、横切刀痕、地球仪、粉笔线。","pos":[{"tag":"n.","zh":"赤道；赤道地区"},{"tag":"n.","zh":"天赤道；磁赤道；热赤道"},{"tag":"n.","zh":"（细胞的）赤道面"}],"collocations":[{"phrase":"on the equator","zh":"在赤道上"},{"phrase":"cross the equator","zh":"越过赤道"},{"phrase":"north of the equator","zh":"赤道以北"},{"phrase":"south of the equator","zh":"赤道以南"},{"phrase":"celestial equator","zh":"天赤道"},{"phrase":"magnetic equator","zh":"磁赤道"}],"forms":[{"label":"复数","form":"equators"},{"label":"形容词（赤道的）","form":"equatorial"},{"label":"副词（赤道地）","form":"equatorially"}],"derivatives":[{"word":"equatorial","pos":"adj./n.","zh":"赤道的；赤道地区的 / 赤道仪"},{"word":"equatorially","pos":"adv.","zh":"在赤道附近地"},{"word":"equatorward","pos":"adj./adv.","zh":"朝赤道方向的"}],"senses":[{"no":"01","title":"The earth's great circle","titleCN":"地球赤道：与两极等距的大圆","definition":"the great circle around the earth that lies halfway between the north and south poles and marks zero latitude","definitionCN":"绕地球一圈、位于南北两极正中并标出零度纬线的大圆","example":"The river crosses the equator twice on its long course.","exampleCN":"这条河在漫长的流程中两次越过赤道。","why":"Latin aequator meant 'equalizer'; the circle is named for making day and night equal, and it is the zero line from which latitude is counted.","whyCN":"拉丁 aequator 意为「使相等者」；这条圈因使昼夜等长而得名，也是计算纬度的零度线。"},{"no":"02","title":"The equatorial region","titleCN":"赤道地区：赤道两侧的湿热地带","definition":"the hot, humid belt of the earth near the equator","definitionCN":"赤道附近炎热潮湿的地带","example":"Rubber plantations thrive in the equator's rain belt.","exampleCN":"橡胶园在赤道雨带里生长旺盛。","why":"The line marks a climate as well as a coordinate, so the region around it is called the equator in ordinary speech.","whyCN":"这条线既标坐标也标气候，因此它周围的地区在日常说法里也叫 the equator。"},{"no":"03","title":"The celestial equator","titleCN":"天赤道：天球上与地球赤道对应的大圆","definition":"the great circle on the celestial sphere lying in the plane of the earth's equator","definitionCN":"天球上位于地球赤道平面内的大圆","example":"The sun crosses the celestial equator at the equinoxes.","exampleCN":"太阳在二分点时穿过天赤道。","why":"Astronomers projected the earth's equator onto the sky, where it serves as the zero line for declination.","whyCN":"天文学家把地球赤道投影到天空，用作赤纬的零度线。"},{"no":"04","title":"The magnetic equator","titleCN":"磁赤道：地磁场的零倾角线","definition":"the line around the earth where a magnetic needle stays horizontal and magnetic dip is zero","definitionCN":"地球表面磁针保持水平、磁倾角为零的连线","example":"Compasses behave differently near the magnetic equator.","exampleCN":"在磁赤道附近，指南针的表现不同。","why":"The magnetic field has its own symmetry plane, so it produces an 'equator' that does not match the geographic one.","whyCN":"磁场有自己的对称面，因此产生一条与地理赤道不重合的「赤道」。"},{"no":"05","title":"The thermal equator","titleCN":"热赤道：地表年均最高温的连线","definition":"the line of highest mean annual temperature, which shifts with the seasons and with land distribution","definitionCN":"年平均气温最高的连线，随季节与海陆分布而移动","example":"The thermal equator lies north of the geographic equator in July.","exampleCN":"七月时热赤道位于地理赤道以北。","why":"Heat, not geometry, defines this belt, yet its central line is still pictured as an equator.","whyCN":"定义这条带的是热量而非几何，但它的中心线仍被想象成一条赤道。"},{"no":"06","title":"The cell equator","titleCN":"细胞赤道：有丝分裂中期染色体排列的平面","definition":"the plane midway between the two poles of a dividing cell, where chromosomes line up","definitionCN":"分裂细胞两极之间的中间平面，染色体在此排列","example":"Chromosomes align at the cell equator before separating.","exampleCN":"染色体在分离前排列在细胞赤道面上。","why":"A dividing cell has two poles like a small sphere, so the plane halfway between them borrows the name equator.","whyCN":"分裂的细胞像一个小球有两极，因此两极之间的平面借用了赤道之名。"},{"no":"07","title":"A great circle of any sphere","titleCN":"任意球体的大圆：与自转轴垂直的等分圈","definition":"any great circle perpendicular to the axis of a sphere or spheroid","definitionCN":"与球体或椭球体自转轴垂直的任一大圆","example":"Surveyors computed the equator of the model dome.","exampleCN":"测量员计算了模型穹顶的赤道圈。","why":"The earth's equator is only one instance of a general geometric relation, which can be applied to any rounded body.","whyCN":"地球赤道只是一般几何关系的一个实例，可套用到任何近球体。"},{"no":"08","title":"A dividing line between halves","titleCN":"平分线：把事物分成相等两半的界线","definition":"a line imagined as dividing something into two equal parts","definitionCN":"被想象为把某物分成相等两半的界线","example":"The negotiators drew an equator through the disputed budget.","exampleCN":"谈判者把有争议的预算划出一条对半分的界线。","why":"The word's core image, a line that makes two sides equal, can be moved from geography to any divided whole.","whyCN":"这个词的核心意象——一条使两边相等的线——可以从地理移到任何被分割的整体。"}],"etymology":{"intro":{"en":"Equator is from Medieval Latin aequator 'equalizer', from aequare 'to make equal', built on aequus 'level, equal'. The geographical name began as a phrase about the circle that equalizes day and night. Dates are approximate.","cn":"equator 来自中世纪拉丁 aequator「使相等者」，源于 aequare「使相等」，其词根为 aequus「平的、相等的」；地理名称最初是一个关于「使昼夜相等之圈」的短语。年代均为约数。"},"items":[{"era":"LATIN AEQUUS","en":"Aequus meant 'level, even, equal'. Its deeper origin is not settled; the connection sometimes suggested to a root meaning 'even' is a reconstruction.","cn":"aequus 意为「平的、均匀的、相等的」；其更深来源没有定论，有时提出的与「平」有关的词根联系属重构形式。"},{"era":"LATIN AEQUARE","en":"Aequare meant 'to make level or equal', a verb formed from aequus.","cn":"aequare 意为「使平、使相等」，是由 aequus 构成的动词。"},{"era":"MEDIEVAL LATIN AEQUATOR","en":"Aequator, 'one who equalizes', was used for the circle that makes day and night equal.","cn":"aequator 意为「使相等者」，被用来指使昼夜等长的那条圈。"},{"era":"THE FULL PHRASE","en":"The older phrase circulus aequator diei et noctis, 'the circle equalizing day and night', explains why the line received this name.","cn":"更早的短语 circulus aequator diei et noctis 意为「使昼夜相等之圈」，说明了这条线得名的原因。"},{"era":"GEOGRAPHICAL USE","en":"English geography adopted equator for the zero-latitude circle in the seventeenth century, dropping the rest of the phrase.","cn":"英语地理学在 17 世纪采用 equator 指零度纬线圈，省去了短语的其余部分。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper root and first dates): the pre-Latin origin of aequus is unresolved, and the earliest English uses of the magnetic and thermal senses are not precisely dated.","cn":"来源不确定（更深词根与首见年代）：aequus 在拉丁语之前的来源尚无定论，磁赤道与热赤道在英语中的最早用法亦无确切年代。"}]},"similar":{"note":{"en":"Group one holds words built on the same Latin 'equal' stock; group two holds the geographic lines and belts it is paired with.","cn":"第一组是同出拉丁「相等」词干的词；第二组是常与赤道配对的地理线与地带。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"equation","ipa":"/ɪˈkweɪʒn/","tag":"same equal root","definition":"From aequatio 'a making equal': a statement that two quantities are equal, with no geographical meaning.","definitionCN":"来自 aequatio「使相等」：表示两个量相等的式子，不含地理意义。"},{"word":"equilateral","ipa":"/ˌiːkwɪˈlætərəl/","tag":"equal sides","definition":"Aequus 'equal' plus latus 'side': a figure whose sides are all equal.","definitionCN":"aequus「相等」加 latus「边」：各边相等的图形。"},{"word":"equivalent","ipa":"/ɪˈkwɪvələnt/","tag":"equal in value","definition":"Aequus plus valere 'be worth': equal in value or effect, not equal in shape.","definitionCN":"aequus 加 valere「有价值」：价值或效果相等，而非形状相等。"},{"word":"equator","ipa":"/ɪˈkweɪtə/","tag":"the line itself","definition":"The zero-latitude circle; the other words in this group are about equality in general.","definitionCN":"零度纬线圈；本组其它词讲的是普遍的相等关系。"}]},{"heading":"NEAR MEANING","entries":[{"word":"tropics","ipa":"/ˈtrɒpɪks/","tag":"the hot belt","definition":"The region between the Tropic of Cancer and the Tropic of Capricorn, which contains the equator but is wider.","definitionCN":"南北回归线之间的地带，包含赤道但范围更宽。"},{"word":"parallel","ipa":"/ˈpærəlel/","tag":"any latitude circle","definition":"A circle parallel to the equator; the equator is the zero-degree parallel.","definitionCN":"与赤道平行的圈；赤道就是零度纬线。"},{"word":"latitude","ipa":"/ˈlætɪtjuːd/","tag":"the measurement","definition":"The angular distance from the equator, not the line itself.","definitionCN":"相对赤道的角距离，不是那条线本身。"},{"word":"meridian","ipa":"/məˈrɪdiən/","tag":"the perpendicular partner","definition":"A great circle through the poles; meridians cross the equator at right angles.","definitionCN":"过两极的大圆；经线与赤道正交。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Latin 'equalizer', real geographic lines and real cell biology, not invented rhymes.","cn":"正常联想：真实的拉丁「使相等者」、真实的地理线与真实的细胞生物学，而非编造的顺口溜。"},"normal":[{"en":"Aequus 'equal' + -ator 'one who makes': the circle that makes day and night equal.","cn":"aequus「相等」+ -ator「使……者」：使昼夜相等的那条圈。"},{"en":"The equator is the zero-degree parallel; latitude is counted up and down from it.","cn":"赤道是零度纬线；纬度从它向南北计数。"},{"en":"The celestial equator is the earth's equator projected onto the sky.","cn":"天赤道是地球赤道投影到天空的结果。"},{"en":"The magnetic equator is where a compass needle lies flat.","cn":"磁赤道是磁针保持水平的地方。"},{"en":"In cell division, chromosomes line up on the cell equator, also called the metaphase plate.","cn":"细胞分裂时染色体排在细胞赤道上，也叫中期板。"}],"abstract":[{"en":"Picture a belt worn exactly around the middle of a ball.","cn":"想象一条带子正好系在球的正中间。"},{"en":"Picture a knife cutting an orange into two equal cups.","cn":"想象一刀把橙子切成两只相等的杯状半。"},{"en":"Picture a line drawn through a budget so that both sides get the same amount.","cn":"想象在预算中间划一条线，让两边得到相同的数额。"}]},"examples":[{"en":"The equator passes through several countries in Africa and South America.","cn":"赤道穿过非洲和南美洲的若干国家。"},{"en":"Temperatures stay high near the equator all year.","cn":"赤道附近全年气温都很高。"},{"en":"The celestial equator is the zero line for declination.","cn":"天赤道是赤纬的零度线。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"equa（相等，如 equal）+ tor（……者）→ 使昼夜相等的线 → 赤道","word":"equator"},"root":"中世纪拉丁 aequator「使相等者」= aequare「使相等」（aequus「平的、相等的」）+ -ator；原指使昼夜相等之圈，后在英语中指零度纬线。","sensesIntro":{"en":"Eight senses all use one image, a line that divides a round body into two equal halves: the earth's zero latitude, its hot belt, the sky's projection, the magnetic and thermal lines, the cell's mid-plane, any sphere's great circle, and a figurative dividing line.","cn":"八个义项共用一个意象：把圆体分成相等两半的线——地球的零度纬线、湿热地带、天空中的投影、磁与热的对应线、细胞的中间平面、任意球体的大圆，以及比喻性的平分线。"},"semanticMap":{"core":{"en":"CORE IMAGE: a belt drawn around the middle of a sphere, making the two halves equal.","cn":"核心意象：一条绕球体中部的带子，使两半相等。"},"chain":["EQUAL HALVES","ZERO LATITUDE","HOT BELT","SKY PROJECTION","MAGNETIC LINE","CELL MID-PLANE"],"branches":[{"senses":"S1 · S7","en":"THE LINE: the earth's zero circle is one case of a general great circle perpendicular to an axis.","cn":"这条线：地球的零度圈是与轴垂直的一般大圆的一个实例。"},{"senses":"S2 · S5","en":"THE BELT: climate turns a geometric line into a hot region, and heat draws its own central line.","cn":"地带：气候把几何线变成炎热区域，热量又画出自己的中心线。"},{"senses":"S3","en":"THE SKY: the earth's equator is projected outward as the celestial equator.","cn":"天空：地球赤道向外投影为天赤道。"},{"senses":"S4","en":"THE FIELD: magnetism produces a second equator that does not match the geographic one.","cn":"场：磁性产生第二条与地理赤道不重合的赤道。"},{"senses":"S6 · S8","en":"DIVISION: a cell's mid-plane and a figurative halfway line both repeat the equal-halves gesture.","cn":"分割：细胞的中间平面与比喻的对半线都重复了「等分」动作。"}]},"affixes":{"intro":{"en":"Equator belongs to a Latin family built on aequus 'equal'; the same root yields equality, equation and adequate.","cn":"equator 属于以拉丁 aequus「相等」为根的词族；同一词根还衍生 equality、equation 与 adequate。"},"latinIntro":{"en":"Latin aequus 'level, equal' yields aequare 'to make equal', aequator 'equalizer' and aequatio 'equation'; English keeps the family in equal, equity and equator.","cn":"拉丁 aequus「平的、相等」衍生 aequare「使相等」、aequator「使相等者」与 aequatio「等式」；英语以 equal、equity 与 equator 保留这个词族。"},"items":[{"word":"aequus","structure":"aequus (Latin adjective, 'level, equal')","meaning":"level; equal","meaningCN":"平的；相等的","example":"The root names balance between two sides.","exampleCN":"这个词根表示两边之间的均衡。"},{"word":"aequare","structure":"aequare (Latin verb, first conjugation)","meaning":"to make equal or level","meaningCN":"使相等；使平","example":"The verb supplies the action of equalizing.","exampleCN":"这个动词提供「使相等」的动作。"},{"word":"aequator","structure":"aequator, aequatoris (m., third declension)","meaning":"one who equalizes","meaningCN":"使相等者","example":"The noun first named the circle that equalizes day and night.","exampleCN":"这个名词最初指使昼夜相等的圈。"},{"word":"equator","structure":"aequator (Medieval Latin)","meaning":"the zero-latitude circle","meaningCN":"赤道","example":"The equator divides the globe into two halves.","exampleCN":"赤道把地球分成两半。"},{"word":"equatorial","structure":"equator + -ial (relating to)","meaning":"relating to the equator","meaningCN":"赤道的","example":"Equatorial heat drives strong storms.","exampleCN":"赤道的热量催生强风暴。"},{"word":"equatorward","structure":"equator + -ward (toward)","meaning":"toward the equator","meaningCN":"向赤道方向","example":"The trade winds move equatorward.","exampleCN":"信风朝赤道方向吹。"},{"word":"equality","structure":"aequalis 'equal' + -ity (state)","meaning":"the state of being equal","meaningCN":"平等；相等","example":"The law aims at equality before the courts.","exampleCN":"法律追求法庭面前的平等。"},{"word":"equinox","structure":"aequus 'equal' + nox 'night'","meaning":"equal day and night","meaningCN":"昼夜平分点","example":"The equinox occurs twice a year.","exampleCN":"昼夜平分点每年出现两次。"},{"word":"adequate","structure":"ad- 'to' + aequatus 'made equal'","meaning":"enough, proportionate","meaningCN":"足够的；相称的","example":"The supply was adequate for the winter.","exampleCN":"供给足够过冬。"}],"latinEntries":[{"word":"aequus","structure":"aequus, aequa, aequum (adjective)","meaning":"level, equal, fair","meaningCN":"平的；相等的；公正的"},{"word":"aequare","structure":"aequare, aequavi, aequatum (verb, first conjugation)","meaning":"to make equal, level","meaningCN":"使相等；使平"},{"word":"aequator","structure":"aequator, aequatoris (m., third declension)","meaning":"equalizer","meaningCN":"使相等者"}]}},{"word":"meridian","ipa_uk":"/məˈrɪdiən/","ipa_us":"/məˈrɪdiən/","definition_zh":"子午线；经线；正午；顶点；经络","definition_en":"a great circle through the poles, especially one used as a longitude reference, or the moment of midday","core_image":"太阳在天空升到最高，一条从南到北划过天顶的隐形大圆正好对着它","scene":"正午时分测量杆的影子缩到最短。At noon the sun crosses the meridian and the shadow reaches its shortest.","sceneCN":"这里 meridian 指「过南北两极、也过天顶的大圆」（第 7 个义项：观测者所在的天球子午圈）；句意为太阳经过这条大圆时正当正午，杆影最短。图中可辨识物件：测量杆、影子、太阳、南北方向的标线。","pos":[{"tag":"n.","zh":"子午线；经线；正午；顶点；经络"},{"tag":"adj.","zh":"子午线的；正午的；顶点的"}],"collocations":[{"phrase":"the prime meridian","zh":"本初子午线"},{"phrase":"celestial meridian","zh":"天球子午圈"},{"phrase":"meridian line","zh":"子午线；南北向标线"},{"phrase":"the meridian sun","zh":"正午的太阳"},{"phrase":"reach its meridian","zh":"达到顶点"},{"phrase":"acupuncture meridians","zh":"针灸经络"}],"forms":[{"label":"复数","form":"meridians"},{"label":"形容词（子午的；南方的）","form":"meridional"},{"label":"副词（向南地）","form":"meridionally"},{"label":"缩写（上午）","form":"a.m."},{"label":"缩写（下午）","form":"p.m."}],"derivatives":[{"word":"meridional","pos":"adj./n.","zh":"子午线的；南方的 / 南欧人"},{"word":"meridionally","pos":"adv.","zh":"沿子午线方向地"},{"word":"ante meridiem","pos":"phrase","zh":"午前；上午"},{"word":"post meridiem","pos":"phrase","zh":"午后；下午"}],"senses":[{"no":"01","title":"A great circle through the poles","titleCN":"子午线：过南北两极的大圆","definition":"a great circle on the earth passing through both poles and any given place","definitionCN":"地球上过南北两极与某地的大圆","example":"Every place lies on its own meridian.","exampleCN":"每个地方都位于自己的一条子午线上。","why":"Latin meridies meant 'midday'; the sun at noon lies on the north-south circle, so that circle became the meridian.","whyCN":"拉丁 meridies 意为「正午」；正午太阳位于南北向的圈上，这条圈因此被称为子午线。"},{"no":"02","title":"The prime meridian","titleCN":"本初子午线：经度计数的零度线","definition":"the meridian chosen as zero longitude, internationally fixed at Greenwich","definitionCN":"被选作零度经线的子午线，国际上定在格林尼治","example":"Longitude is counted east and west from the prime meridian.","exampleCN":"经度从本初子午线向东、向西计数。","why":"One meridian must be chosen as the zero for all others, and that choice is a convention rather than a natural line.","whyCN":"必须选一条子午线作为其它经线的零点，这个选择是约定而非天然界线。"},{"no":"03","title":"Midday or noon","titleCN":"正午：太阳位于当地最高点的时间","definition":"the time of day when the sun is at its highest point, that is, local noon","definitionCN":"太阳位于当地最高点的时间，即当地正午","example":"The ceremony took place at the meridian.","exampleCN":"仪式在正午举行。","why":"Meridian comes straight from meridies 'midday', so the word can still name the hour itself, not only the line.","whyCN":"meridian 直接来自 meridies「正午」，因此这个词仍可指这个时刻本身，而不只是线。"},{"no":"04","title":"The sun's highest point","titleCN":"太阳中天：太阳到达当日最高处的时刻","definition":"the moment when the sun reaches its greatest altitude and crosses the observer's meridian","definitionCN":"太阳达到当日最大高度并经过观测者子午圈的时刻","example":"The astronomers recorded the meridian of the sun with a transit instrument.","exampleCN":"天文学家使用中星仪记录了太阳中天的时刻。","why":"The crossing of the meridian is the physical event that defines noon, so 'meridian' names both the line and the crossing.","whyCN":"经过子午圈是定义正午的物理事件，因此 meridian 既指线也指这次经过。"},{"no":"05","title":"The peak of achievement","titleCN":"顶点：事业或成就的最高处","definition":"the highest point of success, fame or a career","definitionCN":"成功、名声或事业的最高点","example":"The composer was at his meridian when he wrote the symphony.","exampleCN":"作曲家写这部交响曲时正处于创作顶峰。","why":"The sun at noon is at its highest, so the same word pictures any career at its high point.","whyCN":"正午的太阳升到最高，同一个词便用来比喻任何事业的最高点。"},{"no":"06","title":"An acupuncture channel","titleCN":"经络：中医里气血运行的通道","definition":"one of the channels in traditional Chinese medicine along which qi and blood are said to flow","definitionCN":"中医认为气血运行的通道之一","example":"The acupuncturist traced a meridian down the patient's arm.","exampleCN":"针灸师沿着病人手臂的一条经络施针。","why":"English translators needed a word for these channels and borrowed 'meridian', because a channel runs like a line across the body.","whyCN":"英语译者需要为这些通道找词，便借用了 meridian，因为经络像一条线贯穿身体。"},{"no":"07","title":"The observer's celestial meridian","titleCN":"天球子午圈：过天顶与天极的大圆","definition":"the great circle on the celestial sphere passing through the poles and the observer's zenith","definitionCN":"天球上过天极与观测者天顶的大圆","example":"Stars rise and culminate on the celestial meridian.","exampleCN":"恒星在天球子午圈上升起并达到中天。","why":"The zenith and the two celestial poles define one great circle, and observers track stars as they cross it.","whyCN":"天顶与两个天极确定一条大圆，观测者就在恒星越过它时进行追踪。"},{"no":"08","title":"Meridian passage or transit","titleCN":"中天：天体经过子午圈的时刻","definition":"the passage of a celestial body across the observer's meridian","definitionCN":"天体经过观测者子午圈的时刻","example":"The planet's meridian was predicted for midnight.","exampleCN":"那颗行星的中天时刻被预测在午夜。","why":"Once the line is fixed, the event of crossing it needs a name too, so astronomy uses meridian for the transit.","whyCN":"线固定之后，越过它的事件也需要名称，因此天文学用 meridian 指这次中天。"}],"etymology":{"intro":{"en":"Meridian comes from Latin meridianus 'of midday, southern', from meridies 'midday, south', itself from medius 'middle' and dies 'day'. Dates are approximate.","cn":"meridian 来自拉丁 meridianus「正午的、南方的」，源于 meridies「正午、南方」，而 meridies 由 medius「中间」与 dies「日」构成。年代均为约数。"},"items":[{"era":"LATIN MEDIUS","en":"Medius meant 'middle'; it marks the centre of the day, the point where the sun stands highest.","cn":"medius 意为「中间的」；它标出一天的中心，也就是太阳最高之处。"},{"era":"LATIN DIES","en":"Dies meant 'day'; its deeper origin is connected with a root for brightness, a reconstruction rather than a recorded form.","cn":"dies 意为「日、白天」；其更深来源与表示明亮的词根相关，属重构形式而非有记录的词。"},{"era":"LATIN MERIDIES","en":"Medius plus dies produced meridies, 'midday, and by extension the south', since the sun at noon stands toward the south in the northern hemisphere.","cn":"medius 加 dies 构成 meridies，意为「正午」，并引申为「南方」，因为北半球正午太阳位于南方。"},{"era":"LATIN MERIDIANUS","en":"Meridianus meant 'of midday or of the south'; this adjective passed through French and became the English noun meridian.","cn":"meridianus 意为「正午的、南方的」；这个形容词经法语演变为英语名词 meridian。"},{"era":"ENGLISH","en":"English meridian appears in the fourteenth century for noon and for the north-south line; the geographical reference sense developed in the sixteenth and seventeenth centuries.","cn":"英语 meridian 在 14 世纪出现，指正午与南北方向的线；作为经度参考的用法在 16 至 17 世纪发展起来。"},{"era":"UNCERTAIN FIRST DATES","en":"Source uncertain (first dates only): the acupuncture sense is a modern translation choice, and its exact first English use is not recorded.","cn":"来源不确定（仅首见年代）：经络义属现代翻译选择，其在英语中的确切首见年代未见记录。"}]},"similar":{"note":{"en":"Group one holds words that look like meridian; group two holds the lines, times and peaks it is confused with.","cn":"第一组是外形接近 meridian 的词；第二组是容易与它混淆的线、时刻与顶点概念。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"median","ipa":"/ˈmiːdiən/","tag":"middle value","definition":"From medius 'middle': the middle value in a set or a line through a midpoint, with no noon meaning.","definitionCN":"来自 medius「中间」：一组数的中间值或过中点的线，不含正午义。"},{"word":"medium","ipa":"/ˈmiːdiəm/","tag":"middle, means","definition":"The middle size or a means of communication; it shares medius but not the day.","definitionCN":"指中等尺寸或媒介；同出 medius，但与「日」无关。"},{"word":"meridional","ipa":"/məˈrɪdiənəl/","tag":"southern","definition":"The adjective from meridian in its 'south' sense: southern, or running north-south.","definitionCN":"由 meridian 的「南方」义变来的形容词：南方的，或南北走向的。"},{"word":"meridianal","ipa":"/məˈrɪdiənəl/","tag":"rare variant","definition":"An uncommon variant spelling of meridional; standard usage prefers meridional.","definitionCN":"meridional 的罕见异体拼写；标准用法多用 meridional。"}]},{"heading":"NEAR MEANING","entries":[{"word":"longitude","ipa":"/ˈlɒŋɡɪtjuːd/","tag":"the coordinate","definition":"The east-west angle measured from a meridian; a meridian is the line, longitude is the number.","definitionCN":"相对某子午线量出的东西角度；meridian 是线，longitude 是数值。"},{"word":"parallel","ipa":"/ˈpærəlel/","tag":"the crossing line","definition":"A latitude circle running east-west; it crosses meridians at right angles.","definitionCN":"东西走向的纬线圈，与子午线正交。"},{"word":"noon","ipa":"/nuːn/","tag":"the hour","definition":"The middle of the day, when the sun is highest; meridian can name the same moment formally.","definitionCN":"一天的正中、太阳最高之时；meridian 可正式地指同一时刻。"},{"word":"zenith","ipa":"/ˈzenɪθ/","tag":"the highest point","definition":"The point directly overhead, or figuratively the peak; the meridian passes through it.","definitionCN":"头顶正上方的点，或比喻的顶点；子午圈经过它。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Latin 'middle day', real navigation and real astronomy, not invented rhymes.","cn":"正常联想：真实的拉丁「一日之中」、真实的航海与真实的天文学，而非编造的顺口溜。"},"normal":[{"en":"Medius 'middle' + dies 'day': midday, then the north-south line the noon sun crosses.","cn":"medius「中间」+ dies「日」：正午，再指正午太阳经过的南北向线。"},{"en":"A meridian runs north-south; longitude is counted east and west from one chosen meridian.","cn":"子午线南北走向；经度从选定的那条本初子午线向东西计数。"},{"en":"Ante meridiem and post meridiem are the Latin phrases behind a.m. and p.m.","cn":"ante meridiem 与 post meridiem 就是 a.m. 与 p.m. 背后的拉丁短语。"},{"en":"The sun culminates, or crosses the meridian, at local noon.","cn":"太阳在当地正午达到中天，也就是经过子午圈。"},{"en":"Acupuncture meridians are channels, a metaphorical line running through the body.","cn":"针灸经络是通道，像一条穿过身体的比喻之线。"}],"abstract":[{"en":"Picture a shadow shrinking to nothing as the sun stands overhead.","cn":"想象太阳当顶时影子缩到几乎没有。"},{"en":"Picture a career that has reached its noon and can only move sideways.","cn":"想象一项事业已到正午，此后只能横向移动。"},{"en":"Picture a seam down the middle of a sphere, joining both ends.","cn":"想象一条从球体正中穿过、连接两端的接缝。"}]},"examples":[{"en":"The prime meridian passes through Greenwich.","cn":"本初子午线穿过格林尼治。"},{"en":"The ship's chronometer was set to the meridian of Greenwich.","cn":"船上的航海钟按格林尼治子午线设定。"},{"en":"His career reached its meridian in the 1990s.","cn":"他的事业在二十世纪九十年代达到顶点。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"meri（中间，如 medium）+ dian（日，如 diary 每日）→ 一日之中 → 正午、子午线","word":"meridian"},"root":"拉丁 meridies「正午、南方」= medius「中间」+ dies「日」；meridianus「正午的、南方的」经法语进入英语，兼指正午与南北向大圆。","sensesIntro":{"en":"Eight senses start from 'middle of the day': the north-south line the noon sun crosses, the zero line chosen for longitude, the hour of noon, the sun's culmination, the peak of a career, the body's channels, the sky's north-south circle, and the transit across it.","cn":"八个义项都从「一日之中」出发：正午太阳经过的南北线、被选作经度零点的线、正午时刻、太阳中天、事业顶点、身体通道、天球南北圈，以及越过它的事件。"},"semanticMap":{"core":{"en":"CORE IMAGE: the noon sun standing on an invisible north-south circle that runs through both poles and the observer's zenith.","cn":"核心意象：正午的太阳立在一条看不见的南北大圆上，这条圆穿过两极与观测者天顶。"},"chain":["MIDDAY","SUN AT PEAK","NORTH-SOUTH CIRCLE","ZERO LINE","HIGH POINT","BODY CHANNEL"],"branches":[{"senses":"S1 · S7","en":"THE LINE: the earth and the sky each draw the same north-south great circle.","cn":"线：地球与天空各自画出同一条南北大圆。"},{"senses":"S2","en":"ZERO BY AGREEMENT: one meridian is chosen as the zero for all the others.","cn":"约定的零度：选一条子午线作为其余各线的零点。"},{"senses":"S3 · S4 · S8","en":"THE MOMENT: noon, the sun's culmination and the star's transit are the same crossing seen as time.","cn":"时刻：正午、太阳中天与恒星中天，是同一次穿越在时间上的呈现。"},{"senses":"S5","en":"THE PEAK: a career at its height is the noon sun applied to a life.","cn":"顶点：事业的高处，就是正午太阳用于人生。"},{"senses":"S6","en":"THE BODY: a channel running through the body borrows the line's shape.","cn":"身体：贯穿身体的通道借用了线的形态。"}]},"affixes":{"intro":{"en":"Meridian is built from Latin words for 'middle' and 'day'; the same parts survive in midday, medius and the a.m./p.m. phrases.","cn":"meridian 由拉丁的「中间」与「日」两个词构成；同样的成分保存在 midday、medius 与 a.m./p.m. 短语中。"},"latinIntro":{"en":"Latin medius 'middle' and dies 'day' combine in meridies 'midday'; meridies yields meridianus and the English meridian, while medius also gives median and medium.","cn":"拉丁 medius「中间」与 dies「日」组合成 meridies「正午」；meridies 衍生 meridianus 与英语 meridian，而 medius 还衍生 median 与 medium。"},"items":[{"word":"medius","structure":"medius (Latin adjective, 'middle')","meaning":"middle","meaningCN":"中间的","example":"The root marks the centre of the day.","exampleCN":"这个词根标出一日之中。"},{"word":"dies","structure":"dies (Latin noun, 'day')","meaning":"day","meaningCN":"日；白天","example":"The second element names the day itself.","exampleCN":"第二个成分指「日」本身。"},{"word":"meridies","structure":"meridies (Latin noun, fifth declension)","meaning":"midday; south","meaningCN":"正午；南方","example":"At noon the sun stands toward the south.","exampleCN":"正午太阳位于南方。"},{"word":"meridianus","structure":"meridianus (Latin adjective)","meaning":"of midday; southern","meaningCN":"正午的；南方的","example":"The adjective became the English noun.","exampleCN":"这个形容词变成了英语名词。"},{"word":"meridian","structure":"meridianus (through French)","meaning":"a north-south great circle","meaningCN":"子午线","example":"The map marks every tenth meridian.","exampleCN":"地图每隔十条经线标一条。"},{"word":"meridional","structure":"meridian + -al (relating to)","meaning":"southern; north-south","meaningCN":"南方的；南北的","example":"Meridional winds brought warm air.","exampleCN":"南风带来了暖空气。"},{"word":"ante meridiem","structure":"ante 'before' + meridiem 'midday'","meaning":"before noon","meaningCN":"午前","example":"The office opens ante meridiem.","exampleCN":"办公室上午开门。"},{"word":"post meridiem","structure":"post 'after' + meridiem 'midday'","meaning":"after noon","meaningCN":"午后","example":"The train leaves post meridiem.","exampleCN":"火车下午出发。"},{"word":"median","structure":"medius + -anus (relating to)","meaning":"middle value","meaningCN":"中位数；中间的","example":"The median income rose slightly.","exampleCN":"收入中位数略有上升。"}],"latinEntries":[{"word":"medius","structure":"medius, media, medium (adjective)","meaning":"middle","meaningCN":"中间的"},{"word":"dies","structure":"dies, diei (m./f., fifth declension)","meaning":"day","meaningCN":"日；白天"},{"word":"meridies","structure":"meridies, meridiei (m., fifth declension)","meaning":"midday, south","meaningCN":"正午；南方"},{"word":"meridianus","structure":"meridianus, meridiana, meridianum (adjective)","meaning":"of midday, southern","meaningCN":"正午的；南方的"}]}},{"word":"polar","ipa_uk":"/ˈpəʊlə/","ipa_us":"/ˈpoʊlər/","definition_zh":"极地的；磁极的；极性的；截然对立的；极冷的","definition_en":"relating to a pole, especially the earth's polar regions, or to opposite extremes such as magnetic or electric poles","core_image":"一根磁针的两端分别指向相反方向，越靠近端点，方向越明确","scene":"极夜里的气象站外风声不断。Researchers at the station record polar winds during the long winter night.","sceneCN":"这里 polar 指「南极或北极地区的」（第 1 个义项：属于地球两极地带的）；句意为研究人员在漫长冬夜里记录极地风。图中可辨识物件：气象站、风向标、极光、雪地。","pos":[{"tag":"adj.","zh":"极地的；两极的"},{"tag":"adj.","zh":"磁极的；电极的；极性的"},{"tag":"adj.","zh":"截然相反的"}],"collocations":[{"phrase":"polar regions","zh":"极地地区"},{"phrase":"polar ice","zh":"极地冰盖"},{"phrase":"polar bear","zh":"北极熊"},{"phrase":"polar opposite","zh":"截然相反的事物"},{"phrase":"polar coordinates","zh":"极坐标"},{"phrase":"polar molecule","zh":"极性分子"}],"forms":[{"label":"比较级","form":"more polar"},{"label":"最高级","form":"most polar"},{"label":"副词（罕见）","form":"polarly"},{"label":"名词（极性）","form":"polarity"}],"derivatives":[{"word":"polarity","pos":"n.","zh":"极性；截然对立"},{"word":"polarize","pos":"v.","zh":"使极化；使两极分化"},{"word":"polarization","pos":"n.","zh":"极化；偏振；两极分化"},{"word":"polarizer","pos":"n.","zh":"偏振片；起偏器"},{"word":"bipolar","pos":"adj.","zh":"双极的；两极的"}],"senses":[{"no":"01","title":"Of the earth's polar regions","titleCN":"极地的：属于南北两极地带的","definition":"relating to the regions around the North or South Pole","definitionCN":"与北极或南极周围地区有关的","example":"Polar ice reflects most of the sunlight that reaches it.","exampleCN":"极地冰面把到达那里的大部分阳光反射出去。","why":"Polaris 'of the pole' names the axis end; the regions around that end are the polar regions.","whyCN":"polaris 意为「极的」，指轴的端点；围绕这个端点的地区就是极地。"},{"no":"02","title":"Of a magnetic pole","titleCN":"磁极的：与磁体两端有关的","definition":"relating to either end of a magnet, where its magnetic force is strongest","definitionCN":"与磁体两端、磁力最强处有关的","example":"The north polar end of the magnet attracted the iron clip.","exampleCN":"磁体的北极一端吸住了铁夹。","why":"Every magnet concentrates force at two ends, so the adjective polar describes anything belonging to those ends.","whyCN":"每块磁体都在两端集中磁力，因此 polar 形容属于这两端的事物。"},{"no":"03","title":"Having electric polarity","titleCN":"电极性的：分正负极的","definition":"relating to the positive and negative terminals of an electric source","definitionCN":"与电源正负两极有关的","example":"The polar terminals must not be reversed.","exampleCN":"极性端子不可接反。","why":"Electricity repeats the two-end pattern of magnetism, so the ends of a cell or battery are also called poles and their property polar.","whyCN":"电学重复了磁学的两端模式，因此电池两端也叫极，其性质也称 polar。"},{"no":"04","title":"Polar in chemistry","titleCN":"极性的：分子正负电荷中心不重合的","definition":"describing a molecule in which positive and negative charge centres are separated","definitionCN":"描述正负电荷中心分离的分子","example":"Water is a polar molecule, which is why it dissolves salt so well.","exampleCN":"水是极性分子，因此能很好地溶解盐。","why":"A molecule with separated charge ends behaves like a tiny magnet, so chemistry borrowed the magnetic word.","whyCN":"电荷两端分离的分子行为像一枚小磁体，化学因此借用了磁学的词。"},{"no":"05","title":"Polar coordinates","titleCN":"极坐标的：用半径与角度定位的","definition":"describing a coordinate system that fixes a point by distance from a pole and angle from an axis","definitionCN":"用离极点的距离与相对轴的角度定位的坐标系","example":"The radar plot uses polar coordinates rather than a square grid.","exampleCN":"雷达图使用极坐标，而不是方格网。","why":"The centre of the grid is treated as a pole, and every point is measured outward from it, so the system is called polar.","whyCN":"网格中心被当作极点，每一点都从那里向外量，因此这套坐标系叫极坐标。"},{"no":"06","title":"Directly opposite","titleCN":"截然相反的：处于两个对立端的","definition":"completely opposite in character or position","definitionCN":"性质或位置上完全对立的","example":"Their views on the issue are polar opposites.","exampleCN":"他们在这个问题上的观点截然相反。","why":"Two poles sit at the ends of one axis and face away from each other, so 'polar' pictures extreme opposition.","whyCN":"两极位于同一轴的两端、彼此背向，因此 polar 用来比喻极端的对立。"},{"no":"07","title":"Extremely cold","titleCN":"极冷的：像极地一样寒冷的","definition":"extremely cold, as in the polar regions","definitionCN":"像极地地区那样寒冷的","example":"A polar wind swept through the valley overnight.","exampleCN":"一夜之间，一股极冷的风扫过山谷。","why":"The polar regions are the coldest zones on earth, so the adjective extends from place to temperature.","whyCN":"极地是地球上最冷的区域，因此这个形容词从地点延伸到温度。"},{"no":"08","title":"Of the pole star","titleCN":"极星的：与北极星有关的","definition":"relating to the pole star, the star near the northern axis of the sky","definitionCN":"与靠近天球北轴的北极星有关的","example":"Sailors steered by the polar star before compasses were reliable.","exampleCN":"在指南针尚不可靠之前，水手靠北极星辨向。","why":"The star sits almost on the axis, so it is the polar star, the star of the pole.","whyCN":"这颗星几乎位于天轴上，因此是北极星，即「极之恒星」。"}],"etymology":{"intro":{"en":"Polar comes from Latin polaris 'of the pole', from polus 'pole, axis', which was borrowed from Greek polos 'pivot, axis'. Dates are approximate.","cn":"polar 来自拉丁 polaris「极的」，源于 polus「极、轴」，而 polus 借自希腊 polos「枢轴、轴」。年代均为约数。"},"items":[{"era":"GREEK POLOS","en":"Polos meant 'pivot, axis, the end of an axis', and also the vault of the sky turning on that axis. Its deeper origin is uncertain; connections to a 'turning' root are hypotheses.","cn":"polos 意为「枢轴、轴、轴的端点」，也指绕轴转动的天穹。其更深来源不确定；与「转动」词根的联系属假说。"},{"era":"LATIN POLUS","en":"Latin borrowed polos as polus, 'pole, especially the pole of the heavens'.","cn":"拉丁把 polos 借作 polus，意为「极，尤指天极」。"},{"era":"LATIN POLARIS","en":"Polus plus -alis 'relating to' gave polaris, 'of the pole'.","cn":"polus 加 -alis「与……有关的」构成 polaris「极的」。"},{"era":"ENGLISH","en":"English polar appears in the seventeenth century, first in astronomy and geography for the axis ends of the sky and earth.","cn":"英语 polar 在 17 世纪出现，最初用于天文与地理，指天空与地球的轴端。"},{"era":"SCIENCE SENSES","en":"In the nineteenth century physics and chemistry extended polar to magnetism, electricity and the charge separation of molecules.","cn":"19 世纪物理学与化学把 polar 扩展到磁性、电性与分子的电荷分离。"},{"era":"UNCERTAIN FIRST DATES","en":"Source uncertain (first dates only): the figurative sense 'directly opposite' and the chemical sense have no precisely recorded first English use; the Latin root is not in doubt.","cn":"来源不确定（仅首见年代）：比喻义「截然相反」与化学义在英语中的确切首见年代未见记录；拉丁词根则无争议。"}]},"similar":{"note":{"en":"Group one holds look-alike words that are not about poles; group two holds words about cold, ends and opposition.","cn":"第一组是外形相近但并不表示「极」的词；第二组是关于寒冷、端点与对立的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"poplar","ipa":"/ˈpɒplə/","tag":"tree, near sound","definition":"A tall fast-growing tree; it sounds close to polar but has nothing to do with axes or cold.","definitionCN":"一种高大速生的树；读音接近 polar，但与轴或寒冷无关。"},{"word":"solar","ipa":"/ˈsəʊlə/","tag":"sun, not pole","definition":"From sol 'sun': relating to the sun, as in solar energy; the first consonant differs from polar.","definitionCN":"来自 sol「太阳」：与太阳有关，如太阳能；首辅音与 polar 不同。"},{"word":"stellar","ipa":"/ˈstelə/","tag":"stars in general","definition":"From stella 'star': relating to stars, not specifically to the pole star.","definitionCN":"来自 stella「星」：与恒星有关，并非专指北极星。"},{"word":"polarity","ipa":"/pəˈlærəti/","tag":"the noun form","definition":"The state of having two opposite poles; it is the abstract noun built on polar, not a separate root.","definitionCN":"具有两个对立极的状态；由 polar 构成的抽象名词，并非另一词根。"}]},{"heading":"NEAR MEANING","entries":[{"word":"arctic","ipa":"/ˈɑːktɪk/","tag":"northern cold","definition":"Relating to the Arctic, the northern polar region named after the bear constellation.","definitionCN":"与北极地区有关，这一北方极区以熊座命名。"},{"word":"frigid","ipa":"/ˈfrɪdʒɪd/","tag":"very cold","definition":"Formally cold, often used of climate or manner; polar adds the image of the ice caps.","definitionCN":"正式地表示寒冷，常用于气候或态度；polar 另带冰盖意象。"},{"word":"opposite","ipa":"/ˈɒpəzɪt/","tag":"facing the other end","definition":"Placed on the other side or completely different; polar stresses the two ends of one axis.","definitionCN":"位于另一边或完全不同；polar 强调同一轴的两端。"},{"word":"magnetic","ipa":"/mæɡˈnetɪk/","tag":"of magnets","definition":"Relating to magnetism; polar can describe the ends of a magnet, while magnetic describes the force itself.","definitionCN":"与磁有关；polar 可形容磁体两端，magnetic 则形容磁力本身。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Greek pivot, real magnetism and real coordinate geometry, not invented rhymes.","cn":"正常联想：真实的希腊「枢轴」、真实的磁学与真实的坐标几何，而非编造的顺口溜。"},"normal":[{"en":"Polos 'axis' + -ar: belonging to one end of an axis.","cn":"polos「轴」+ -ar：属于轴的一端。"},{"en":"A magnet has two polar ends; a molecule with separated charge is polar too.","cn":"磁体有两个极性端；电荷分离的分子也是极性的。"},{"en":"Polar coordinates locate a point by distance from a central pole and angle from an axis.","cn":"极坐标用离中心极点的距离与相对轴的角度定位。"},{"en":"Polar opposites sit at the two ends of one line of argument.","cn":"截然相反的观点位于同一争论线的两端。"},{"en":"The polar star stands almost over the earth's northern axis.","cn":"北极星几乎位于地球北轴的正上方。"}],"abstract":[{"en":"Picture two magnets repelling each other no matter how you turn them.","cn":"想象两块磁体无论怎么转都互相排斥。"},{"en":"Picture a single street with one end in bright sun and the other under ice.","cn":"想象一条街，一端阳光明亮，另一端埋在冰下。"},{"en":"Picture a debate with two microphones at opposite ends of a long table.","cn":"想象一场辩论，两只麦克风分处长桌两端。"}]},"examples":[{"en":"Polar bears depend on sea ice to hunt.","cn":"北极熊依赖海冰捕猎。"},{"en":"Water is polar, so it dissolves many salts.","cn":"水是极性的，因此能溶解许多盐。"},{"en":"The two policies are polar opposites.","cn":"这两项政策截然相反。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"pole（极）+ ar（……的）→ 极的 → 极地的、磁极的、极性的","word":"polar"},"root":"拉丁 polaris「极的」= polus「极、轴」+ -alis；polus 借自希腊 polos「枢轴、轴」。","sensesIntro":{"en":"Eight senses all begin at one end of an axis: the frozen regions, the ends of a magnet and a battery, separated charges in a molecule, a coordinate centre, opposite extremes, extreme cold, and the star that marks the northern end.","cn":"八个义项都从轴的一端开始：冰封地区、磁体与电池的两端、分子中分离的电荷、坐标中心、对立的两端、极端的寒冷，以及标出北端的那颗星。"},"semanticMap":{"core":{"en":"CORE IMAGE: a needle whose two ends point opposite ways, each end defined by the axis it belongs to.","cn":"核心意象：一根两端指向相反方向的针，每一端都由它所属的轴来定义。"},"chain":["AXIS END","COLD ZONE","MAGNET END","CHARGE END","COORDINATE CENTRE","OPPOSITE EXTREME"],"branches":[{"senses":"S1 · S7","en":"PLACE AND TEMPERATURE: the polar regions are cold, and the word passes from place to weather.","cn":"地点与温度：极地寒冷，词义从地点转到天气。"},{"senses":"S2 · S3 · S4","en":"PHYSICAL ENDS: magnetism, electricity and molecular charge all repeat the two-end pattern.","cn":"物理的两端：磁、电与分子电荷都重复两端模式。"},{"senses":"S5","en":"GEOMETRY: a polar grid treats its centre as the pole from which everything is measured.","cn":"几何：极坐标网格把中心当作极点，一切从那里量起。"},{"senses":"S6","en":"OPPOSITION: two ends facing away become a picture of complete disagreement.","cn":"对立：两端背向而居，成为完全分歧的图景。"},{"senses":"S8","en":"THE SKY: the pole star marks the northern end of the celestial axis.","cn":"天空：北极星标出天球轴的北端。"}]},"affixes":{"intro":{"en":"Polar is pole plus an adjective ending; the same Latin root builds polarity, polarize and the international scientific vocabulary.","cn":"polar 是 pole 加形容词后缀；同一拉丁词根还构成 polarity、polarize 以及国际科学词汇。"},"latinIntro":{"en":"Greek polos 'pivot' became Latin polus 'pole'; polaris 'of the pole' adds -alis, and English polar, polarity and polarization continue the family.","cn":"希腊 polos「枢轴」变成拉丁 polus「极」；polaris「极的」加 -alis，英语 polar、polarity 与 polarization 延续这个词族。"},"items":[{"word":"polos","structure":"polos (Greek noun, 'pivot, axis')","meaning":"pivot; axis","meaningCN":"枢轴；轴","example":"The root names the line a sphere turns on.","exampleCN":"这个词根指球体转动所绕的线。"},{"word":"polus","structure":"polus (Latin noun, 'pole')","meaning":"pole","meaningCN":"极；天极","example":"Latin shortened the Greek word.","exampleCN":"拉丁缩短了这个希腊词。"},{"word":"polaris","structure":"polaris (Latin adjective, 'of the pole')","meaning":"of the pole","meaningCN":"极的","example":"Polaris also names the pole star.","exampleCN":"Polaris 也用作北极星的名称。"},{"word":"polar","structure":"polaris + English -ar","meaning":"relating to a pole","meaningCN":"极的；极性的","example":"The polar regions are warming fast.","exampleCN":"极地地区正在快速变暖。"},{"word":"polarity","structure":"polar + -ity (state)","meaning":"the state of having poles","meaningCN":"极性；对立","example":"The battery's polarity is marked on the case.","exampleCN":"电池的极性标在外壳上。"},{"word":"polarize","structure":"polar + -ize (make)","meaning":"to give polarity","meaningCN":"使极化；使分化","example":"The filter polarizes the light.","exampleCN":"滤片使光偏振。"},{"word":"polarization","structure":"polarize + -ation (action)","meaning":"the act of polarizing","meaningCN":"极化；偏振","example":"Political polarization increased.","exampleCN":"政治两极分化加剧。"},{"word":"polarizer","structure":"polarize + -er (one that does)","meaning":"a device that polarizes","meaningCN":"偏振片","example":"The photographer fitted a polarizer.","exampleCN":"摄影师装上了偏振片。"},{"word":"bipolar","structure":"bi- 'two' + polar","meaning":"having two poles","meaningCN":"双极的；两极的","example":"Bipolar disorder involves extreme mood swings.","exampleCN":"双相障碍表现为剧烈的情绪波动。"}],"latinEntries":[{"word":"polus","structure":"polus, poli (m., second declension)","meaning":"pole, especially of the heavens","meaningCN":"极；天极"},{"word":"polaris","structure":"polaris, polare (adjective)","meaning":"of the pole","meaningCN":"极的"},{"word":"polaritas","structure":"polaritas, polaritatis (f., third declension, Medieval Latin)","meaning":"polarity","meaningCN":"极性"}]}},{"word":"pole","ipa_uk":"/pəʊl/","ipa_us":"/poʊl/","definition_zh":"极；极点；杆；磁极；电极；对立的一端","definition_en":"either end of an axis, a long slender rod, or one of two opposite extremes","core_image":"地球的自转轴从球心穿出，两端各有一个点；旁边另立一根笔直的长木杆","scene":"河边的船工撑起木筏准备过浅滩。The boatman pushes the raft along the river with a long pole.","sceneCN":"这里 pole 指「一根细长的木杆或金属杆」（第 2 个义项：用于撑船、支撑或探测的长杆）；句意为船工用长杆把木筏撑过河面。图中可辨识物件：木筏、长杆、浅滩、河水。","pos":[{"tag":"n.","zh":"极；极点；磁极；电极"},{"tag":"n.","zh":"杆；竿；撑杆"},{"tag":"n.","zh":"（长度单位）杆"}],"collocations":[{"phrase":"the North Pole","zh":"北极"},{"phrase":"the South Pole","zh":"南极"},{"phrase":"magnetic pole","zh":"磁极"},{"phrase":"positive pole","zh":"正极"},{"phrase":"poles apart","zh":"相距极远；截然不同"},{"phrase":"fishing pole","zh":"钓鱼竿"}],"forms":[{"label":"复数","form":"poles"},{"label":"三单（撑船）","form":"poles"},{"label":"过去式","form":"poled"},{"label":"过去分词","form":"poled"},{"label":"现在分词","form":"poling"},{"label":"名词（极性）","form":"polarity"}],"derivatives":[{"word":"polar","pos":"adj.","zh":"极的；极性的"},{"word":"poleward","pos":"adj./adv.","zh":"向极地的"},{"word":"polestar","pos":"n.","zh":"北极星；指导原则"},{"word":"flagpole","pos":"n.","zh":"旗杆"},{"word":"poleaxe","pos":"n./v.","zh":"长柄斧；用斧砍倒"},{"word":"pole-vault","pos":"n./v.","zh":"撑杆跳"}],"senses":[{"no":"01","title":"Either end of the earth's axis","titleCN":"地极：地球自转轴的两端","definition":"either of the two points where the earth's axis of rotation meets its surface","definitionCN":"地球自转轴与地表相交的两个点之一","example":"Expeditions race to reach the South Pole.","exampleCN":"探险队竞相抵达南极点。","why":"Greek polos named the pivot of a turning sphere; the two ends of that axis are the poles.","whyCN":"希腊 polos 指旋转球体的枢轴；这条轴的两端就是极。"},{"no":"02","title":"A long slender rod","titleCN":"杆：细长的木杆或金属杆","definition":"a long slender piece of wood or metal used for support, pushing or fishing","definitionCN":"用于支撑、撑推或钓鱼的细长木杆或金属杆","example":"He planted a pole to mark the boundary.","exampleCN":"他竖了一根杆子来标出边界。","why":"This sense has a different origin: Old English pāl 'stake' from Latin palus 'stake', not from Greek polos.","whyCN":"这一义项来源不同：古英语 pāl「桩」来自拉丁 palus「桩」，而非希腊 polos。"},{"no":"03","title":"A magnetic pole","titleCN":"磁极：磁体磁力最强的两端","definition":"either of the two ends of a magnet where the magnetic force is concentrated","definitionCN":"磁体两端磁力集中的任一端","example":"Like poles repel each other.","exampleCN":"同名的磁极互相排斥。","why":"Magnetism was pictured as an axis with two ends, so those ends took the name of the earth's poles.","whyCN":"磁现象被想象成一条有两端的轴，这两端便沿用了地球「极」的名称。"},{"no":"04","title":"An electric terminal","titleCN":"电极：电源或电路的正负端","definition":"either of the two terminals of an electric cell or circuit","definitionCN":"电池或电路的两个端子之一","example":"Connect the red wire to the positive pole.","exampleCN":"把红线接到正极。","why":"Electricity inherited the two-end image from magnetism, so a battery's terminals are also poles.","whyCN":"电学从磁学继承了「两端」的意象，因此电池端子也叫极。"},{"no":"05","title":"One of two opposite extremes","titleCN":"对立的一端：两个极端之一","definition":"either of two opposite positions, opinions or tendencies","definitionCN":"两个对立立场、观点或倾向中的任一方","example":"The two candidates represent opposite poles of the party.","exampleCN":"两位候选人代表党内对立的两端。","why":"Two poles of an axis face opposite directions, which makes them a natural image for extreme opposition.","whyCN":"同一轴的两极朝向相反，因此自然成为极端对立的意象。"},{"no":"06","title":"The pole of a circle or sphere","titleCN":"极点：几何中与给定圆或球对应的点","definition":"a point related to a circle or sphere by a fixed geometric construction","definitionCN":"与给定圆或球通过固定几何构造相联系的点","example":"The pole of the great circle lies on the perpendicular axis.","exampleCN":"这个大圆的极点位于垂直轴上。","why":"Projective geometry keeps the axis-end meaning but defines the point by a relation instead of by the earth.","whyCN":"射影几何保留了「轴端」之义，但用几何关系而非地球来定义这个点。"},{"no":"07","title":"A unit of length","titleCN":"杆：英制长度单位，约五码半","definition":"a former unit of length equal to about five and a half yards, used in surveying","definitionCN":"旧时长度单位，约合五码半，用于测量","example":"The field measured ten poles across.","exampleCN":"这块地横量有十杆宽。","why":"The measuring rod itself became the unit, so a pole could mean both the stick and the length it marked.","whyCN":"测量用的杆本身成了单位，因此 pole 既可指杆，也可指它所标的长度。"},{"no":"08","title":"A pole of a dividing cell","titleCN":"细胞极：有丝分裂纺锤体的两端","definition":"either of the two ends of the spindle in a dividing cell, toward which chromosomes move","definitionCN":"分裂细胞纺锤体的两端，染色体分别移向那里","example":"The spindle fibres pull chromosomes toward each pole.","exampleCN":"纺锤丝把染色体拉向两极。","why":"A dividing cell behaves like a tiny sphere with an axis, so its spindle ends are called poles.","whyCN":"分裂的细胞像带轴的小球，因此纺锤体两端被称为极。"}],"etymology":{"intro":{"en":"Pole has two separate origins that happen to share a spelling: the geographic and magnetic pole from Greek polos 'axis', and the rod from Old English pāl 'stake', from Latin palus. Dates are approximate.","cn":"pole 有两个恰好同形的来源：地理与磁学的「极」来自希腊 polos「轴」，而「杆」来自古英语 pāl「桩」，再上溯拉丁 palus。年代均为约数。"},"items":[{"era":"GREEK POLOS","en":"Polos meant 'pivot, axis, end of an axis'. Its deeper origin is not established, and links to a 'turn' root are hypotheses.","cn":"polos 意为「枢轴、轴、轴端」。其更深来源未得到证明，与「转动」词根的联系属假说。"},{"era":"LATIN POLUS","en":"Latin polus 'pole, especially of the heavens' was borrowed from Greek and passed into English as pole.","cn":"拉丁 polus「极，尤指天极」借自希腊语，后进入英语作 pole。"},{"era":"OLD ENGLISH PAL","en":"The rod sense comes from Old English pāl 'stake, post', borrowed from Latin palus 'stake'. Palus 'stake' is a different word from palus 'marsh'.","cn":"「杆」义来自古英语 pāl「桩、柱」，借自拉丁 palus「桩」。palus「桩」与 palus「沼泽」是两个不同的词。"},{"era":"MAGNETIC SENSE","en":"From the sixteenth century the ends of a magnet were called poles by analogy with the earth's axis.","cn":"16 世纪起，磁体两端因类比地球轴端而被称为极。"},{"era":"EXTREME SENSE","en":"By the seventeenth century 'poles apart' and 'opposite poles' extended the axis image to opinions and positions.","cn":"到 17 世纪，poles apart 与 opposite poles 把轴端意象扩展到观点与立场。"},{"era":"UNCERTAIN FIRST DATES","en":"Source uncertain (first dates only): the exact first English use of the unit of length and of the cell-biology sense is not recorded; the two roots themselves are well documented.","cn":"来源不确定（仅首见年代）：长度单位与细胞生物学义在英语中的确切首见年代未见记录；两个词根本身都有充分文献。"}]},"similar":{"note":{"en":"Group one holds words that look or sound like pole; group two holds rods, ends and extremes.","cn":"第一组是外形或读音接近 pole 的词；第二组是关于杆、端点与极端的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"poll","ipa":"/pəʊl/","tag":"same sound","definition":"A survey of opinions or a vote; it sounds identical to pole but has no axis or rod meaning.","definitionCN":"指民意调查或投票；与 pole 同音，但没有轴或杆的意思。"},{"word":"pale","ipa":"/peɪl/","tag":"one letter","definition":"Light in colour, or a boundary stake; the vowel is different from pole.","definitionCN":"颜色浅的，或指界桩；元音与 pole 不同。"},{"word":"pool","ipa":"/puːl/","tag":"one letter","definition":"A small body of water or a shared fund; the vowel is long and different.","definitionCN":"小水塘或共用资金；元音更长且不同。"},{"word":"mole","ipa":"/məʊl/","tag":"one letter","definition":"A small burrowing animal or a spot on the skin; it shares the ending but not the meaning.","definitionCN":"穴居小动物或皮肤上的痣；词尾相同而意义无关。"}]},{"heading":"NEAR MEANING","entries":[{"word":"post","ipa":"/pəʊst/","tag":"a standing rod","definition":"A strong upright piece of timber or metal fixed in the ground; a pole may be movable and thinner.","definitionCN":"固定在地上的坚固立木或金属柱；pole 可能更细且可移动。"},{"word":"rod","ipa":"/rɒd/","tag":"a thin bar","definition":"A slim straight bar of wood or metal; pole is longer and often used for pushing.","definitionCN":"细直的木条或金属条；pole 更长，常用于撑推。"},{"word":"beam","ipa":"/biːm/","tag":"a structural bar","definition":"A heavy horizontal timber or metal bar that carries a load; it is structural, unlike a simple pole.","definitionCN":"承重的粗大水平木梁或金属梁；它是结构件，不同于普通杆。"},{"word":"extreme","ipa":"/ɪkˈstriːm/","tag":"the far end","definition":"The furthest point or most intense degree; a pole is one of two extremes facing each other.","definitionCN":"最远的点或最强的程度；pole 是彼此相对的两个极端之一。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: two real roots, real magnetism and real surveying, not invented rhymes.","cn":"正常联想：两个真实词根、真实的磁学与真实的测量，而非编造的顺口溜。"},"normal":[{"en":"Geographic pole comes from Greek polos 'axis'; rod pole comes from Latin palus 'stake'. Same spelling, different roots.","cn":"地理的 pole 来自希腊 polos「轴」；杆义的 pole 来自拉丁 palus「桩」。同形不同源。"},{"en":"The North Pole and South Pole are the two ends of the earth's rotation axis.","cn":"北极与南极是地球自转轴的两端。"},{"en":"Like magnetic poles repel, unlike poles attract.","cn":"同名磁极相斥，异名磁极相吸。"},{"en":"A battery has a positive pole and a negative pole.","cn":"电池有正极与负极。"},{"en":"Poles apart means as far apart as the two ends of an axis.","cn":"poles apart 意为像轴的两端那样相距极远。"}],"abstract":[{"en":"Picture two flags planted at the ends of a long straight road.","cn":"想象一条笔直长路的两端各插一面旗。"},{"en":"Picture a see-saw with one end up and the other down.","cn":"想象一块跷跷板，一端翘起、一端落下。"},{"en":"Picture a tent held up by one simple straight stick.","cn":"想象一顶帐篷只靠一根笔直的棍子撑起。"}]},"examples":[{"en":"The expedition reached the North Pole by dog sled.","cn":"探险队乘狗拉雪橇抵达北极。"},{"en":"He vaulted over the fence with a long pole.","cn":"他用一根长杆撑过栅栏。"},{"en":"Their political views are poles apart.","cn":"他们的政治观点截然相反。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"pole 有两个来源：地理「极」来自希腊轴心，长「杆」来自拉丁木桩；同形两义 → 极、杆","word":"pole"},"root":"地理与磁学的 pole 来自希腊 polos「轴」经拉丁 polus；杆义的 pole 来自古英语 pāl「桩」，再上溯拉丁 palus「桩」。两源同形异义。","sensesIntro":{"en":"Eight senses divide between an axis and a rod: the earth's two ends, a long stick, magnetic and electric terminals, opposite extremes, a geometric point, a unit of length, and the ends of a dividing cell.","cn":"八个义项分属「轴」与「杆」两条线：地球两端、长杆、磁极与电极、对立极端、几何极点、长度单位，以及分裂细胞的两极。"},"semanticMap":{"core":{"en":"CORE IMAGE: an axis emerging from a turning sphere at two ends, beside a single straight rod.","cn":"核心意象：一条轴从旋转球体的两端穿出，旁边另立一根笔直的长杆。"},"chain":["AXIS END","ROD","MAGNET END","CHARGE END","OPPOSITE EXTREME","GEOMETRIC POINT"],"branches":[{"senses":"S1 · S3 · S4","en":"TWO ENDS: earth, magnet and battery all concentrate their force at a pair of ends.","cn":"两端：地球、磁体与电池都把力集中在成对的两端。"},{"senses":"S2 · S7","en":"THE ROD: a stick becomes a tool and then a unit of length.","cn":"杆：一根棍子成为工具，再成为长度单位。"},{"senses":"S5","en":"OPPOSITION: two ends facing away become a picture of extreme disagreement.","cn":"对立：两端背向而居，成为极端分歧的图景。"},{"senses":"S6","en":"GEOMETRY: a circle or sphere defines a matching point on its axis.","cn":"几何：圆或球在它的轴上定义一个对应的点。"},{"senses":"S8","en":"CELL: a dividing cell's spindle has two ends that pull chromosomes apart.","cn":"细胞：分裂细胞的纺锤体有两端，把染色体拉向两边。"}]},"affixes":{"intro":{"en":"Pole carries two Latin roots that look alike in English: polus 'axis' and palus 'stake'. Compounds such as flagpole come from the rod, while polar and polarity come from the axis.","cn":"pole 在英语中合并了两个外形相近的拉丁词根：polus「轴」与 palus「桩」。flagpole 等复合词来自「杆」，polar 与 polarity 来自「轴」。"},"latinIntro":{"en":"Greek polos 'axis' gives Latin polus, English pole, polar and polarity; Latin palus 'stake' gives Old English pāl, English pole 'rod' and palisade.","cn":"希腊 polos「轴」衍生拉丁 polus、英语 pole、polar 与 polarity；拉丁 palus「桩」衍生古英语 pāl、英语 pole「杆」与 palisade。"},"items":[{"word":"polos","structure":"polos (Greek noun, 'pivot, axis')","meaning":"pivot; axis","meaningCN":"枢轴；轴","example":"The axis has two ends.","exampleCN":"这条轴有两个端点。"},{"word":"polus","structure":"polus (Latin noun, 'pole')","meaning":"pole of the heavens","meaningCN":"天极","example":"The Latin word entered English as pole.","exampleCN":"这个拉丁词进入英语作 pole。"},{"word":"pole","structure":"polus (axis sense)","meaning":"end of an axis","meaningCN":"极；极点","example":"The South Pole is colder than the coast.","exampleCN":"南极点比海岸更冷。"},{"word":"palus","structure":"palus (Latin noun, 'stake')","meaning":"stake; post","meaningCN":"桩；柱","example":"A different Latin word from polus.","exampleCN":"这是与 polus 不同的拉丁词。"},{"word":"palisade","structure":"palus + -ade (a set of)","meaning":"a fence of stakes","meaningCN":"木桩栅栏","example":"A palisade surrounded the old fort.","exampleCN":"旧堡垒四周有木桩栅栏。"},{"word":"flagpole","structure":"flag + pole (rod)","meaning":"a pole for a flag","meaningCN":"旗杆","example":"The flagpole stands in the square.","exampleCN":"旗杆立在广场上。"},{"word":"maypole","structure":"May + pole (rod)","meaning":"a decorated spring pole","meaningCN":"五月柱","example":"Dancers circled the maypole.","exampleCN":"舞者绕着五月柱转圈。"},{"word":"poleaxe","structure":"pole (rod) + axe","meaning":"a long-handled axe","meaningCN":"长柄斧","example":"The woodman swung a poleaxe.","exampleCN":"伐木工挥起长柄斧。"},{"word":"pole-vault","structure":"pole (rod) + vault","meaning":"jumping with a pole","meaningCN":"撑杆跳","example":"She cleared the bar in the pole-vault.","exampleCN":"她在撑杆跳中越过了横杆。"},{"word":"polar","structure":"polus + -ar","meaning":"of the pole","meaningCN":"极的","example":"Polar winds are bitterly cold.","exampleCN":"极地风冷得刺骨。"}],"latinEntries":[{"word":"polus","structure":"polus, poli (m., second declension)","meaning":"pole, axis end","meaningCN":"极；轴端"},{"word":"palus","structure":"palus, pali (m., second declension)","meaning":"stake, post","meaningCN":"桩；柱"},{"word":"polaris","structure":"polaris, polare (adjective)","meaning":"of the pole","meaningCN":"极的"}]}},{"word":"tropic","ipa_uk":"/ˈtrɒpɪk/","ipa_us":"/ˈtrɑːpɪk/","definition_zh":"回归线；热带地区；（古）转折点","definition_en":"either of the two parallels of latitude where the sun stands directly overhead at the solstice","core_image":"太阳在天空缓缓北移，到达一条界线后停住并折返，那条界线就是回归线","scene":"课本上的图示标出太阳直射点折返的那条界线。The diagram marks the Tropic of Cancer, where the noon sun stands overhead in June and then turns back.","sceneCN":"这里 tropic 指「太阳在夏至正午直射并随后折返的纬线」（第 1 个义项：北回归线）；句意为示意图标出北回归线，六月正午太阳在此当顶，随后转向南移。图中可辨识物件：地球、太阳光线、回归线、箭头。","pos":[{"tag":"n.","zh":"回归线；热带地区"},{"tag":"adj.","zh":"热带的（作定语）"},{"tag":"n.","zh":"转折点（古义）"}],"collocations":[{"phrase":"the Tropic of Cancer","zh":"北回归线"},{"phrase":"the Tropic of Capricorn","zh":"南回归线"},{"phrase":"the tropics","zh":"热带地区"},{"phrase":"north of the Tropic","zh":"回归线以北"},{"phrase":"the tropic sun","zh":"热带的太阳"},{"phrase":"the celestial tropic","zh":"天球回归线"}],"forms":[{"label":"复数","form":"tropics"},{"label":"形容词（热带的）","form":"tropical"},{"label":"副词（热带地）","form":"tropically"},{"label":"名词（向性）","form":"tropism"}],"derivatives":[{"word":"tropical","pos":"adj.","zh":"热带的；回归线的"},{"word":"tropically","pos":"adv.","zh":"在热带地区地"},{"word":"tropics","pos":"n.","zh":"热带地区"},{"word":"tropism","pos":"n.","zh":"向性；趋性"},{"word":"subtropical","pos":"adj.","zh":"亚热带的"}],"senses":[{"no":"01","title":"The Tropic of Cancer","titleCN":"北回归线：太阳北移的极限纬线","definition":"the northern parallel at about twenty-three and a half degrees north, where the sun is overhead at the June solstice","definitionCN":"约北纬二十三度半、夏至时太阳直射的纬线","example":"The Tropic of Cancer crosses the Sahara and southern China.","exampleCN":"北回归线穿过撒哈拉与中国南方。","why":"Greek trope 'a turn' names the line where the sun turns back; the northern one is named for the sign the sun entered.","whyCN":"希腊 trope「转折」命名太阳折返之处；北面那条因太阳进入的星座而得名。"},{"no":"02","title":"The Tropic of Capricorn","titleCN":"南回归线：太阳南移的极限纬线","definition":"the southern parallel at about twenty-three and a half degrees south, where the sun is overhead at the December solstice","definitionCN":"约南纬二十三度半、冬至时太阳直射的纬线","example":"The Tropic of Capricorn runs through Australia and southern Africa.","exampleCN":"南回归线穿过澳大利亚与非洲南部。","why":"The southern line is the same turn seen from the other hemisphere, named for the sign the sun enters in December.","whyCN":"南面这条线是从另一半球看到的同一次折返，因太阳十二月进入的星座而得名。"},{"no":"03","title":"The tropics as a region","titleCN":"热带地区：南北回归线之间的地带","definition":"the region of the earth between the two tropics","definitionCN":"地球上两条回归线之间的地带","example":"Coffee and bananas grow throughout the tropics.","exampleCN":"咖啡与香蕉在整个热带地区都有种植。","why":"The two lines bound a belt, and the plural name of the lines became the name of the belt.","whyCN":"两条线围出一条带，线的复数名称就成了这条带的名称。"},{"no":"04","title":"Tropical, as an attributive adjective","titleCN":"热带的：作定语的形容词用法","definition":"relating to the tropics, used before a noun","definitionCN":"与热带有关的，用于名词前","example":"Tropic heat and moisture favour dense forest.","exampleCN":"热带的炎热与湿润有利于密林生长。","why":"English often uses the shorter tropic before a noun where tropical would also fit, a clipped attributive use.","whyCN":"英语在名词前常用较短的 tropic，而 tropical 同样适用，这是截短的定语用法。"},{"no":"05","title":"The celestial tropic","titleCN":"天球回归线：太阳在天球上的折返圈","definition":"either of the two circles on the celestial sphere marking the sun's greatest declination","definitionCN":"天球上标出太阳最大赤纬的两条圈之一","example":"The celestial tropic touches the ecliptic at the solstice points.","exampleCN":"天球回归线在二至点与黄道相切。","why":"The sky repeats the terrestrial limit in its own circles, marking where the sun's declination stops.","whyCN":"天空用它自己的圈重复地表的界限，标出太阳赤纬停止之处。"},{"no":"06","title":"A turning point, archaic","titleCN":"转折点：事情转向的时刻（古义）","definition":"a point of turning or change, the older general sense of the Greek root","definitionCN":"转向或改变的时刻，即希腊词根的较早一般义","example":"The old text speaks of the tropic of fortune.","exampleCN":"那篇旧文谈到命运的转折点。","why":"The root's general sense of turning survives in older writing about any change of course.","whyCN":"词根的一般「转向」义在谈论任何路线改变的旧文字中留存。"},{"no":"07","title":"A tropic response in biology","titleCN":"向性的：生物对刺激转向的反应","definition":"describing a movement or growth directed by a stimulus such as light or gravity","definitionCN":"描述由光、重力等刺激引导的运动或生长","example":"Roots show a tropic response to gravity.","exampleCN":"根对重力表现出向性反应。","why":"A plant organ turns toward or away from a stimulus, which is the root's literal 'turn' applied to growth.","whyCN":"植物器官朝刺激转向或背离，正是词根字面的「转」用于生长。"},{"no":"08","title":"The torrid zone between the tropics","titleCN":"热带地带：两回归线之间的气候带","definition":"the hot climate belt lying between the two tropics","definitionCN":"位于两条回归线之间的炎热气候带","example":"The torrid zone receives the sun almost vertically all year.","exampleCN":"热带地带全年几乎接受垂直照射的阳光。","why":"The belt between the lines stays hot because the sun remains high there throughout the year.","whyCN":"两线之间的地带之所以炎热，是因为太阳全年都保持在较高位置。"}],"etymology":{"intro":{"en":"Tropic comes from Latin tropicus, from Greek tropikos 'of a turn, of the solstice', built on trope 'a turn' and trepein 'to turn'. The lines are named for the sun's turning at the solstices. Dates are approximate.","cn":"tropic 来自拉丁 tropicus，源于希腊 tropikos「转折的、至点的」，由 trope「转折」与 trepein「转动」构成；这两条线因太阳在二至点折返而得名。年代均为约数。"},"items":[{"era":"GREEK TROPE","en":"Trope meant 'a turn, a turning', especially of the sun or of a argument.","cn":"trope 意为「转折、转向」，尤指太阳的折返或论证的转折。"},{"era":"GREEK TREPEIN","en":"Trepein meant 'to turn'. The noun and verb form one of the most productive roots in Greek.","cn":"trepein 意为「转动」。这个名词与动词构成希腊语中最多产的词根之一。"},{"era":"GREEK TROPIKOS","en":"Tropikos meant 'of a turn', and in astronomy 'of the solstice', because the sun appears to turn back there.","cn":"tropikos 意为「转折的」，在天文学中指「至点的」，因为太阳在那里看似折返。"},{"era":"LATIN TROPICUS","en":"Latin borrowed the adjective as tropicus; the noun tropicus circulus named the solstitial circle.","cn":"拉丁把这个形容词借作 tropicus；名词短语 tropicus circulus 指至点圈。"},{"era":"ENGLISH","en":"English tropic appears in the sixteenth century for the two solstitial parallels, and the plural tropics soon named the belt between them.","cn":"英语 tropic 在 16 世纪出现，指两条至点纬线；复数 the tropics 很快指它们之间的地带。"},{"era":"UNCERTAIN FIRST DATES","en":"Source uncertain (first dates only): the biological 'tropic response' sense and the archaic 'turning point' sense have no precisely dated first English use; the Greek root is not in doubt.","cn":"来源不确定（仅首见年代）：生物学的「向性反应」义与古义「转折点」在英语中的确切首见年代未见记录；希腊词根则无争议。"}]},"similar":{"note":{"en":"Group one holds words that look or sound like tropic; group two holds the lines and belts it belongs to.","cn":"第一组是外形或读音接近 tropic 的词；第二组是它所归属的线与地带。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"topic","ipa":"/ˈtɒpɪk/","tag":"one letter","definition":"A subject of discussion, from Greek ta topika 'things about places'; it is not related to turning.","definitionCN":"讨论的主题，来自希腊 ta topika「关于处所之事」；与「转动」无关。"},{"word":"trophy","ipa":"/ˈtrəʊfi/","tag":"near spelling","definition":"A prize or memorial, from Greek tropaion 'a rout of the enemy'; the root is different.","definitionCN":"奖品或纪念物，来自希腊 tropaion「击溃敌人」；词根不同。"},{"word":"tropism","ipa":"/ˈtrəʊpɪzəm/","tag":"same turn root","definition":"A directed growth response to a stimulus, built on the same Greek trope 'turn'.","definitionCN":"对刺激的有方向生长反应，同出希腊 trope「转」。"},{"word":"trope","ipa":"/trəʊp/","tag":"the root itself","definition":"A figurative turn of phrase, literally a 'turning' of meaning.","definitionCN":"比喻性的说法，字面就是意义的「转向」。"}]},{"heading":"NEAR MEANING","entries":[{"word":"equator","ipa":"/ɪˈkweɪtə/","tag":"the middle line","definition":"The zero-latitude circle halfway between the tropics, where day and night are equal.","definitionCN":"两条回归线正中的零度纬线，那里昼夜等长。"},{"word":"latitude","ipa":"/ˈlætɪtjuːd/","tag":"the measurement","definition":"Angular distance from the equator; the tropics are two particular latitudes.","definitionCN":"相对赤道的角距离；回归线是两个特定的纬度。"},{"word":"parallel","ipa":"/ˈpærəlel/","tag":"the line type","definition":"Any circle parallel to the equator; a tropic is one named parallel.","definitionCN":"与赤道平行的任一圈；回归线是其中有名的一条。"},{"word":"solstice","ipa":"/ˈsɒlstɪs/","tag":"the turning moment","definition":"The two times of year when the sun reaches its greatest declination and turns back.","definitionCN":"一年中太阳到达最大赤纬并折返的两个时刻。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Greek 'turn', real solstice astronomy and real geography, not invented rhymes.","cn":"正常联想：真实的希腊「转」、真实的至点天文与真实地理，而非编造的顺口溜。"},"normal":[{"en":"Trope 'a turn' + -ic: the line where the sun turns back at the solstice.","cn":"trope「转折」+ -ic：太阳在至点折返的那条线。"},{"en":"The Tropic of Cancer is northern; the Tropic of Capricorn is southern.","cn":"北回归线在北，南回归线在南。"},{"en":"The tropics lie between the two tropics and are hot all year.","cn":"the tropics 位于两条回归线之间，全年炎热。"},{"en":"The same Greek root gives tropism, a plant's turning response to light.","cn":"同一希腊词根衍生 tropism，即植物对光的转向反应。"},{"en":"Celestial tropics mark the sun's greatest declination on the sky.","cn":"天球回归线标出太阳在天球上的最大赤纬。"}],"abstract":[{"en":"Picture a pendulum that swings north and stops just before returning.","cn":"想象一只向北摆动的摆锤，在返回前停住。"},{"en":"Picture a path with two marked fences, beyond which the sun never goes overhead.","cn":"想象一条路两侧各有一道标线，太阳从不越过它们当顶。"},{"en":"Picture a conversation that changes direction at a single sharp word.","cn":"想象一场对话在一个尖刻的词上突然转向。"}]},"examples":[{"en":"The Tropic of Cancer passes through the northern hemisphere.","cn":"北回归线穿过北半球。"},{"en":"Rainforests cover much of the tropics.","cn":"雨林覆盖了热带地区的大部分。"},{"en":"The sun stands overhead at the tropic on the solstice.","cn":"至点时太阳在回归线上当顶。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"trop（转，如 trope 转义）+ ic → 太阳折返的线 → 回归线、热带","word":"tropic"},"root":"希腊 tropikos「转折的、至点的」= trope「转折」+ -ikos；源于 trepein「转动」，指太阳在二至点折返的纬线。拉丁 tropicus，英语 16 世纪借入。","sensesIntro":{"en":"Eight senses revolve around one turn: the two solstitial parallels where the sun reverses, the belt they enclose, the attributive use, the sky's corresponding circles, the old 'turning point', the biological turning response, and the hot zone itself.","cn":"八个义项围绕一次「折返」：太阳转向的两条至点纬线、它们围出的地带、定语用法、天空中的对应圈、古义「转折点」、生物学的转向反应，以及炎热地带本身。"},"semanticMap":{"core":{"en":"CORE IMAGE: the sun moving north or south, reaching a marked line, and turning back.","cn":"核心意象：太阳向北或向南移动，到达一条标线后折返。"},"chain":["SUN MOVES","REACHES LIMIT","TURNS BACK","MARKED PARALLEL","HOT BELT","TURNING POINT"],"branches":[{"senses":"S1 · S2","en":"TWO LIMITS: the northern and southern parallels mark the two ends of the sun's yearly swing.","cn":"两条界线：南北两条纬线标出太阳一年摆动的两端。"},{"senses":"S3 · S8","en":"THE BELT: the space between the lines becomes a hot region and a climate zone.","cn":"地带：两线之间的空间成为炎热地区与气候带。"},{"senses":"S4","en":"ATTRIBUTIVE: the short form works before a noun as a clipped adjective.","cn":"定语：较短形式可在名词前作截短形容词。"},{"senses":"S5","en":"SKY: the celestial tropics mirror the earthly limits on the celestial sphere.","cn":"天空：天球回归线在天球上镜像地表的界限。"},{"senses":"S6 · S7","en":"TURNING: the old sense names any turning point, and biology names a growth response that turns toward a stimulus.","cn":"转折：古义指任何转折点，生物学则指朝刺激转向的生长反应。"}]},"affixes":{"intro":{"en":"Tropic is an adjective from Greek 'turn'; its family includes tropical, tropism and trope, all built on the same root.","cn":"tropic 是来自希腊「转」的形容词；其词族包括 tropical、tropism 与 trope，均建于同一词根。"},"latinIntro":{"en":"Greek trope 'a turn' and trepein 'to turn' give tropikos, Latin tropicus and English tropic; the same root yields tropical and tropism, while trophy comes from a different Greek branch, tropaion 'a rout'.","cn":"希腊 trope「转折」与 trepein「转动」衍生 tropikos、拉丁 tropicus 与英语 tropic；同一词根还衍生 tropical 与 tropism，而 trophy 来自另一支希腊词 tropaion「击溃」。"},"items":[{"word":"trepein","structure":"trepein (Greek verb, 'to turn')","meaning":"to turn","meaningCN":"转动","example":"The verb supplies the action of turning.","exampleCN":"这个动词提供「转动」的动作。"},{"word":"trope","structure":"trope (Greek noun, 'a turn')","meaning":"a turn","meaningCN":"转折；转向","example":"A trope in rhetoric is a turn of meaning.","exampleCN":"修辞中的 trope 是意义的转向。"},{"word":"tropikos","structure":"tropikos (Greek adjective, 'of a turn')","meaning":"of a turn; of the solstice","meaningCN":"转折的；至点的","example":"The adjective named the solstitial circle.","exampleCN":"这个形容词命名至点圈。"},{"word":"tropicus","structure":"tropicus (Latin adjective)","meaning":"of the solstice","meaningCN":"至点的","example":"Latin kept the Greek meaning.","exampleCN":"拉丁保留了希腊含义。"},{"word":"tropic","structure":"tropicus (through French)","meaning":"a solstitial parallel","meaningCN":"回归线","example":"The Tropic of Cancer marks the northern limit.","exampleCN":"北回归线标出北界。"},{"word":"tropical","structure":"tropic + -al (relating to)","meaning":"of the tropics","meaningCN":"热带的","example":"Tropical forests are humid all year.","exampleCN":"热带森林全年湿润。"},{"word":"tropics","structure":"tropic + -s (plural region)","meaning":"the hot belt","meaningCN":"热带地区","example":"The tropics receive heavy rain.","exampleCN":"热带地区降雨丰沛。"},{"word":"tropism","structure":"trope + -ism (directed action)","meaning":"a turning response","meaningCN":"向性","example":"Phototropism bends a shoot toward light.","exampleCN":"向光性使幼苗朝光弯曲。"},{"word":"subtropical","structure":"sub- 'near' + tropical","meaning":"nearly tropical","meaningCN":"亚热带的","example":"Subtropical fruits need mild winters.","exampleCN":"亚热带水果需要温和的冬天。"}],"latinEntries":[{"word":"tropus","structure":"tropus, tropi (m., second declension)","meaning":"a turn, figure","meaningCN":"转折；转义"},{"word":"tropicus","structure":"tropicus, tropica, tropicum (adjective)","meaning":"of the solstice","meaningCN":"至点的"},{"word":"solstitium","structure":"solstitium, solstitii (n., second declension)","meaning":"solstice","meaningCN":"至点；夏至或冬至"}]}},{"word":"tropical","ipa_uk":"/ˈtrɒpɪkl/","ipa_us":"/ˈtrɑːpɪkl/","definition_zh":"热带的；热带气候的；回归线的；热带病的","definition_en":"relating to the tropics, the hot belt of the earth between the two tropics","core_image":"层叠的雨林树冠在正午阳光下蒸腾出水汽，叶面被照得发亮","scene":"雨林树冠层整天水汽蒸腾。Botanists study the layered canopy of a tropical rainforest.","sceneCN":"这里 tropical 指「属于热带雨林的」（第 6 个义项：与热带雨林生态系统有关的）；句意为植物学家研究热带雨林层层叠叠的树冠。图中可辨识物件：树冠层、藤蔓、水汽、阳光。","pos":[{"tag":"adj.","zh":"热带的；热带气候的"},{"tag":"adj.","zh":"回归线的；热带病的"}],"collocations":[{"phrase":"tropical rainforest","zh":"热带雨林"},{"phrase":"tropical climate","zh":"热带气候"},{"phrase":"tropical storm","zh":"热带风暴"},{"phrase":"tropical medicine","zh":"热带医学"},{"phrase":"tropical fruit","zh":"热带水果"},{"phrase":"tropical year","zh":"回归年"}],"forms":[{"label":"比较级","form":"more tropical"},{"label":"最高级","form":"most tropical"},{"label":"副词","form":"tropically"},{"label":"名词（热带地区）","form":"tropics"}],"derivatives":[{"word":"tropically","pos":"adv.","zh":"在热带地区地；热带地"},{"word":"subtropics","pos":"n.","zh":"亚热带地区"},{"word":"subtropical","pos":"adj.","zh":"亚热带的"},{"word":"tropicalization","pos":"n.","zh":"热带化（生态学术语）"}],"senses":[{"no":"01","title":"Located in the tropics","titleCN":"热带的：位于南北回归线之间的","definition":"situated in or belonging to the belt between the two tropics","definitionCN":"位于或属于两条回归线之间地带的","example":"Tropical countries often have a wet and a dry season.","exampleCN":"热带国家常有雨季与旱季。","why":"Tropic 'turn' names the lines where the sun reverses; everything inside those lines is tropical, the adjective of the belt.","whyCN":"tropic「转折」命名太阳折返的界线；两条线以内的一切都是 tropical，即这条地带的形容词。"},{"no":"02","title":"Hot and humid","titleCN":"湿热的：热带气候那样炎热潮湿的","definition":"characteristically hot and humid, as the tropics are","definitionCN":"像热带那样炎热而潮湿的","example":"The tropical heat made midday work impossible.","exampleCN":"湿热的天气让正午干活变得不可能。","why":"The belt's climate, not only its position, is hot and wet, so the adjective also describes the weather itself.","whyCN":"这条带不仅位置在热带，气候也炎热潮湿，因此这个形容词也描述天气本身。"},{"no":"03","title":"The tropical year","titleCN":"回归年：太阳两次经过春分点之间的时间","definition":"the period between two successive returns of the sun to the vernal equinox","definitionCN":"太阳连续两次回到春分点之间的时间","example":"A tropical year is slightly shorter than the calendar year.","exampleCN":"回归年比日历年略短。","why":"The 'tropical' year is the year measured by the sun's turning points, the solstices and equinoxes, not by the stars.","whyCN":"「回归」年是按太阳折返点（至点与二分点）测量的年，而不是按恒星测量。"},{"no":"04","title":"A tropical storm","titleCN":"热带风暴：在热带海域生成的风暴","definition":"a storm that forms over warm tropical waters and may develop into a hurricane","definitionCN":"在热带暖水面上生成、可能发展成飓风的风暴","example":"The tropical storm strengthened as it crossed the warm sea.","exampleCN":"热带风暴越过温暖海面时增强。","why":"A storm born over the warm belt carries the belt's name before it grows into a hurricane.","whyCN":"在暖带生成的风暴，在发展为飓风之前带着这条带的名字。"},{"no":"05","title":"Tropical medicine","titleCN":"热带医学的：研究热带常见疾病的","definition":"relating to the branch of medicine concerned with diseases common in hot climates","definitionCN":"与研究炎热气候常见疾病的医学分支有关的","example":"Tropical medicine focuses on malaria and other warm-climate diseases.","exampleCN":"热带医学关注疟疾和其它暖气候疾病。","why":"Medicine names the field by the climate zone where these diseases are common.","whyCN":"医学按这些疾病常见的气候带命名这一领域。"},{"no":"06","title":"Tropical rainforest","titleCN":"热带雨林的：与赤道附近多雨森林有关的","definition":"relating to the dense evergreen forest of the wet tropics","definitionCN":"与湿润热带地区常绿密林有关的","example":"Botanists study the layered canopy of a tropical rainforest.","exampleCN":"植物学家研究热带雨林层层叠叠的树冠。","why":"The rainforest is the belt's typical vegetation, so the adjective attaches to the ecosystem as well as to the region.","whyCN":"雨林是这条带最典型的植被，因此这个形容词既修饰地区也修饰生态系统。"},{"no":"07","title":"Of the Tropic circles","titleCN":"回归线的：与南北回归线有关的（天文）","definition":"relating to the Tropic of Cancer or the Tropic of Capricorn","definitionCN":"与北回归线或南回归线有关的","example":"The tropical circle marks the sun's greatest declination.","exampleCN":"回归圈标出太阳的最大赤纬。","why":"The adjective can also attach to the two astronomical circles themselves.","whyCN":"这个形容词也可以直接修饰那两条天文学上的圈。"},{"no":"08","title":"Adapted to tropical conditions","titleCN":"热带风格的：为湿热气候设计的","definition":"describing building or planting designed for hot, humid conditions","definitionCN":"描述为炎热潮湿环境而设计的建筑或种植方式","example":"Tropical architecture uses deep shade and cross ventilation.","exampleCN":"热带建筑采用深遮阳与穿堂风。","why":"Designers borrow the word to mean 'made for the tropics', extending the adjective from nature to human craft.","whyCN":"设计者借这个词表示「为热带而造」，把形容词从自然延伸到人造物。"}],"etymology":{"intro":{"en":"Tropical is tropic plus the adjective ending -al; tropic comes from Greek tropikos 'of a turn', from trope 'a turn'. The climatic sense grew from the belt between the two turning circles. Dates are approximate.","cn":"tropical 是 tropic 加形容词后缀 -al；tropic 来自希腊 tropikos「转折的」，源于 trope「转折」。气候义从两条折返圈之间的地带发展而来。年代均为约数。"},"items":[{"era":"GREEK TROPE","en":"Trope meant 'a turn'; the sun's apparent reversal at the solstice is the model for the name.","cn":"trope 意为「转折」；太阳在至点看似折返，是命名的原型。"},{"era":"GREEK TROPIKOS","en":"Tropikos meant 'of a turn or of the solstice'; it named the two parallels where the reversal happens.","cn":"tropikos 意为「转折的、至点的」；它命名折返发生的两条纬线。"},{"era":"LATIN TROPICUS","en":"Latin tropicus continued the Greek adjective, and the derived noun tropicus circulus named the solstitial circle.","cn":"拉丁 tropicus 延续这个希腊形容词，派生名词 tropicus circulus 指至点圈。"},{"era":"ENGLISH TROPIC","en":"English tropic appears in the sixteenth century; tropical follows as its adjective in the same period.","cn":"英语 tropic 在 16 世纪出现；tropical 作为其形容词也在同一时期出现。"},{"era":"CLIMATIC EXTENSION","en":"Because the belt between the tropics is hot and wet, tropical came to mean the climate and ecology of that belt, then anything built for it.","cn":"由于回归线之间的地带炎热潮湿，tropical 转指该带的气候与生态，再指为其建造之物。"},{"era":"UNCERTAIN FIRST DATES","en":"Source uncertain (first dates only): the medical and architectural uses have no precisely dated first English citation; the Greek root is secure.","cn":"来源不确定（仅首见年代）：医学与建筑用法在英语中的确切首见年代未见记录；希腊词根可靠。"}]},"similar":{"note":{"en":"Group one holds words that look like tropical; group two holds climate words that are often contrasted with it.","cn":"第一组是外形接近 tropical 的词；第二组是常与它对照的气候词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"topical","ipa":"/ˈtɒpɪkl/","tag":"one letter","definition":"Relating to a subject or to the surface of the body; from Greek topos 'place', not from 'turn'.","definitionCN":"与主题或身体表面有关；来自希腊 topos「处所」，与「转」无关。"},{"word":"tropic","ipa":"/ˈtrɒpɪk/","tag":"the base word","definition":"The parallel of latitude itself, or the hot belt; tropical is its adjective.","definitionCN":"指回归线本身或热带地带；tropical 是它的形容词。"},{"word":"subtropical","ipa":"/ˌsʌbˈtrɒpɪkl/","tag":"near, not inside","definition":"The zone just outside the tropics, with warm but less extreme conditions.","definitionCN":"紧邻热带外侧的地带，温暖但不那么极端。"},{"word":"tropics","ipa":"/ˈtrɒpɪks/","tag":"the region noun","definition":"The belt between the two tropics; it names the place, not a quality.","definitionCN":"两条回归线之间的地带；它指地方，不指性质。"}]},{"heading":"NEAR MEANING","entries":[{"word":"torrid","ipa":"/ˈtɒrɪd/","tag":"hot and dry","definition":"Formally 'burning', used for the hot zone and for intense heat; tropical stresses moisture as well as heat.","definitionCN":"正式意为「灼热的」，用于热带或酷热；tropical 同时强调潮湿。"},{"word":"equatorial","ipa":"/ˌiːkwəˈtɔːriəl/","tag":"on the equator","definition":"Relating to the equator itself, a narrower band than the whole tropics.","definitionCN":"与赤道本身有关，范围比整个热带窄。"},{"word":"humid","ipa":"/ˈhjuːmɪd/","tag":"moist air","definition":"Having a lot of water vapour; it names one feature of tropical weather, not the region.","definitionCN":"空气含水汽多；它只指热带天气的一个特征，不指地区。"},{"word":"temperate","ipa":"/ˈtempərət/","tag":"mild contrast","definition":"Neither very hot nor very cold; it is the zone beyond the tropics and often contrasted with tropical.","definitionCN":"既不很热也不很冷；位于热带之外，常与 tropical 对照。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real 'turn' root, real climate zones and real rainforest ecology, not invented rhymes.","cn":"正常联想：真实的「转」词根、真实的气候带与真实的雨林生态，而非编造的顺口溜。"},"normal":[{"en":"Tropic 'turn' + -al: belonging to the belt where the sun turns back.","cn":"tropic「转折」+ -al：属于太阳折返的那条带。"},{"en":"Tropical rainforest, tropical storm and tropical medicine are all fixed phrases built on the same adjective.","cn":"tropical rainforest、tropical storm 与 tropical medicine 都是同一形容词构成的固定搭配。"},{"en":"The tropics are the region; tropical is what belongs to it.","cn":"the tropics 是地区；tropical 是属于该地区的性质。"},{"en":"A tropical year is measured by the sun's turning points, not by the stars.","cn":"回归年按太阳的折返点计算，而非按恒星。"},{"en":"Tropical architecture answers heat and humidity with shade and airflow.","cn":"热带建筑用遮阳与通风应对炎热潮湿。"}],"abstract":[{"en":"Picture a greenhouse that never cools and never dries.","cn":"想象一座从不降温、也从不干燥的温室。"},{"en":"Picture a calendar page marked only by the sun's turning.","cn":"想象一页日历，只按太阳的折返来标记。"},{"en":"Picture a house whose roof floats above the walls to let air pass.","cn":"想象一座屋顶浮在墙上方、让空气穿过的房子。"}]},"examples":[{"en":"Tropical forests absorb huge amounts of carbon.","cn":"热带森林吸收大量碳。"},{"en":"The tropical storm was upgraded to a hurricane overnight.","cn":"热带风暴一夜之间升级为飓风。"},{"en":"She studies tropical diseases in coastal clinics.","cn":"她在沿海诊所研究热带疾病。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"tropic（回归线、热带）+ al（……的）→ 热带的、湿热的","word":"tropical"},"root":"tropic + -al；tropic 来自希腊 tropikos「转折的、至点的」（trope「转折」+ -ikos），指太阳在至点折返的纬线，其内侧地带即热带。","sensesIntro":{"en":"Eight senses extend one adjective from place to weather, to the sun's year, to storms, medicine, rainforest, the tropic circles themselves, and finally to design made for the belt.","cn":"八个义项把这一个形容词从地点扩展到天气、太阳年、风暴、医学、雨林、回归圈本身，最后到为这条带而做的设计。"},"semanticMap":{"core":{"en":"CORE IMAGE: a hot, wet belt between two lines where the sun turns, and everything that belongs to it.","cn":"核心意象：两条太阳折返线之间一条炎热潮湿的带，以及属于这条带的一切。"},"chain":["TURNING LINES","HOT BELT","WET HEAT","SUN'S YEAR","STORM AND DISEASE","RAINFOREST"],"branches":[{"senses":"S1 · S7","en":"THE BELT AND ITS LINES: the region inside the tropics and the circles that bound it.","cn":"地带与界线：热带以内的区域及围出它的圈。"},{"senses":"S2 · S8","en":"HEAT AND DESIGN: the climate itself, and human building adapted to it.","cn":"炎热与设计：气候本身，以及为适应它的人造物。"},{"senses":"S3","en":"THE SOLAR YEAR: the year measured by the sun's turning points.","cn":"太阳年：按太阳折返点计的年。"},{"senses":"S4 · S5","en":"HAZARD AND MEDICINE: warm-water storms and the diseases of hot climates.","cn":"灾害与医学：暖水风暴与炎热气候的疾病。"},{"senses":"S6","en":"ECOLOGY: the rainforest is the belt's richest ecosystem.","cn":"生态：雨林是这条带最丰富的生态系统。"}]},"affixes":{"intro":{"en":"Tropical is built on tropic plus -al; the same Greek root supplies tropism and trope, while sub- adds the zone just outside.","cn":"tropical 由 tropic 加 -al 构成；同一希腊词根还提供 tropism 与 trope，前缀 sub- 则加出紧邻外侧的地带。"},"latinIntro":{"en":"Greek trope 'turn' gives tropikos, Latin tropicus and English tropic; -al makes tropical, and sub- makes subtropical, the belt just beyond.","cn":"希腊 trope「转」衍生 tropikos、拉丁 tropicus 与英语 tropic；-al 构成 tropical，sub- 构成 subtropical，即紧邻外侧的地带。"},"items":[{"word":"trope","structure":"trope (Greek noun, 'a turn')","meaning":"a turn","meaningCN":"转折","example":"The root names the sun's reversal.","exampleCN":"词根指太阳的折返。"},{"word":"tropikos","structure":"tropikos (Greek adjective, 'of a turn')","meaning":"of the solstice","meaningCN":"至点的","example":"The adjective named the solstitial lines.","exampleCN":"这个形容词命名至点线。"},{"word":"tropicus","structure":"tropicus (Latin adjective)","meaning":"of the solstice","meaningCN":"至点的","example":"Latin kept the Greek sense.","exampleCN":"拉丁保留希腊含义。"},{"word":"-al","structure":"-alis (Latin adjective suffix, 'relating to')","meaning":"relating to","meaningCN":"与……有关的","example":"The suffix turns the noun into a descriptive adjective.","exampleCN":"后缀把名词变成描述性形容词。"},{"word":"tropical","structure":"tropic + -al","meaning":"of the tropics","meaningCN":"热带的","example":"Tropical soil is often thin in nutrients.","exampleCN":"热带土壤常常养分稀薄。"},{"word":"tropically","structure":"tropical + -ly (adverb)","meaning":"in a tropical way","meaningCN":"热带地","example":"The plant grows tropically in glasshouses.","exampleCN":"这种植物在温室里像在热带一样生长。"},{"word":"tropics","structure":"tropic + -s (plural region)","meaning":"the hot belt","meaningCN":"热带地区","example":"The tropics span three continents.","exampleCN":"热带横跨三个大洲。"},{"word":"subtropical","structure":"sub- 'near' + tropical","meaning":"nearly tropical","meaningCN":"亚热带的","example":"Subtropical air brought warm rain.","exampleCN":"亚热带空气带来暖雨。"},{"word":"tropism","structure":"trope + -ism (directed action)","meaning":"a turning response","meaningCN":"向性","example":"Phototropism turns shoots toward light.","exampleCN":"向光性使幼苗朝光转。"}],"latinEntries":[{"word":"tropus","structure":"tropus, tropi (m., second declension)","meaning":"a turn, figure","meaningCN":"转折；转义"},{"word":"tropicus","structure":"tropicus, tropica, tropicum (adjective)","meaning":"of the solstice","meaningCN":"至点的"},{"word":"tropicalis","structure":"tropicalis, tropicale (adjective, Medieval Latin)","meaning":"tropical","meaningCN":"热带的"}]}},{"word":"subtropical","ipa_uk":"/ˌsʌbˈtrɒpɪkl/","ipa_us":"/ˌsʌbˈtrɑːpɪkl/","definition_zh":"亚热带的；亚热带气候的；副热带的","definition_en":"relating to the region or climate just outside the tropics, warm but not fully tropical","core_image":"柑橘树长在山坡上，身后是尚有余热的阳光，前方已吹来温带的风","scene":"山坡上的果园种着柑橘与茶树。Farmers grow citrus and tea in the warm subtropical hills.","sceneCN":"这里 subtropical 指「位于热带外侧、气候温暖的亚热带地区的」（第 1 个义项：紧邻热带但尚未进入热带的纬度地带）；句意为农民在温暖的亚热带山坡上种植柑橘与茶树。图中可辨识物件：梯田果园、柑橘、茶树、远山。","pos":[{"tag":"adj.","zh":"亚热带的；亚热带气候的"},{"tag":"n.","zh":"亚热带地区（复数）"}],"collocations":[{"phrase":"subtropical climate","zh":"亚热带气候"},{"phrase":"subtropical region","zh":"亚热带地区"},{"phrase":"subtropical high","zh":"副热带高压"},{"phrase":"subtropical cyclone","zh":"副热带气旋"},{"phrase":"subtropical fruits","zh":"亚热带水果"},{"phrase":"subtropical jet","zh":"副热带急流"}],"forms":[{"label":"名词复数（地区）","form":"subtropics"},{"label":"比较级","form":"more subtropical"},{"label":"最高级","form":"most subtropical"},{"label":"副词","form":"subtropically"}],"derivatives":[{"word":"subtropic","pos":"adj.","zh":"亚热带的（异体）"},{"word":"subtropics","pos":"n.","zh":"亚热带地区"},{"word":"subtropically","pos":"adv.","zh":"亚热带地"}],"senses":[{"no":"01","title":"Just outside the tropics","titleCN":"亚热带的：紧邻热带外侧的","definition":"lying in the belt immediately outside the tropics, usually between about twenty-three and a half and thirty-five degrees of latitude","definitionCN":"位于热带紧邻外侧的地带，通常约在二十三度半到三十五度纬度之间","example":"The orchard lies in the subtropical belt north of the Tropic of Cancer.","exampleCN":"这片果园位于北回归线以北的亚热带地带。","why":"Sub- 'below, near' plus tropical gives 'nearly tropical'; the belt sits just beyond the turning lines without entering them.","whyCN":"sub-「在下、靠近」加 tropical 构成「近乎热带」；这条带紧贴折返线之外，但未进入热带。"},{"no":"02","title":"Warm climate with mild winters","titleCN":"亚热带气候的：冬暖夏热的","definition":"describing a climate with hot summers and mild, rarely freezing winters","definitionCN":"描述夏热、冬暖且极少结冰的气候","example":"Subtropical climates support citrus orchards and winter vegetables.","exampleCN":"亚热带气候适合柑橘园与冬季蔬菜。","why":"The zone's latitude gives it warm summers and mild winters, so the adjective describes climate as well as position.","whyCN":"这条带的纬度带来暖夏与暖冬，因此形容词既描述位置也描述气候。"},{"no":"03","title":"The subtropical high","titleCN":"副热带高压的：副热带高压带的","definition":"relating to the belt of high atmospheric pressure centred near thirty degrees latitude","definitionCN":"与中心位于约三十度纬度的副热带高压带有关的","example":"The subtropical high brings settled, dry weather in summer.","exampleCN":"副热带高压在夏季带来稳定干燥的天气。","why":"Meteorology names the pressure belt by the latitude zone where it sits.","whyCN":"气象学按气压带所在的纬度地带为其命名。"},{"no":"04","title":"A subtropical cyclone","titleCN":"副热带气旋的：兼具热带与中纬度特征的气旋","definition":"describing a cyclone that shares features of tropical and mid-latitude systems","definitionCN":"描述兼具热带与中纬度特征的气旋","example":"A subtropical cyclone can form over cooler water than a tropical one.","exampleCN":"副热带气旋可在比热带气旋更冷的水面上形成。","why":"The storm mixes tropical and mid-latitude behaviour, so the prefix marks the in-between position.","whyCN":"这种风暴混合了热带与中纬度行为，因此前缀标出居中的位置。"},{"no":"05","title":"Subtropical crops","titleCN":"亚热带作物的：属于亚热带农业的","definition":"relating to crops grown in warm, frost-free belts outside the tropics","definitionCN":"与热带外侧温暖无霜地带的作物有关的","example":"Subtropical crops include tea, citrus and olives.","exampleCN":"亚热带作物包括茶、柑橘与油橄榄。","why":"Crops follow the climate, and the zone's frost-free warmth supports citrus and tea.","whyCN":"作物随气候分布，这条带无霜的暖意支撑柑橘与茶。"},{"no":"06","title":"The subtropical jet","titleCN":"副热带急流的：副热带高空强风带的","definition":"relating to the strong upper-air wind belt found near the edge of the tropics","definitionCN":"与热带边缘附近的高空强风带有关的","example":"The subtropical jet steers winter storms across the region.","exampleCN":"副热带急流引导冬季风暴穿过该地区。","why":"The jet runs along the edge of the tropical belt, so it takes the same marginal label.","whyCN":"急流沿热带边缘运行，因此带着同样的「边缘」标签。"},{"no":"07","title":"The subtropics as a region","titleCN":"亚热带地区：把该地带当作地区","definition":"the regions lying just outside the tropics, taken as a whole","definitionCN":"热带外侧各地带的总称","example":"The subtropics are home to many of the world's largest coastal cities.","exampleCN":"亚热带地区是世界许多最大沿海城市的所在地。","why":"Once a belt is named, its plural can stand for the places inside it.","whyCN":"地带一旦有了名称，其复数形式就可以指带内的各个地方。"},{"no":"08","title":"Subtropical vegetation","titleCN":"亚热带植被的：常绿阔叶与棕榈混生的","definition":"describing the mixed evergreen and palm vegetation of warm marginal belts","definitionCN":"描述温暖边缘地带常绿阔叶与棕榈混生的植被","example":"Subtropical vegetation mixes palms with broadleaf trees.","exampleCN":"亚热带植被把棕榈与阔叶树混在一起。","why":"Vegetation is the visible signature of the zone's warmth.","whyCN":"植被是这条带暖意最可见的标志。"}],"etymology":{"intro":{"en":"Subtropical is Latin sub- 'under, near' joined to tropical. The term belongs to nineteenth-century geography and climatology, when the globe was divided into tropical, subtropical and temperate belts. Dates are approximate.","cn":"subtropical 是拉丁 sub-「在下、靠近」加 tropical。这个词属于 19 世纪地理学与气候学，当时全球被划为热带、亚热带与温带。年代均为约数。"},"items":[{"era":"LATIN SUB","en":"Sub- meant 'under, below, close to'; in compounds it marks a position just short of the main thing.","cn":"sub- 意为「在下、低于、靠近」；在复合词中表示略低于或紧邻主要事物。"},{"era":"GREEK TROPICUS","en":"The second element is the tropic adjective from Greek tropikos 'of a turn', the line where the sun reverses.","cn":"第二个成分是来自希腊 tropikos「转折的」的 tropic 形容词，指太阳折返的线。"},{"era":"NINETEENTH-CENTURY GEOGRAPHY","en":"Geographers divided the globe into tropical, subtropical, temperate and polar belts, and subtropical named the margin just outside the tropics.","cn":"地理学家把全球划为热带、亚热带、温带与极地，subtropical 指热带外侧的边缘。"},{"era":"CLIMATOLOGY","en":"Twentieth-century meteorology added the subtropical high, the subtropical jet and the subtropical cyclone.","cn":"20 世纪气象学增添了副热带高压、副热带急流与副热带气旋。"},{"era":"UNCERTAIN FIRST DATES","en":"Source uncertain (first dates only): no precise first English citation is recorded for the climate term, though its formation is transparent; the Latin and Greek roots are certain.","cn":"来源不确定（仅首见年代）：这一气候词在英语中的确切首见年代未见记录，但其构词透明；拉丁与希腊词根可靠。"}]},"similar":{"note":{"en":"Group one holds words that look like subtropical; group two holds neighbouring climate terms it is often confused with.","cn":"第一组是外形接近 subtropical 的词；第二组是容易与之混淆的邻近气候词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"tropical","ipa":"/ˈtrɒpɪkl/","tag":"inside the lines","definition":"Belonging to the belt between the tropics; subtropical is the margin outside it.","definitionCN":"属于两条回归线之间的地带；subtropical 是它外面的边缘。"},{"word":"subtropic","ipa":"/ˌsʌbˈtrɒpɪk/","tag":"short variant","definition":"A rare shortened adjective with the same meaning as subtropical.","definitionCN":"罕见的缩短形容词，意义与 subtropical 相同。"},{"word":"subtropics","ipa":"/ˌsʌbˈtrɒpɪks/","tag":"the noun","definition":"The regions just outside the tropics, taken as a place rather than a quality.","definitionCN":"热带外侧的地区，指地方而非性质。"},{"word":"tropic","ipa":"/ˈtrɒpɪk/","tag":"the base line","definition":"Either of the two parallels where the sun turns; it is the boundary, not the belt beyond.","definitionCN":"太阳折返的两条纬线之一；它是边界，不是外面的带。"}]},{"heading":"NEAR MEANING","entries":[{"word":"semitropical","ipa":"/ˌsemiˈtrɒpɪkl/","tag":"halfway label","definition":"Partly tropical in character, often used loosely for warm marginal zones.","definitionCN":"性质上部分属热带，常用于宽泛地指温暖的边缘地带。"},{"word":"warm-temperate","ipa":"/wɔːm ˈtempərət/","tag":"the next belt out","definition":"A temperate zone with mild winters, lying beyond the subtropics.","definitionCN":"冬季温和的温带，位于亚热带之外。"},{"word":"temperate","ipa":"/ˈtempərət/","tag":"mild zone","definition":"Neither hot nor cold; it begins where the subtropical margin ends.","definitionCN":"既不热也不冷；从亚热带边缘结束处开始。"},{"word":"torrid","ipa":"/ˈtɒrɪd/","tag":"the hot zone","definition":"The old name for the belt between the tropics, stressing heat rather than position.","definitionCN":"旧时对回归线之间地带的称呼，强调炎热而非位置。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real sub- prefix, real climate belts and real meteorology, not invented rhymes.","cn":"正常联想：真实的 sub- 前缀、真实的气候带与真实的气象学，而非编造的顺口溜。"},"normal":[{"en":"Sub- 'near' + tropical: the belt that is nearly, but not quite, tropical.","cn":"sub-「靠近」+ tropical：几乎算热带、但还不算热带的带。"},{"en":"Subtropical climate means hot summers and mild winters, good for citrus.","cn":"亚热带气候意为夏热冬暖，适合柑橘。"},{"en":"The subtropical high is a belt of dry descending air near thirty degrees latitude.","cn":"副热带高压是约三十度纬度附近一条干爽的下沉气流带。"},{"en":"The subtropics hold many coastal megacities.","cn":"亚热带地区拥有许多沿海大城市。"},{"en":"Subtropical vegetation mixes palms and broadleaf trees.","cn":"亚热带植被把棕榈与阔叶树混生在一起。"}],"abstract":[{"en":"Picture a warm room next to a hot room, sharing one wall.","cn":"想象一间温暖的房间紧挨着一间炎热的房间，共用一堵墙。"},{"en":"Picture a hillside where oranges grow but snow still visits once a year.","cn":"想象一片山坡，柑橘能长，但每年仍会下一次雪。"},{"en":"Picture a map with a soft border rather than a sharp line.","cn":"想象一张地图，边界是柔和的过渡而不是硬线。"}]},"examples":[{"en":"The city has a subtropical climate with humid summers.","cn":"这座城市属亚热带气候，夏季潮湿。"},{"en":"Subtropical fruits such as lychee grow in the south.","cn":"荔枝等亚热带水果在南方生长。"},{"en":"The subtropical high dominated the weather for weeks.","cn":"副热带高压连续数周主导天气。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"sub（在下、靠近）+ tropical（热带的）→ 靠近热带 → 亚热带的","word":"subtropical"},"root":"拉丁 sub-「在下、靠近」+ tropical；tropical 来自 tropic（希腊 tropikos「转折的」）+ -al，指热带外侧的温暖地带。","sensesIntro":{"en":"Eight senses all place one adjective just outside the tropics: the latitude belt, its mild climate, the high-pressure and jet systems, cyclones, crops, the region as a noun, and its mixed vegetation.","cn":"八个义项都把同一个形容词放在热带外侧：纬度带、温和气候、高压与急流系统、气旋、作物、作为名词的地区，以及混生植被。"},"semanticMap":{"core":{"en":"CORE IMAGE: a warm hillside just beyond the line where the sun turns, close to the tropics but not inside them.","cn":"核心意象：紧贴太阳折返线外侧的一片温暖山坡，靠近热带却不在其中。"},"chain":["BORDER ZONE","WARM CLIMATE","HIGH PRESSURE","CYCLONE","CROPS","VEGETATION"],"branches":[{"senses":"S1 · S7","en":"THE PLACE: the belt and the region it forms when taken as a whole.","cn":"地方：这条带，以及把它整体看待时形成的地区。"},{"senses":"S2 · S8","en":"CLIMATE AND LIFE: mild warmth supports crops and a mixed evergreen vegetation.","cn":"气候与生命：温和的暖意支撑作物与混生常绿植被。"},{"senses":"S3 · S6","en":"THE AIR: the subtropical high and subtropical jet are the belt's large-scale wind systems.","cn":"空气：副热带高压与副热带急流是这条带的大尺度风系。"},{"senses":"S4","en":"STORMS: a subtropical cyclone mixes tropical and mid-latitude behaviour.","cn":"风暴：副热带气旋混合了热带与中纬度的行为。"},{"senses":"S5","en":"AGRICULTURE: citrus, tea and olives mark the zone in farming.","cn":"农业：柑橘、茶与油橄榄在农耕上标出这条带。"}]},"affixes":{"intro":{"en":"Subtropical is a transparent compound of a Latin prefix and the adjective tropical; its family includes the noun subtropics and the rare short form subtropic.","cn":"subtropical 是拉丁前缀与形容词 tropical 构成的透明复合词；其词族包括名词 subtropics 与罕见短形式 subtropic。"},"latinIntro":{"en":"Latin sub 'under, near' attaches to tropicus 'of the solstice'; English builds subtropical, subtropics and subtropically on that base.","cn":"拉丁 sub「在下、靠近」加在 tropicus「至点的」上；英语由此构成 subtropical、subtropics 与 subtropically。"},"items":[{"word":"sub-","structure":"sub- (Latin prefix, 'under, near')","meaning":"under; near","meaningCN":"在下；靠近","example":"The prefix marks a position just short of the tropics.","exampleCN":"这个前缀标出略未达到热带的位置。"},{"word":"tropicus","structure":"tropicus (Latin adjective, 'of the solstice')","meaning":"of the solstice","meaningCN":"至点的","example":"The second element is the tropic adjective.","exampleCN":"第二个成分是 tropic 形容词。"},{"word":"tropical","structure":"tropic + -al","meaning":"of the tropics","meaningCN":"热带的","example":"Tropical air lies closer to the equator.","exampleCN":"热带空气更靠近赤道。"},{"word":"subtropic","structure":"sub- + tropic (short form)","meaning":"nearly tropical","meaningCN":"亚热带的","example":"The short form appears in older botanical writing.","exampleCN":"这一短形式见于较早的植物学文字。"},{"word":"subtropical","structure":"sub- + tropical","meaning":"just outside the tropics","meaningCN":"亚热带的","example":"Subtropical rain fell for three days.","exampleCN":"亚热带降雨持续了三天。"},{"word":"subtropics","structure":"subtropical + -s (plural region)","meaning":"the marginal belts","meaningCN":"亚热带地区","example":"The subtropics supply much of the world's tea.","exampleCN":"亚热带地区供应世界大部分茶叶。"},{"word":"subtropically","structure":"subtropical + -ly (adverb)","meaning":"in a subtropical way","meaningCN":"亚热带地","example":"The valley is subtropically warm in winter.","exampleCN":"这条山谷冬季暖如亚热带。"},{"word":"subpolar","structure":"sub- 'near' + polar","meaning":"nearly polar","meaningCN":"副极地的","example":"Subpolar lows drive winter storms.","exampleCN":"副极地低压驱动冬季风暴。"},{"word":"subarctic","structure":"sub- 'near' + arctic","meaning":"nearly arctic","meaningCN":"亚北极的","example":"Subarctic forest gives way to tundra.","exampleCN":"亚北极森林过渡为苔原。"}],"latinEntries":[{"word":"sub","structure":"sub (Latin preposition and prefix)","meaning":"under, below, near","meaningCN":"在下；低于；靠近"},{"word":"tropicus","structure":"tropicus, tropica, tropicum (adjective)","meaning":"of the solstice","meaningCN":"至点的"},{"word":"tropicalis","structure":"tropicalis, tropicale (adjective, Medieval Latin)","meaning":"tropical","meaningCN":"热带的"}]}},{"word":"temperate","ipa_uk":"/ˈtempərət/","ipa_us":"/ˈtempərət/","definition_zh":"温带的；气候温和的；有节制的；适度的","definition_en":"having a mild climate, or showing moderation and self-restraint","core_image":"一支温度计停在刻度中间，既没有顶到上端，也没有落到底部","scene":"海边小镇四季分明，冬天不冷得刺骨。Residents enjoy a temperate climate with mild winters and cool summers.","sceneCN":"这里 temperate 指「气候温和、冬夏都不走极端的」（第 2 个义项：气候温和、温度适中的）；句意为居民享有冬季温和、夏季凉爽的温带气候。图中可辨识物件：海滨小镇、温度计、树影、海面。","pos":[{"tag":"adj.","zh":"温带的；气候温和的"},{"tag":"adj.","zh":"有节制的；适度的"}],"collocations":[{"phrase":"temperate climate","zh":"温带气候；温和气候"},{"phrase":"temperate zone","zh":"温带"},{"phrase":"temperate latitudes","zh":"温带纬度"},{"phrase":"temperate rainforest","zh":"温带雨林"},{"phrase":"temperate habits","zh":"有节制的生活习惯"},{"phrase":"temperate language","zh":"措辞克制的语言"}],"forms":[{"label":"比较级","form":"more temperate"},{"label":"最高级","form":"most temperate"},{"label":"副词","form":"temperately"},{"label":"名词（节制；温和）","form":"temperateness"}],"derivatives":[{"word":"temperance","pos":"n.","zh":"节制；戒酒"},{"word":"temper","pos":"n./v.","zh":"脾气；使缓和"},{"word":"temperament","pos":"n.","zh":"性情；气质"},{"word":"temperature","pos":"n.","zh":"温度；体温"},{"word":"tempered","pos":"adj.","zh":"经过回火的；有……脾气的"},{"word":"intemperate","pos":"adj.","zh":"无节制的；放纵的"}],"senses":[{"no":"01","title":"The temperate zone","titleCN":"温带的：位于热带与极圈之间的","definition":"belonging to the zone between the tropics and the polar circles","definitionCN":"位于回归线与极圈之间的地带","example":"The country lies in the northern temperate zone.","exampleCN":"这个国家位于北温带。","why":"Temperare 'to mix in due proportion' gives 'moderated'; the zone is named for its moderate temperature between two extremes.","whyCN":"temperare「按适当比例调和」引申出「有节制的」；温带因处于两个极端之间的适中温度而得名。"},{"no":"02","title":"Mild, not extreme","titleCN":"气候温和的：不酷热也不严寒的","definition":"having a climate that is neither very hot nor very cold","definitionCN":"气候既不很热也不很冷的","example":"Residents enjoy a temperate climate with mild winters and cool summers.","exampleCN":"居民享有冬季温和、夏季凉爽的温带气候。","why":"The zone's name comes from 'moderated', and mildness is that due proportion applied to climate.","whyCN":"这条带的名称来自「被调和」，温和就是这种适度用于气候。"},{"no":"03","title":"Self-restrained","titleCN":"有节制的：能约束自己的","definition":"showing moderation and restraint in behaviour or speech","definitionCN":"在行为或言语上表现克制与适度的","example":"He gave a temperate reply even under provocation.","exampleCN":"即使受到挑衅，他的回答仍然克制。","why":"The Latin verb meant to keep something within due measure, and that moral sense survives beside the climate sense.","whyCN":"拉丁动词意为把事物保持在适当尺度内，这一道德义与气候义并存至今。"},{"no":"04","title":"Moderate in amount","titleCN":"适度的：数量或程度不过分的","definition":"not excessive in amount, degree or force","definitionCN":"在数量、程度或力度上不过分的","example":"The report called for temperate use of antibiotics.","exampleCN":"报告呼吁适度使用抗生素。","why":"Keeping an amount within measure is the same restraint the adjective names in behaviour.","whyCN":"把数量保持在尺度内，与形容词在行为上所指的克制是同一件事。"},{"no":"05","title":"Temperate rainforest","titleCN":"温带雨林的：与温带多雨森林有关的","definition":"relating to the wet forest of cool temperate coasts","definitionCN":"与凉爽温带海岸的湿润森林有关的","example":"Temperate rainforest covers parts of the Pacific coast.","exampleCN":"温带雨林覆盖太平洋沿岸的部分地区。","why":"The forest grows where rain is ample but temperatures stay mild, joining the zone's two features.","whyCN":"这种森林生长在雨量充足而温度温和之处，把这条带的两个特征结合起来。"},{"no":"06","title":"Temperate phage","titleCN":"温和噬菌体的：可整合进宿主基因组的","definition":"describing a bacteriophage that can lie dormant inside a host genome","definitionCN":"描述能整合进宿主基因组并潜伏的噬菌体","example":"A temperate phage may remain silent for many generations.","exampleCN":"温和噬菌体可以沉默许多代。","why":"The virus does not immediately destroy the cell but holds its activity within bounds, which is why biologists borrowed 'temperate'.","whyCN":"这种病毒不立即摧毁细胞，而是把活动控制在限度内，生物学家因此借用了 temperate。"},{"no":"07","title":"Temperate latitudes","titleCN":"温带纬度的：中纬度地区的","definition":"relating to the mid-latitudes between tropical and polar regions","definitionCN":"与热带与极地之间的中纬度有关的","example":"Storms track across the temperate latitudes from west to east.","exampleCN":"风暴在温带纬度自西向东移动。","why":"The mid-latitudes are the temperate zone's projection onto the map.","whyCN":"中纬度就是温带在地图上的投影。"},{"no":"08","title":"Temperate in diet or habits","titleCN":"饮食起居有节的：生活有度的","definition":"moderate in eating, drinking or daily habits","definitionCN":"在饮食、饮酒或日常习惯上有节制的","example":"His temperate diet kept him healthy into old age.","exampleCN":"他有节制的饮食使他健康地活到老年。","why":"Daily moderation is due measure applied to the body.","whyCN":"日常节制就是把「适度」用于身体。"}],"etymology":{"intro":{"en":"Temperate comes from Latin temperatus 'moderated', the participle of temperare 'to mix in due proportion, regulate, restrain'. English uses it for both climate and character. Dates are approximate.","cn":"temperate 来自拉丁 temperatus「被调和的」，是 temperare「按适当比例调和、调节、约束」的分词；英语用它兼指气候与性格。年代均为约数。"},"items":[{"era":"LATIN TEMPERARE","en":"Temperare meant 'to mix in due proportion, regulate, restrain'. Its deeper origin is disputed; a link to tempus 'time' has been proposed but is not established.","cn":"temperare 意为「按适当比例调和、调节、约束」。其更深来源有争议；与 tempus「时间」的联系曾被提出，但未得到确立。"},{"era":"LATIN TEMPERATUS","en":"The participle temperatus meant 'moderated, kept within measure', and became the adjective for mildness and restraint.","cn":"分词 temperatus 意为「被调和的、被保持在尺度内的」，后来成为表示温和与克制的形容词。"},{"era":"ENGLISH","en":"English temperate appears in the sixteenth century for both bodily and moral moderation.","cn":"英语 temperate 在 16 世纪出现，兼指身体与道德上的节制。"},{"era":"GEOGRAPHY","en":"The temperate zone was named as the belt between the torrid and frigid extremes, a climate of due proportion.","cn":"温带被命名为位于炎热与严寒两端之间的地带，即比例适中的气候。"},{"era":"BIOLOGY","en":"Twentieth-century microbiology applied temperate to phages that remain dormant instead of destroying the host at once.","cn":"20 世纪微生物学把 temperate 用于不立即破坏宿主、而是潜伏的噬菌体。"},{"era":"UNCERTAIN ROOT","en":"Source uncertain: the derivation of temperare itself is not settled, and the proposed connection with tempus 'time' remains a hypothesis rather than an accepted etymology.","cn":"来源不确定：temperare 本身的来源尚无定论，所提出的与 tempus「时间」的联系仍属假说，未被普遍接受。"}]},"similar":{"note":{"en":"Group one holds words that look like temperate; group two holds words about mildness and restraint.","cn":"第一组是外形接近 temperate 的词；第二组是关于温和与克制的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"temperature","ipa":"/ˈtempərətʃə/","tag":"the noun of measure","definition":"The degree of heat or cold, built on the same root; it is a quantity, not a quality of climate.","definitionCN":"冷热程度，同出这一词根；它是量，不是气候性质。"},{"word":"tempered","ipa":"/ˈtempəd/","tag":"the participle","definition":"Adjusted or moderated, often of metal or of a person's disposition.","definitionCN":"经调整或缓和的，常用于金属或人的性情。"},{"word":"temperance","ipa":"/ˈtempərəns/","tag":"the abstract noun","definition":"Moderation, especially in drinking; it names the virtue rather than the climate.","definitionCN":"节制，尤指饮酒有度；它指美德而非气候。"},{"word":"intemperate","ipa":"/ɪnˈtempərət/","tag":"the negative","definition":"Without restraint, often of speech or weather; the in- reverses the moderation.","definitionCN":"无节制的，常指言语或天气；前缀 in- 反转了「有度」。"}]},{"heading":"NEAR MEANING","entries":[{"word":"mild","ipa":"/maɪld/","tag":"gentle weather","definition":"Not severe or extreme; it describes weather or manner without the zone meaning.","definitionCN":"不严酷、不极端；描述天气或态度，不含气候带义。"},{"word":"moderate","ipa":"/ˈmɒdərət/","tag":"not excessive","definition":"Kept within reasonable limits; it is the general word that temperate applies to climate and character.","definitionCN":"保持在合理限度内；它是 temperate 用于气候与性格时的一般同义词。"},{"word":"restrained","ipa":"/rɪˈstreɪnd/","tag":"held back","definition":"Controlled in expression or action; it stresses holding back rather than due proportion.","definitionCN":"在表达或行动上受控制；强调克制而非比例适中。"},{"word":"clement","ipa":"/ˈklemənt/","tag":"mild weather","definition":"Formally mild or merciful, used of weather and of judgement.","definitionCN":"正式指温和或宽厚的，用于天气与评判。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Latin 'due proportion', real climate zones and real microbiology, not invented rhymes.","cn":"正常联想：真实的拉丁「适当比例」、真实的气候带与真实的微生物学，而非编造的顺口溜。"},"normal":[{"en":"Temperare 'to mix in due proportion' gives temperate: kept within measure.","cn":"temperare「按适当比例调和」构成 temperate：被保持在尺度之内。"},{"en":"The temperate zone lies between the torrid and the frigid zones.","cn":"温带位于热带与寒带之间。"},{"en":"A temperate reply is restrained, not hot with anger.","cn":"temperate 的回答是克制的，不是怒火中烧的。"},{"en":"Temperate rainforest grows on cool, wet coasts.","cn":"温带雨林生长在凉爽湿润的海岸。"},{"en":"A temperate phage stays quiet inside its host.","cn":"温和噬菌体在宿主内保持沉默。"}],"abstract":[{"en":"Picture a thermostat set to the middle of its range.","cn":"想象一只恒温器被设在量程的中间。"},{"en":"Picture a person who answers an insult with a level voice.","cn":"想象一个人用平稳的语调回应侮辱。"},{"en":"Picture a table where every dish is served in a modest portion.","cn":"想象一桌菜，每道都只盛适中的一份。"}]},"examples":[{"en":"The region has a temperate climate with four distinct seasons.","cn":"该地区气候温和，四季分明。"},{"en":"She kept a temperate tone throughout the argument.","cn":"整场争论中她都保持克制的语气。"},{"en":"Temperate forests shed their leaves in autumn.","cn":"温带森林在秋天落叶。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"temper（调和、脾气）+ ate → 被调和过的 → 温和的、有节制的、温带的","word":"temperate"},"root":"拉丁 temperatus「被调和的」= temperare「按适当比例调和、约束」的分词；词根更深来源存疑，与 tempus「时间」的联系属假说。","sensesIntro":{"en":"Eight senses rest on 'kept within measure': the zone between hot and cold, its mild climate, restrained character, moderate amounts, the cool wet forest, a dormant virus, the mid-latitudes, and moderation in daily habits.","cn":"八个义项都建立在「保持在尺度内」：冷热之间的地带、温和气候、克制的性格、适中的数量、凉爽湿润的森林、潜伏的病毒、中纬度，以及日常习惯的节制。"},"semanticMap":{"core":{"en":"CORE IMAGE: a gauge resting in the middle of its scale, neither at the hot end nor the cold end.","cn":"核心意象：一根指针停在刻度中央，既不在热端，也不在冷端。"},"chain":["MIDDLE OF SCALE","MILD CLIMATE","MID-LATITUDES","RESTRAINT","MODERATE AMOUNT","DORMANT VIRUS"],"branches":[{"senses":"S1 · S7","en":"THE ZONE: the temperate belt and its mid-latitudes occupy the space between tropical and polar extremes.","cn":"地带：温带及其中纬度占据热带与极地两端之间的空间。"},{"senses":"S2 · S5","en":"CLIMATE AND FOREST: mildness supports the cool, wet temperate rainforest.","cn":"气候与森林：温和支撑凉爽湿润的温带雨林。"},{"senses":"S3 · S8","en":"CHARACTER: restraint in speech and moderation in diet are the same due measure applied to a person.","cn":"性格：言语克制与饮食有度，是同一「适度」用于人。"},{"senses":"S4","en":"AMOUNT: not excessive in quantity or force, the measure read as a number.","cn":"数量：数量或力度不过分，是同一尺度读作数字。"},{"senses":"S6","en":"BIOLOGY: a temperate phage holds its activity within bounds instead of destroying the host.","cn":"生物学：温和噬菌体把活动限制在限度内，而不摧毁宿主。"}]},"affixes":{"intro":{"en":"Temperate belongs to the Latin family of temperare 'to mix in due proportion', which also gives temper, temperament, temperature and temperance.","cn":"temperate 属于拉丁 temperare「按比例调和」的词族，同一词族还给出 temper、temperament、temperature 与 temperance。"},"latinIntro":{"en":"Latin temperare 'to regulate, mix' yields temperatus 'moderated', English temperate, and the nouns temperance and temperature; the deeper root of temperare is disputed.","cn":"拉丁 temperare「调节、调和」衍生 temperatus「被调和的」、英语 temperate，以及名词 temperance 与 temperature；temperare 的更深词根有争议。"},"items":[{"word":"temperare","structure":"temperare (Latin verb, first conjugation)","meaning":"to mix in proportion, regulate","meaningCN":"按比例调和；调节","example":"The verb names keeping things within measure.","exampleCN":"这个动词表示把事物保持在尺度内。"},{"word":"temperatus","structure":"temperatus, temperata, temperatum (participle/adjective)","meaning":"moderated, mild","meaningCN":"被调和的；温和的","example":"The participle became the English adjective.","exampleCN":"这个分词变成了英语形容词。"},{"word":"temperate","structure":"temperatus (through French)","meaning":"mild; restrained","meaningCN":"温和的；有节制的","example":"The coast has a temperate climate.","exampleCN":"海岸气候温和。"},{"word":"temperance","structure":"temperare + -ance (state)","meaning":"moderation","meaningCN":"节制","example":"He practised temperance in drink.","exampleCN":"他在饮酒上奉行节制。"},{"word":"temper","structure":"temperare (through Old English/French)","meaning":"to moderate; disposition","meaningCN":"使缓和；脾性","example":"She tempered her criticism with praise.","exampleCN":"她用赞扬缓和了批评。"},{"word":"temperament","structure":"temperamentum 'due mixture' + -ment","meaning":"natural disposition","meaningCN":"性情；气质","example":"His calm temperament suited the work.","exampleCN":"他沉静的性情适合这项工作。"},{"word":"temperature","structure":"temperatura 'due mixture' + -ure","meaning":"degree of heat","meaningCN":"温度","example":"The temperature fell below freezing.","exampleCN":"气温降到冰点以下。"},{"word":"intemperate","structure":"in- 'not' + temperate","meaning":"unrestrained","meaningCN":"无节制的","example":"His intemperate remarks caused offence.","exampleCN":"他无节制的言论冒犯了人。"},{"word":"tempera","structure":"Italian tempera, from temperare","meaning":"pigment mixed with egg","meaningCN":"蛋彩画颜料","example":"The panel was painted in tempera.","exampleCN":"这块画板是用蛋彩画的。"}],"latinEntries":[{"word":"temperare","structure":"temperare, temperavi, temperatum (verb, first conjugation)","meaning":"to mix, regulate, restrain","meaningCN":"调和；调节；约束"},{"word":"temperatus","structure":"temperatus, temperata, temperatum (participle)","meaning":"moderated, mild","meaningCN":"被调和的；温和的"},{"word":"temperantia","structure":"temperantia, temperantiae (f., first declension)","meaning":"moderation","meaningCN":"节制；适度"}]}},{"word":"arctic","ipa_uk":"/ˈɑːktɪk/","ipa_us":"/ˈɑːrktɪk/","definition_zh":"北极的；极冷的；北极地区","definition_en":"relating to the region around the North Pole, or extremely cold","core_image":"一片白色浮冰上立着帐篷，天边低垂的太阳把冰面照成淡蓝色","scene":"科考队在浮冰上扎营，四周全是白色。A research team sets up its camp on the drifting arctic ice.","sceneCN":"这里 arctic 指「属于北极地区的」（第 1 个义项：位于北极圈及其附近地带的）；句意为科考队在漂移的北极冰面上扎营。图中可辨识物件：浮冰、帐篷、雪橇、低垂的太阳。","pos":[{"tag":"adj.","zh":"北极的；极冷的"},{"tag":"n.","zh":"北极地区"}],"collocations":[{"phrase":"the Arctic Circle","zh":"北极圈"},{"phrase":"the Arctic Ocean","zh":"北冰洋"},{"phrase":"Arctic ice","zh":"北极冰盖"},{"phrase":"Arctic conditions","zh":"极地天气条件"},{"phrase":"Arctic wildlife","zh":"北极野生动物"},{"phrase":"the Arctic region","zh":"北极地区"}],"forms":[{"label":"专有名词（地区）","form":"the Arctic"},{"label":"比较级（极少用）","form":"more arctic"},{"label":"最高级（极少用）","form":"most arctic"},{"label":"副词（罕见）","form":"arctically"}],"derivatives":[{"word":"subarctic","pos":"adj.","zh":"亚北极的"},{"word":"Antarctic","pos":"adj./n.","zh":"南极的；南极地区"},{"word":"arctically","pos":"adv.","zh":"极地地（罕见）"},{"word":"Nearctic","pos":"adj./n.","zh":"新北界的；新北界（北美生物地理区）"}],"senses":[{"no":"01","title":"Of the Arctic region","titleCN":"北极的：属于北极地区及其周边的","definition":"relating to the region around the North Pole, including the Arctic Ocean and its coasts","definitionCN":"与北极周围地区有关的，包括北冰洋及其海岸","example":"Arctic ice has been shrinking for decades.","exampleCN":"北极冰面数十年来一直在缩小。","why":"The Greek adjective named the northern sky of the Bear, and the frozen region beneath it inherited the name.","whyCN":"希腊形容词命名熊座所在的北天，其下的冰封地区继承了这个名字。"},{"no":"02","title":"Extremely cold","titleCN":"极冷的：像北极一样严寒的","definition":"extremely cold, as the Arctic is","definitionCN":"像北极地区一样极其寒冷的","example":"An arctic wind closed the mountain road.","exampleCN":"一股极冷的风封住了山路。","why":"The Arctic is the coldest region on earth, so its name easily becomes a word for extreme cold.","whyCN":"北极是地球上最冷的地区，因此它的名字很容易变成「极冷」的说法。"},{"no":"03","title":"Of the Arctic Circle","titleCN":"北极圈的：与北极圈有关的","definition":"relating to the Arctic Circle, the parallel north of which the sun does not set in midsummer","definitionCN":"与北极圈有关，圈内地区仲夏太阳不落","example":"The village lies just south of the Arctic Circle.","exampleCN":"这个村子就在北极圈以南。","why":"The circle marks where the northern midnight sun begins, and the adjective names everything that belongs to it.","whyCN":"这条圈标出北方极昼开始之处，形容词则命名属于它的一切。"},{"no":"04","title":"The Arctic as a region","titleCN":"北极地区：把北极当作一个地方","definition":"the northern polar region taken as a whole","definitionCN":"整个北方极区","example":"Scientists wintered in the Arctic to study sea ice.","exampleCN":"科学家在北极越冬研究海冰。","why":"A proper noun can name the whole region that the adjective describes.","whyCN":"专有名词可以命名形容词所描述的全部地区。"},{"no":"05","title":"Of the Arctic Ocean","titleCN":"北冰洋的：与北冰洋有关的","definition":"relating to the Arctic Ocean, the smallest and shallowest of the world's oceans","definitionCN":"与世界上最小最浅的北冰洋有关的","example":"Icebreakers keep the Arctic Ocean open in summer.","exampleCN":"破冰船在夏季维持北冰洋的航道。","why":"The ocean lies under the pole, so it carries the region's name.","whyCN":"这片海洋位于极点之下，因此带着该地区的名字。"},{"no":"06","title":"Arctic wildlife","titleCN":"北极生物的：北极物种的","definition":"relating to the animals and plants of the Arctic, such as bears, seals and tundra plants","definitionCN":"与北极的熊、海豹与苔原植物等生物有关的","example":"Polar bears and seals are part of Arctic wildlife.","exampleCN":"北极熊与海豹属于北极野生动物。","why":"Animals and plants are named by the region they inhabit.","whyCN":"动植物按它们栖居的地区得名。"},{"no":"07","title":"Arctic conditions","titleCN":"极地条件的：严寒冰雪环境的","definition":"describing weather or conditions typical of the Arctic","definitionCN":"描述北极典型的天气或环境","example":"The crew trained for Arctic conditions before the expedition.","exampleCN":"探险前，队员针对极地条件进行了训练。","why":"Weather typical of the region becomes a general description of severe conditions.","whyCN":"该地区典型的天气，成为对严酷环境的一般描述。"},{"no":"08","title":"Northern, archaic","titleCN":"北方的：古义与天文用法中的北","definition":"an older or astronomical use meaning 'northern'","definitionCN":"较早的或天文学中表示「北方的」用法","example":"Early astronomers used arctic simply to mean northern.","exampleCN":"早期天文学家用 arctic 就表示「北方的」。","why":"Before it named a region, the word carried the plain sense 'northern' in astronomy.","whyCN":"在命名地区之前，这个词在天文学中只表示「北方的」。"}],"etymology":{"intro":{"en":"Arctic comes from Greek arktikos 'of the north', from arktos 'bear', because the northern sky is dominated by the Bear, Ursa Major. Latin arcticus passed it into English. Dates are approximate.","cn":"arctic 来自希腊 arktikos「北方的」，源于 arktos「熊」，因为北天由大熊座主导；拉丁 arcticus 把它传入英语。年代均为约数。"},"items":[{"era":"GREEK ARKTOS","en":"Arktos meant 'bear'; the constellation we call Ursa Major was the Bear, and it marked the north. The Indo-European form behind arktos is reconstructed, not recorded.","cn":"arktos 意为「熊」；我们称为大熊座的星座就是「熊」，它标示北方。arktos 背后的印欧语形式属重构，而非有记录。"},{"era":"GREEK ARKTIKOS","en":"Arktikos meant 'of the bear, of the north', because the Bear circles the northern pole.","cn":"arktikos 意为「熊的、北方的」，因为熊座绕北极旋转。"},{"era":"LATIN ARCTICUS","en":"Latin borrowed the adjective as arcticus, keeping the northern sense.","cn":"拉丁把这个形容词借作 arcticus，保留「北方」义。"},{"era":"ENGLISH","en":"English arctic appears in the fourteenth century, first as an astronomical and geographic term.","cn":"英语 arctic 在 14 世纪出现，最初是天文与地理术语。"},{"era":"EXPLORATION","en":"From the eighteenth and nineteenth centuries arctic named the region, its ice and its wildlife during polar exploration.","cn":"18 至 19 世纪的极地探险使 arctic 指该地区、其冰面与野生动物。"},{"era":"UNCERTAIN FIRST DATES","en":"Source uncertain (first dates only): the exact first English use of the 'extremely cold' sense is not recorded; the Greek 'bear' origin is well documented.","cn":"来源不确定（仅首见年代）：形容词「极冷」义在英语中的确切首见年代未见记录；希腊「熊」的来源有充分文献。"}]},"similar":{"note":{"en":"Group one holds words that look like arctic; group two holds words about polar cold and the north.","cn":"第一组是外形接近 arctic 的词；第二组是关于极地寒冷与北方的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"Antarctic","ipa":"/ænˈtɑːktɪk/","tag":"the opposite pole","definition":"Built with anti- 'opposite': the southern polar region, named as the reverse of the Arctic.","definitionCN":"由 anti-「相反」构成：南方的极区，作为北极的反面而得名。"},{"word":"attic","ipa":"/ˈætɪk/","tag":"room under the roof","definition":"The space just below a roof; it sounds similar but comes from a different architectural word.","definitionCN":"屋顶下方的空间；读音相近，但来自另一个建筑用词。"},{"word":"arc","ipa":"/ɑːk/","tag":"curve, not cold","definition":"A curved line or a spark of electricity; it shares letters but not meaning.","definitionCN":"曲线或电弧；共享字母而无意义关联。"},{"word":"arch","ipa":"/ɑːtʃ/","tag":"curved structure","definition":"A curved span or a mischievous manner; unrelated to the pole.","definitionCN":"弧形结构或顽皮的态度；与极无关。"}]},{"heading":"NEAR MEANING","entries":[{"word":"polar","ipa":"/ˈpəʊlə/","tag":"of either pole","definition":"Relating to either pole; arctic names only the northern one.","definitionCN":"与任一极有关；arctic 只指北方那一极。"},{"word":"frigid","ipa":"/ˈfrɪdʒɪd/","tag":"formally cold","definition":"Very cold, often of climate or manner; arctic adds the image of ice and bears.","definitionCN":"非常寒冷，常用于气候或态度；arctic 另带冰与熊的意象。"},{"word":"icy","ipa":"/ˈaɪsi/","tag":"covered in ice","definition":"Full of or covered with ice; it describes a surface, not a region.","definitionCN":"覆满冰的；描述表面，不指地区。"},{"word":"boreal","ipa":"/ˈbɔːriəl/","tag":"northern forest","definition":"Relating to the north or to the northern forest belt; a literary and ecological term.","definitionCN":"与北方或北方森林带有关；文学与生态学术语。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Greek bear, real polar geography and real exploration, not invented rhymes.","cn":"正常联想：真实的希腊「熊」、真实的极地地理与真实的探险史，而非编造的顺口溜。"},"normal":[{"en":"Arktos 'bear' + -ikos: the northern sky of the Bear, then the region beneath it.","cn":"arktos「熊」+ -ikos：熊座所在的北天，再指它下方的地区。"},{"en":"The Arctic Circle marks where the midsummer sun does not set.","cn":"北极圈标出仲夏太阳不落的地方。"},{"en":"Arctic ice, Arctic Ocean and Arctic wildlife are fixed geographic phrases.","cn":"Arctic ice、Arctic Ocean 与 Arctic wildlife 都是固定地理搭配。"},{"en":"Antarctic adds anti- 'opposite' to the same root, naming the south.","cn":"Antarctic 在同一词根前加 anti-「相反」，命名南方。"},{"en":"An arctic wind is a metaphor for extreme cold.","cn":"arctic wind 是极度寒冷的比喻。"}],"abstract":[{"en":"Picture a bear circling slowly around a fixed point in the sky.","cn":"想象一头熊绕天空中一个固定点缓慢转圈。"},{"en":"Picture a white plain where the sun merely grazes the horizon.","cn":"想象一片白色平原，太阳只擦着地平线。"},{"en":"Picture a freezer door opening into a summer street.","cn":"想象一扇冷冻库的门在夏日街道上打开。"}]},"examples":[{"en":"The Arctic Ocean is covered by drifting sea ice.","cn":"北冰洋被漂移的海冰覆盖。"},{"en":"Arctic temperatures can fall below minus forty.","cn":"北极气温可降到零下四十度以下。"},{"en":"Few plants survive in the arctic tundra.","cn":"能在北极苔原存活的植物很少。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"arctic 与「熊」有关：希腊 arktos 是熊，熊座在北天 → 北极的、极冷的","word":"arctic"},"root":"希腊 arktikos「北方的」= arktos「熊」+ -ikos，因大熊座标示北方；拉丁 arcticus，英语 14 世纪借入。","sensesIntro":{"en":"Eight senses radiate from the northern Bear: the region, its extreme cold, the circle, the region as a noun, its ocean, its wildlife, its weather, and the older astronomical sense 'northern'.","cn":"八个义项从北天的熊辐射开来：北极地区、极端的寒冷、北极圈、作为名词的地区、北冰洋、极地生物、极地天气，以及较早的「北方」天文义。"},"semanticMap":{"core":{"en":"CORE IMAGE: the Bear constellation circling the northern pole, and the white frozen region beneath it.","cn":"核心意象：绕北极旋转的熊座，以及其下的白色冰封地区。"},"chain":["BEAR","NORTH","ICE REGION","ARCTIC CIRCLE","OCEAN","EXTREME COLD"],"branches":[{"senses":"S1 · S4","en":"THE REGION: the place around the northern pole, whether described or named.","cn":"地区：北方极地周围的地带，无论描述还是命名。"},{"senses":"S2 · S7","en":"COLD: extreme cold and arctic weather are the region's climate turned into a description.","cn":"寒冷：极端寒冷与极地天气，是地区气候转为描述。"},{"senses":"S3","en":"THE CIRCLE: the parallel where the midnight sun begins.","cn":"圈：极昼开始的那条纬线。"},{"senses":"S5 · S6","en":"LIFE AND SEA: the Arctic Ocean and the wildlife adapted to it.","cn":"生命与海：北冰洋及适应它的野生动物。"},{"senses":"S8","en":"OLD NORTH: the astronomical sense simply means northern.","cn":"旧义北方：天文义就是「北方的」。"}]},"affixes":{"intro":{"en":"Arctic is built on the Greek word for bear plus an adjective ending; the same root with anti- makes Antarctic.","cn":"arctic 由希腊「熊」加形容词后缀构成；同一词根加 anti- 构成 Antarctic。"},"latinIntro":{"en":"Greek arktos 'bear' gives arktikos 'northern', Latin arcticus 'northern', English arctic; anti- plus the same root gives antarktikos and Antarctic.","cn":"希腊 arktos「熊」衍生 arktikos「北方的」、拉丁 arcticus「北方的」与英语 arctic；anti- 加同一词根构成 antarktikos 与 Antarctic。"},"items":[{"word":"arktos","structure":"arktos (Greek noun, 'bear')","meaning":"bear","meaningCN":"熊","example":"The constellation gave its name to the north.","exampleCN":"这个星座把名字给了北方。"},{"word":"arktikos","structure":"arktikos (Greek adjective, 'of the north')","meaning":"northern","meaningCN":"北方的","example":"The adjective named the northern region.","exampleCN":"这个形容词命名北方地区。"},{"word":"arcticus","structure":"arcticus (Latin adjective)","meaning":"northern","meaningCN":"北方的","example":"Latin passed the word to English.","exampleCN":"拉丁把这个词传给英语。"},{"word":"arctic","structure":"arcticus (through French)","meaning":"of the Arctic","meaningCN":"北极的","example":"Arctic winds froze the lake.","exampleCN":"北极风把湖面冻住。"},{"word":"Arctic","structure":"arctic (capitalised proper noun)","meaning":"the northern polar region","meaningCN":"北极地区","example":"The Arctic is warming faster than other regions.","exampleCN":"北极地区变暖快于其它地区。"},{"word":"subarctic","structure":"sub- 'near' + arctic","meaning":"nearly arctic","meaningCN":"亚北极的","example":"Subarctic forests grade into tundra.","exampleCN":"亚北极森林逐渐过渡为苔原。"},{"word":"Antarctic","structure":"anti- 'opposite' + arctic","meaning":"the opposite pole","meaningCN":"南极的","example":"The Antarctic is colder than the Arctic.","exampleCN":"南极比北极更冷。"},{"word":"arctically","structure":"arctic + -ally (adverb)","meaning":"in an arctic way","meaningCN":"极地地（罕见）","example":"The wind blew arctically all night.","exampleCN":"整夜风都冷得像极地。"},{"word":"arctic-alpine","structure":"arctic + alpine","meaning":"of cold mountain and polar habitats","meaningCN":"北极高山生的","example":"Arctic-alpine plants grow on exposed ridges.","exampleCN":"北极高山植物长在裸露的山脊上。"}],"latinEntries":[{"word":"arcticus","structure":"arcticus, arctica, arcticum (adjective)","meaning":"northern, of the north","meaningCN":"北方的"},{"word":"arctos","structure":"arctos, arcti (m., second declension, from Greek)","meaning":"bear; the northern constellation","meaningCN":"熊；北方星座"},{"word":"septentrionalis","structure":"septentrionalis, septentrionale (adjective)","meaning":"northern","meaningCN":"北方的"}]}},{"word":"antarctic","ipa_uk":"/ænˈtɑːktɪk/","ipa_us":"/ænˈtɑːrktɪk/","definition_zh":"南极的；南极地区的","definition_en":"relating to the region around the South Pole, opposite the Arctic","core_image":"企鹅站在一望无际的冰盖上，远处是低矮的雪原与灰白色的天","scene":"企鹅聚在冰盖上，风扫过空旷的雪原。Penguins gather on the antarctic ice while the wind sweeps the plain.","sceneCN":"这里 antarctic 指「属于南极地区的」（第 1 个义项：位于南极圈及其附近地带的）；句意为企鹅聚在南极冰面上，风扫过空旷雪原。图中可辨识物件：企鹅、冰盖、雪原、风暴云。","pos":[{"tag":"adj.","zh":"南极的；南极地区的"},{"tag":"n.","zh":"南极地区"}],"collocations":[{"phrase":"the Antarctic Circle","zh":"南极圈"},{"phrase":"the Antarctic continent","zh":"南极大陆"},{"phrase":"the Antarctic Ocean","zh":"南大洋"},{"phrase":"Antarctic ice","zh":"南极冰盖"},{"phrase":"Antarctic wildlife","zh":"南极野生动物"},{"phrase":"the Antarctic region","zh":"南极地区"}],"forms":[{"label":"专有名词（地区）","form":"the Antarctic"},{"label":"专有名词（大陆）","form":"Antarctica"},{"label":"副词（罕见）","form":"antarctically"}],"derivatives":[{"word":"Antarctica","pos":"n.","zh":"南极洲"},{"word":"subantarctic","pos":"adj.","zh":"亚南极的"},{"word":"antarctically","pos":"adv.","zh":"南极地（罕见）"}],"senses":[{"no":"01","title":"Of the Antarctic region","titleCN":"南极的：属于南极地区及其周边的","definition":"relating to the region around the South Pole, including the continent, ice shelves and surrounding ocean","definitionCN":"与南极周围地区有关的，包括大陆、冰架与周围海洋","example":"Antarctic ice holds most of the world's fresh water.","exampleCN":"南极冰盖储存着世界大部分淡水。","why":"The adjective names everything that belongs to the southern region opposite the Arctic.","whyCN":"这个形容词命名属于与北极相对之南方地区的一切。"},{"no":"02","title":"Of the Antarctic Circle","titleCN":"南极圈的：与南极圈有关的","definition":"relating to the Antarctic Circle, the parallel south of which the midsummer sun does not set","definitionCN":"与南极圈有关，圈内地区仲夏太阳不落","example":"The Antarctic Circle lies at about sixty-six and a half degrees south.","exampleCN":"南极圈约位于南纬六十六度半。","why":"The circle marks the southern limit of the midnight sun, named like its northern counterpart.","whyCN":"这条圈标出南方极昼的界限，命名方式与北方的对应圈相同。"},{"no":"03","title":"The Antarctic as a region","titleCN":"南极地区：把南极当作一个地方","definition":"the southern polar region taken as a whole","definitionCN":"整个南方极区","example":"Few people winter in the Antarctic.","exampleCN":"很少有人在南极越冬。","why":"The region can be named as a whole with a proper noun, just as the Arctic is.","whyCN":"这一地区可用专有名词整体命名，与北极相同。"},{"no":"04","title":"Of the Antarctic continent","titleCN":"南极大陆的：与南极洲陆地有关的","definition":"relating to the continent of Antarctica","definitionCN":"与南极洲这块陆地有关的","example":"The Antarctic continent is almost entirely covered by ice.","exampleCN":"南极大陆几乎完全被冰覆盖。","why":"The continent is the region's landmass, so it takes the same adjective.","whyCN":"这块大陆是该地区的陆体，因此使用同一个形容词。"},{"no":"05","title":"Of the Antarctic Ocean","titleCN":"南大洋的：与南极周围海域有关的","definition":"relating to the ocean surrounding the Antarctic continent","definitionCN":"与环绕南极大陆的海洋有关的","example":"The Antarctic Ocean carries cold currents northward.","exampleCN":"南大洋把冷流带向北方。","why":"The surrounding sea carries the name of the continent it encircles.","whyCN":"环绕的海域带着它所包围的大陆之名。"},{"no":"06","title":"Antarctic climate and ice","titleCN":"南极气候与冰盖的：极寒冰雪环境的","definition":"describing the extremely cold climate and ice of the Antarctic","definitionCN":"描述南极极寒气候与冰面的","example":"Antarctic temperatures fell below minus sixty.","exampleCN":"南极气温降到零下六十度以下。","why":"Climate and ice are the region's defining physical features.","whyCN":"气候与冰是该地区最典型的物理特征。"},{"no":"07","title":"Antarctic wildlife","titleCN":"南极生物的：南极物种的","definition":"relating to the animals of the Antarctic, such as penguins, seals and krill","definitionCN":"与企鹅、海豹与磷虾等南极动物有关的","example":"Penguins gather on the antarctic ice while the wind sweeps the plain.","exampleCN":"企鹅聚在南极冰面上，风扫过空旷雪原。","why":"Wildlife is named by the region it inhabits.","whyCN":"野生动物按它们栖息的地区得名。"},{"no":"08","title":"Literally opposite the north","titleCN":"与北极相对的：字面上与北方相反","definition":"the etymological sense 'opposite the north', from anti- plus arctic","definitionCN":"词源上的「与北方相对」，由 anti- 加 arctic 构成","example":"The name Antarctic literally means the opposite of the north.","exampleCN":"Antarctic 这个名字字面上就是「与北方相对」。","why":"The word is literally anti- plus arctic, so the etymological sense is still readable in its parts.","whyCN":"这个词字面就是 anti- 加 arctic，因此词源义仍能从各部分读出。"}],"etymology":{"intro":{"en":"Antarctic is Greek antarktikos, 'opposite the north', from anti- 'opposite' and arktikos 'of the north', itself from arktos 'bear'. Latin antarcticus passed it into English. Dates are approximate.","cn":"antarctic 是希腊 antarktikos「与北方相对的」，由 anti-「相反」与 arktikos「北方的」（源于 arktos「熊」）构成；拉丁 antarcticus 传入英语。年代均为约数。"},"items":[{"era":"GREEK ANTI","en":"Anti- meant 'opposite, against'; it marks the south as the reverse of the north.","cn":"anti- 意为「相反、对着」；它把南方标为北方的反面。"},{"era":"GREEK ARKTIKOS","en":"Arktikos 'of the north' came from arktos 'bear', the constellation that circles the northern pole.","cn":"arktikos「北方的」来自 arktos「熊」，即绕北极旋转的星座。"},{"era":"GREEK ANTARKTIKOS","en":"Antarktikos meant 'opposite the Bear, opposite the north', and named the unknown southern region.","cn":"antarktikos 意为「与熊相对的、与北方相对的」，命名当时未知的南方地区。"},{"era":"LATIN ANTARCTICUS","en":"Latin borrowed the adjective as antarcticus, keeping the sense 'southern, opposite the north'.","cn":"拉丁把这个形容词借作 antarcticus，保留「南方的、与北方相对」之义。"},{"era":"ENGLISH","en":"English antarctic appears in the sixteenth century; Antarctica as the continent's name is a nineteenth-century formation.","cn":"英语 antarctic 在 16 世纪出现；Antarctica 作为大陆名称是 19 世纪形成的。"},{"era":"UNCERTAIN FIRST DATES","en":"Source uncertain (first dates only): the exact first English use of the continental and ocean senses is not recorded; the Greek elements are certain.","cn":"来源不确定（仅首见年代）：大陆义与海洋义在英语中的确切首见年代未见记录；希腊成分可靠。"}]},"similar":{"note":{"en":"Group one holds words that look like antarctic; group two holds southern and polar words.","cn":"第一组是外形接近 antarctic 的词；第二组是关于南方与极地的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"arctic","ipa":"/ˈɑːktɪk/","tag":"the opposite pole","definition":"The northern counterpart, without the prefix anti-; antarctic is literally 'opposite the arctic'.","definitionCN":"没有 anti- 前缀的北方对应词；antarctic 字面就是「与北极相对」。"},{"word":"Atlantic","ipa":"/ətˈlæntɪk/","tag":"ocean name","definition":"The ocean between Europe and America, named after Atlas; it shares the ending, not the root.","definitionCN":"欧美之间的海洋，得名于阿特拉斯；共享词尾而非词根。"},{"word":"attic","ipa":"/ˈætɪk/","tag":"room, not pole","definition":"A space under the roof; it sounds close but belongs to architecture.","definitionCN":"屋顶下的空间；读音接近，但属建筑用词。"},{"word":"arc","ipa":"/ɑːk/","tag":"curve","definition":"A curve or electrical spark; no connection to the pole.","definitionCN":"曲线或电火花；与极无关。"}]},{"heading":"NEAR MEANING","entries":[{"word":"polar","ipa":"/ˈpəʊlə/","tag":"of either pole","definition":"Relating to either pole; antarctic names only the southern one.","definitionCN":"与任一极有关；antarctic 只指南方那一极。"},{"word":"southern","ipa":"/ˈsuːðən/","tag":"direction word","definition":"Simply located to the south; it lacks the ice, wildlife and treaty associations of antarctic.","definitionCN":"只表示位于南方；缺少 antarctic 的冰、野生动物与条约联想。"},{"word":"frigid","ipa":"/ˈfrɪdʒɪd/","tag":"very cold","definition":"Formally very cold, often of climate; antarctic adds the image of the ice sheet.","definitionCN":"正式表示极冷，常用于气候；antarctic 另带冰盖意象。"},{"word":"austral","ipa":"/ˈɔːstrəl/","tag":"southern, literary","definition":"A formal or literary word for southern, from Latin australis.","definitionCN":"正式或文学的「南方的」，来自拉丁 australis。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real anti- prefix, the real Bear constellation and real polar geography, not invented rhymes.","cn":"正常联想：真实的 anti- 前缀、真实的熊座与真实的极地地理，而非编造的顺口溜。"},"normal":[{"en":"Anti- 'opposite' + arctic: the region opposite the northern Bear.","cn":"anti-「相反」+ arctic：与北方熊座相对的地区。"},{"en":"Arctic is north; Antarctic is south; Antarctica is the continent.","cn":"Arctic 是北，Antarctic 是南，Antarctica 是那块大陆。"},{"en":"The Antarctic Circle marks where the midsummer sun stays up all night.","cn":"南极圈标出仲夏太阳整夜不落的地方。"},{"en":"Penguins, seals and krill are the Antarctic's best-known wildlife.","cn":"企鹅、海豹与磷虾是南极最著名的野生动物。"},{"en":"The Antarctic ice sheet stores most of the world's fresh water.","cn":"南极冰盖储存着世界大部分淡水。"}],"abstract":[{"en":"Picture a mirror image of a bear, standing upside down in the southern sky.","cn":"想象熊的镜像倒立在南方天空。"},{"en":"Picture a continent shaped like a broken plate of ice.","cn":"想象一块像碎冰盘的大陆。"},{"en":"Picture a place where the sun sets once a year and rises once a year.","cn":"想象一个地方，太阳一年只落一次、升一次。"}]},"examples":[{"en":"The Antarctic continent is larger than Europe.","cn":"南极大陆比欧洲大。"},{"en":"Antarctic ice cores record ancient climates.","cn":"南极冰芯记录着古代气候。"},{"en":"The Antarctic Circle crosses several southern oceans.","cn":"南极圈穿过几个南部海洋。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"anti（相反）+ arctic（北极的）→ 与北极相对 → 南极的","word":"antarctic"},"root":"希腊 antarktikos「与北方相对的」= anti-（相反）+ arktikos（北方的，源于 arktos「熊」）；拉丁 antarcticus，英语 16 世纪借入。","sensesIntro":{"en":"Eight senses all hang on 'opposite the north': the southern region, its circle, the region as a noun, the continent, its ocean, its climate and ice, its wildlife, and the literal etymological sense.","cn":"八个义项都围绕「与北方相对」：南方地区、南极圈、作为名词的地区、南极大陆、南大洋、气候与冰盖、野生动物，以及字面的词源义。"},"semanticMap":{"core":{"en":"CORE IMAGE: the mirror image of the northern Bear, a white southern continent under a low sun.","cn":"核心意象：北方熊座的镜像，一片低垂太阳下的白色南方大陆。"},"chain":["ANTI-NORTH","SOUTHERN REGION","ICE CONTINENT","ANTARCTIC CIRCLE","OCEAN","WILDLIFE"],"branches":[{"senses":"S1 · S3 · S8","en":"THE OPPOSITE: the southern region is defined as the reverse of the north.","cn":"相对：南方地区被定义为北方的反面。"},{"senses":"S2","en":"THE CIRCLE: the parallel where the southern midsummer sun does not set.","cn":"圈：南方仲夏太阳不落的纬线。"},{"senses":"S4 · S6","en":"THE CONTINENT AND ITS ICE: land almost entirely buried under ice, with a climate to match.","cn":"大陆与冰：几乎全被冰埋没的陆地，以及与之相配的气候。"},{"senses":"S5","en":"THE OCEAN: the sea that surrounds the continent.","cn":"海洋：环绕大陆的海。"},{"senses":"S7","en":"LIFE: penguins, seals and krill are the region's visible inhabitants.","cn":"生命：企鹅、海豹与磷虾是该地区可见的居民。"}]},"affixes":{"intro":{"en":"Antarctic is anti- plus arctic, so its parts can be read directly: 'opposite the northern Bear'.","cn":"antarctic 是 anti- 加 arctic，各部分可直接读出：「与北方的熊相对」。"},"latinIntro":{"en":"Greek anti- 'opposite' and arktikos 'northern' combine in antarktikos; Latin antarcticus passes the compound to English, and Antarctica is its continental name.","cn":"希腊 anti-「相反」与 arktikos「北方的」组合成 antarktikos；拉丁 antarcticus 把这个复合词传给英语，Antarctica 是其大陆名称。"},"items":[{"word":"anti-","structure":"anti- (Greek prefix, 'opposite')","meaning":"opposite","meaningCN":"相反；对抗","example":"The prefix turns the north into its opposite.","exampleCN":"这个前缀把北方变成它的反面。"},{"word":"arktikos","structure":"arktikos (Greek adjective, 'of the north')","meaning":"northern","meaningCN":"北方的","example":"The second element names the north.","exampleCN":"第二个成分命名北方。"},{"word":"antarktikos","structure":"antarktikos (Greek adjective)","meaning":"opposite the north","meaningCN":"与北方相对的","example":"The Greek word named the unknown south.","exampleCN":"这个希腊词命名当时未知的南方。"},{"word":"antarcticus","structure":"antarcticus (Latin adjective)","meaning":"southern, opposite the north","meaningCN":"南方的；与北方相对的","example":"Latin kept the Greek compound.","exampleCN":"拉丁保留了这个希腊复合词。"},{"word":"antarctic","structure":"antarcticus (through French)","meaning":"of the South Pole region","meaningCN":"南极的","example":"Antarctic winds are fierce.","exampleCN":"南极风很猛烈。"},{"word":"Antarctica","structure":"antarctic + -a (place name)","meaning":"the southern continent","meaningCN":"南极洲","example":"Antarctica is almost all ice.","exampleCN":"南极洲几乎全是冰。"},{"word":"subantarctic","structure":"sub- 'near' + antarctic","meaning":"nearly antarctic","meaningCN":"亚南极的","example":"Subantarctic islands lie north of the circle.","exampleCN":"亚南极群岛位于南极圈以北。"},{"word":"antarctically","structure":"antarctic + -ally (adverb)","meaning":"in an antarctic way","meaningCN":"南极地（罕见）","example":"The station was antarctically cold.","exampleCN":"这座站冷得像南极。"},{"word":"arctic","structure":"arktikos (without anti-)","meaning":"northern","meaningCN":"北极的","example":"The two words are a matched pair.","exampleCN":"这两个词是一对对应词。"}],"latinEntries":[{"word":"antarcticus","structure":"antarcticus, antarctica, antarcticum (adjective)","meaning":"southern, opposite the north","meaningCN":"南方的；与北方相对的"},{"word":"arcticus","structure":"arcticus, arctica, arcticum (adjective)","meaning":"northern","meaningCN":"北方的"},{"word":"anti","structure":"anti (Greek preposition and prefix, used in Latin)","meaning":"opposite, against","meaningCN":"相反；对抗"}]}}]);
